function Startup:Mark(stage)
    self.Stage = stage
    self.Lines[#self.Lines + 1] = string.format("%.3f %s", os.clock() - self.Started, stage)
    if #self.Lines > 48 then table.remove(self.Lines, 1) end
    if type(writefile) == "function" then
        pcall(function()
            if type(makefolder) == "function" and (type(isfolder) ~= "function" or not isfolder("MenuSettings")) then
                pcall(makefolder, "MenuSettings")
            end
            writefile(self.Path, "Notification Nova startup diagnostics v6\n" .. table.concat(self.Lines, "\n") .. "\n")
        end)
    end
end
Startup:Mark("script.enter")

Startup:Mark("previous-session.cleanup")
for _, name in ipairs({"__NotificationNova", "__SettingsOnlyMenu", "__" .. previousBrand .. "Nova"}) do
