else generated.Box:CaptureFocus(); status:SetText("Select and copy the key manually.") end end }) local incoming = section:Input({ Text = "Config key", Placeholder = "XXXX-XXXX-XXXX-XXXX", Width = 190 }) section:Button({ Text = "Activate config", Icon = "download", Style = "Primary", Callback = function()
