-- Platform: Roblox Luau; target: Notification Nova Hit Sound display names.
-- Asset names verified against the public Roblox economy API on 2026-10-15.
-- Keep the numeric indices stable: saved HitSoundMode values are 1 through 6.
local HitSoundCatalog = {
    {value = 1, id = 140604838213617, label = "hit sound fist 0", name = "hit sound fist 0"},
    {value = 2, id = 130201387574815, label = "DING", name = "DING"},
    {value = 3, id = 135478009117226, label = "Minecraft Bow Hit Ding", name = "Minecraft Sound Successful Bow Hit Ding"},
    {value = 4, id = 96735711388006, label = "Deagle 1", name = "Deagle 1"},
    {value = 5, id = 126048302910782, label = "Slap", name = "Slap"},
    {value = 6, id = 7255642553, label = "Mania's KeySound - Softhit", name = "Mania's KeySound - Softhit"},
}

local function GetHitSoundOptions()
    local options = {}
    for _, sound in ipairs(HitSoundCatalog) do
        table.insert(options, {value = sound.value, label = sound.label})
    end
    return options
end


