function PlaceSupport.Normalize(values)
    if not PlaceSupport.Viewmodel then
        values.BridgeViewmodelEnabled, values.BridgeViewmodelEnabledBind = false, "None"
    end
    if not PlaceSupport.NoCamRotate then
        values.KillAuraNoCamRotation, values.KillAuraNoCamRotationBind = false, "None"
    end
end

-- Hide unsupported controls before creating sections or registering keybinds.
for index = #FeatureSchema, 1, -1 do
    local feature = FeatureSchema[index]
    if feature.Key == "BridgeViewmodelEnabled" and not PlaceSupport.Viewmodel then
        table.remove(FeatureSchema, index)
    else
        for optionIndex = #feature.Options, 1, -1 do
            if feature.Options[optionIndex].Key == "KillAuraNoCamRotation" and not PlaceSupport.NoCamRotate then
                table.remove(feature.Options, optionIndex)
            end
        end
    end
end

local function StartNotification(window)
    local Session = {
        Alive = true, Ready = false, Connections = {}, CharacterConnections = {}, Overrides = {},
        AntiFlingParts = setmetatable({}, {__mode = "k"}),
        AnimationSpeeds = setmetatable({}, {__mode = "k"}),
        ArmTransparency = setmetatable({}, {__mode = "k"}),
        RenderName = "Notification_Nova_Render",
    }
    Session.Effects = Instance.new("Folder")
    Session.Effects.Name = "Notification_Nova_Effects"
    Session.Effects.Parent = workspace

    function Session:Connect(signal, callback, bucket)
        local connection = signal:Connect(function(...)
            if self.Alive then callback(...) end
        end)
        table.insert(bucket or self.Connections, connection)
        return connection
    end

    function Session:Release(owner)
        local entry = self.Overrides[owner]
        if not entry then return end
        self.Overrides[owner] = nil
        -- Camera zoom limits are ordered to avoid clamping the restored minimum.
        if entry.Values.CameraMaxZoomDistance then
            pcall(function() entry.Instance.CameraMaxZoomDistance = entry.Values.CameraMaxZoomDistance end)
        end
        for property, value in pairs(entry.Values) do
            pcall(function() entry.Instance[property] = value end)
        end
    end

    function Session:Override(owner, instance, values)
        local entry = self.Overrides[owner]
        if entry and entry.Instance ~= instance then self:Release(owner); entry = nil end
        if not entry then
            entry = {Instance = instance, Values = {}}
            for property in pairs(values) do entry.Values[property] = instance[property] end
            self.Overrides[owner] = entry
        end
        if values.CameraMaxZoomDistance then instance.CameraMaxZoomDistance = values.CameraMaxZoomDistance end
        for property, value in pairs(values) do
            if instance[property] ~= value then instance[property] = value end
        end
    end

    function Session:RestoreAntiFling()
        for part, value in pairs(self.AntiFlingParts) do
            if part.Parent then pcall(function() part.CanCollide = value end) end
        end
        table.clear(self.AntiFlingParts)
    end

    function Session:RestoreAnimations()
        for track, speed in pairs(self.AnimationSpeeds) do
            pcall(function() track:AdjustSpeed(speed) end)
        end
        table.clear(self.AnimationSpeeds)
    end

    function Session:RestoreArms()
        for part, transparency in pairs(self.ArmTransparency) do
            if part.Parent then pcall(function() part.LocalTransparencyModifier = transparency end) end
        end
        table.clear(self.ArmTransparency)
    end

