    local listeners = {}
    local characters = setmetatable({}, {__mode = "k"})
    Session.FriendPlayers = setmetatable({}, {__mode = "k"})
    Session.Players = Players
    local function identity(value)
        if typeof(value) == "Instance" and value:IsA("Player") then value = value.UserId end
        if type(value) == "string" then
            if not value:match("^%-?%d+$") then return nil end
            value = tonumber(value)
        end
        if type(value) ~= "number" or value ~= value or value == 0 or math.abs(value) > 1e12 or value % 1 ~= 0 then return nil end
        return tostring(value), value
    end
    function Session:ValidateFriends(value)
        if type(value) ~= "table" then return nil, "Invalid friends list." end
        local copy, count = {}, 0
        for key, entry in pairs(value) do
            count += 1
            if count > 256 then return nil, "The friends list is limited to 256 players." end
            local canonical, id = identity(key)
            if type(key) ~= "string" or canonical ~= key or type(entry) ~= "table"
                or entry.UserId ~= id or id == LocalPlayer.UserId then return nil, "Invalid friend UserId." end
            if type(entry.Name) ~= "string" or #entry.Name == 0 or #entry.Name > 100
                or type(entry.DisplayName) ~= "string" or #entry.DisplayName > 256 then return nil, "Invalid friend name." end
            for field in pairs(entry) do
                if field ~= "UserId" and field ~= "Name" and field ~= "DisplayName" then return nil, "Invalid friend record." end
            end
            copy[key] = {UserId=id, Name=entry.Name, DisplayName=entry.DisplayName}
        end
        return copy
    end
    function Session:CopyFriends()
        local copy = {}
        for id, entry in pairs(Cfg.Friends) do copy[id] = table.clone(entry) end
        return copy
    end
    function Session:IsFriend(value)
        local key = identity(value)
        return key ~= nil and Cfg.Friends[key] ~= nil
    end
    function Session:CharacterUserId(character)
        if not character then return nil end
        local id = characters[character]
        if id then return id end
        local owner = Players:GetPlayerFromCharacter(character)
        if owner then characters[character] = owner.UserId; return owner.UserId end
        return nil
    end
    function Session:IsFriendCharacter(character)
        return self:IsFriend(self:CharacterUserId(character))
    end
    function Session:GetFriends()
        local entries = {}
        for _, entry in pairs(Cfg.Friends) do table.insert(entries, table.clone(entry)) end
        table.sort(entries, function(a, b)
            local left, right = a.Name:lower(), b.Name:lower()
            return left == right and a.UserId < b.UserId or left < right
        end)
        return entries
    end
    function Session:OnFriendsChanged(callback)
        local connection = {Connected=true}
        listeners[connection] = callback
        function connection:Disconnect() self.Connected = false; listeners[self] = nil end
        return connection
    end
    function Session:FriendsChanged()
        if not self.Alive then return end
        table.clear(self.FriendPlayers)
        for _, player in ipairs(Players:GetPlayers()) do
            if self:IsFriend(player) then self.FriendPlayers[player] = true end
        end
        if self.ApplyFriendExclusions then self:ApplyFriendExclusions() end
        for connection, callback in pairs(listeners) do
            if connection.Connected then callback() end
        end
    end
    function Session:AddFriend(player)
        if not self.Alive then return false, "Session is closed." end
        if typeof(player) ~= "Instance" or not player:IsA("Player") or player == LocalPlayer
            or player.Parent ~= Players then return false, "Select a player who is on this server." end
        local id, number = identity(player)
        if not id or number == LocalPlayer.UserId then return false, "Invalid player." end
        if Cfg.Friends[id] then return false, "This player is already a friend." end
        local friends = self:CopyFriends()
        friends[id] = {UserId=number, Name=player.Name, DisplayName=player.DisplayName}
        local valid, message = self:ValidateFriends(friends)
        if not valid then return false, message end
        Cfg.Friends = valid
        if player.Character then characters[player.Character] = number end
        self:Changed("Friends")
        if self.Save then self:Save() end
        return true
    end
    function Session:RemoveFriend(value)
        if not self.Alive then return false end
        local id = identity(value)
        if not id or not Cfg.Friends[id] then return false end
        local friends = self:CopyFriends()
        friends[id] = nil
        Cfg.Friends = friends
        self:Changed("Friends")
        if self.Save then self:Save() end
        return true
    end
    function Session:DestroyFriends()
        for connection in pairs(listeners) do connection.Connected = false end
        table.clear(listeners)
        table.clear(characters)
        table.clear(self.FriendPlayers)
    end
    Session:Connect(Players.PlayerAdded, function(player)
        if Session:IsFriend(player) then Session.FriendPlayers[player] = true end
    end)
    Session:Connect(Players.PlayerRemoving, function(player) Session.FriendPlayers[player] = nil end)
end
-- End script friends model.


Session.Cfg = Cfg
Session.PlaceSupport = PlaceSupport
PlaceSupport.Normalize(Cfg)
Session.Defaults = table.clone(Cfg)
Session.ToggleKeys = {}
for _, feature in ipairs(FeatureSchema) do
    Session.ToggleKeys[feature.Key] = feature.Name
    for _, option in ipairs(feature.Options) do
        if option.Kind == "Toggle" then Session.ToggleKeys[option.Key] = feature.Name .. " / " .. option.Name end
    end
end
for key in pairs(Session.ToggleKeys) do
    Cfg[key .. "Bind"] = Cfg[key .. "Bind"] or "None"
    Session.Defaults[key .. "Bind"] = Cfg[key .. "Bind"]
end

local function SaveLocalMAIN()
    if Session.Alive and Session.Save then Session:Save() end
end


-- Platform: Roblox client / Luau; target: aim reads isolated from camera rendering and collision.
-- No Cam Rotate owns activation; disabling it detaches this session from the native callbacks.
do
    local VERSION = 5
    local profile = Session.PlaceSupport.NoCamRotate
    local previous = environment.__NotificationNovaHooks
    if previous then previous.Session = nil end
    if previous and previous.Version ~= VERSION then environment.__NotificationNovaHooks = nil end
    local function available()
        return type(hookmetamethod) == "function" and type(checkcaller) == "function"
            and type(getnamecallmethod) == "function" and type(setnamecallmethod) == "function" and type(getcallingscript) == "function"
            and debug ~= nil and type(debug.info) == "function"
    end
    Session.HooksAvailable = profile ~= nil and available()
    Session.HooksEnabled = false
    Session.AimHooksRequested = false
    Session.HookStatus = "No Cam Rotate is off."

    -- Cache source names, not whole call stacks: the same utility can serve camera and combat.
    -- Keep movement and networking consumers on real transforms as well as camera consumers.
    local sourceCache, sourceCount = {}, 0
    local cameraSegments = {".camera.", ".cameraruntime.", ".cameramodule.", ".cameracontroller.",
        ".camerainput.", ".cameracollision.", ".camerasubjecttracker.", ".auravisibilitytracker.",
        ".viewmodelcontroller.", ".controlmodule.", ".playermodule.",
        ".network.", ".networking.", ".replication.", ".replicationcontroller.",
        ".networkcontroller.", ".charactercontroller.", ".charactermovement.",
        ".movementcontroller.", ".characterreplication.", ".playercontroller.", ".humanoidcontroller."}
    if profile == "InternalCamera" then
        -- Names and dependencies observed in the supplied PlayerModule.BaseCamera.
        for _, segment in ipairs({".basecamera.", ".camerautils.", ".zoomcontroller.",
            ".cameratogglestatecontroller.", ".cameraui.", ".internalcamera."}) do
            table.insert(cameraSegments, segment)
        end
    end
    local function cameraSource(source)
        if type(source) ~= "string" then return false end
        local cached = sourceCache[source]
        if cached ~= nil then return cached end
        local path = "." .. source:lower():gsub("[/\\]", ".") .. "."
        local protected = false
        for _, segment in ipairs(cameraSegments) do
            if path:find(segment, 1, true) then protected = true; break end
        end
        if sourceCount >= 128 then table.clear(sourceCache); sourceCount = 0 end
        sourceCache[source], sourceCount = protected, sourceCount + 1
        return protected
    end

    function Session:IsAimCameraCaller(caller)
        if typeof(caller) ~= "Instance" then return false end
        -- Include ancestors so CameraRuntime helper modules remain protected after a rename.
        local node = caller
        for _ = 1, 32 do
            if not node or node == game then break end
            if cameraSource(node.Name) then return true end
            node = node.Parent
        end
        return false
    end

    function Session:CanRedirectAimCaller(caller)
        if typeof(caller) ~= "Instance" or not caller.Parent then return false end
        if not caller:IsA("LocalScript") and not caller:IsA("ModuleScript")
            and not (caller:IsA("Script") and caller.RunContext == Enum.RunContext.Client) then return false end
        if self:IsAimCameraCaller(caller) then return false end
        -- getcallingscript can identify the entry script rather than the nested camera module.
        -- Inspect the active sources too, without requiring or modifying game modules.
        if not debug or type(debug.info) ~= "function" then return false end
        for level = 2, 18 do
            local ok, source = pcall(debug.info, level, "s")
            if not ok then return false end
            if source == nil then return true end
            if cameraSource(source) then return false end
        end
        -- An incomplete/deep stack cannot establish that this call is outside the camera.
        return false
    end

    function Session:GetAimHookPart()
        if not profile or not self.Alive or not self.HooksEnabled or not self.Cfg.KillAuraEnabled
            or not self.Cfg.KillAuraNoCamRotation then return nil end
        local target = self.KaTarget
        if typeof(target) ~= "Instance" or not target:IsA("Player") or target.Parent ~= Players
            or target == LocalPlayer or (self.FriendPlayers and self.FriendPlayers[target]) then return nil end
        local character, localCharacter = target.Character, LocalPlayer.Character
        local part = character and character:FindFirstChild("HumanoidRootPart")
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
        local localHumanoid = localCharacter and localCharacter:FindFirstChildOfClass("Humanoid")
        if not character or not character.Parent or not part or not part:IsA("BasePart")
            or not humanoid or humanoid.Health <= 0 or not localCharacter or not localCharacter.Parent or not root or not root:IsA("BasePart")
            or not localHumanoid or localHumanoid.Health <= 0 then return nil end
        local range = self.Cfg.KillAuraRange
        local distance = (part.Position - root.Position).Magnitude
        if type(range) ~= "number" or range ~= range or range == math.huge or range < 0
            or distance ~= distance or distance > range then return nil end
        return part
    end

    local function redirectPart(hooks)
        local current = hooks.Session
        if not current or not current.Alive or not current.HooksEnabled or not current.Cfg.KillAuraEnabled
            or not current.Cfg.KillAuraNoCamRotation or not current.KaTarget then return nil end
        local ok, ownCall = pcall(checkcaller)
        if not ok or ownCall ~= false or type(getcallingscript) ~= "function" then return nil end
        local callerOK, caller = pcall(getcallingscript)
        if not callerOK or not current:CanRedirectAimCaller(caller) then return nil end
        return current:GetAimHookPart(), current
    end

    local function aimRay(ray, position)
        if typeof(ray) ~= "Ray" then return ray end
        local direction = position - ray.Origin
        local length, distance = ray.Direction.Magnitude, direction.Magnitude
        if distance ~= distance or length ~= length or distance <= 0.001 or length <= 0 or length == math.huge then return ray end
        return Ray.new(ray.Origin, direction.Unit * length)
    end

    function Session:RefreshAimCameraReferences()
        self.AimHookCamera = workspace.CurrentCamera
        self.AimHookInternalCamera = nil
        if profile ~= "InternalCamera" then return end
        local function readInternal(scope)
            if type(scope) ~= "table" then return nil end
            local candidate = rawget(scope, "internalCamera")
            if typeof(candidate) == "Instance" and candidate:IsA("Camera") then return candidate end
            return nil
        end
        -- Executors can separate their _G from the game's _G. Resolve it without
        -- requiring PlayerModule or changing any field in the game's camera object.
        local runtime = self.AimRuntimeEnvironment
        self.AimHookInternalCamera = readInternal(type(runtime) == "table" and rawget(runtime, "_G"))
            or readInternal(_G) or readInternal(environment)
    end

    function Session:StopAimCameraTracking()
        if self.AimInternalCameraConnection then
            self.AimInternalCameraConnection:Disconnect()
            self.AimInternalCameraConnection = nil
        end
        self.AimHookInternalCamera, self.AimRuntimeEnvironment = nil, nil
    end

    function Session:StartAimCameraTracking()
        if profile ~= "InternalCamera" then return end
        if type(getrenv) == "function" then
            local ok, runtime = pcall(getrenv)
            self.AimRuntimeEnvironment = ok and type(runtime) == "table" and runtime or nil
        end
        self:RefreshAimCameraReferences()
        if self.AimInternalCameraConnection then return end
        local elapsed = 0
        self.AimInternalCameraConnection = RunService.Heartbeat:Connect(function(dt)
            if not self.Alive or not self.HooksEnabled or not self.Cfg.KillAuraNoCamRotation then return end
            elapsed += dt
            if elapsed < 0.2 then return end
            elapsed = 0
            self:RefreshAimCameraReferences()
        end)
    end

    function Session:IsAimReadCamera(object)
        return object == self.AimHookCamera or (self.AimHookInternalCamera ~= nil and object == self.AimHookInternalCamera)
    end

    function Session:InstallAimHooks()
        if not self.Alive then return false, "This session has ended." end
        if not profile then return false, "No Cam Rotate is not available in this place." end
        if self.HooksEnabled then return true, "Aim hooks are already enabled for this session." end
        self.HooksAvailable = available()
        if not self.HooksAvailable then return false, "Scoped aim requires hookmetamethod, checkcaller, getnamecallmethod, setnamecallmethod, getcallingscript and debug.info. Camera is unchanged." end
        Startup:Mark("aim-hooks.install.begin")
        local callerOK = pcall(getcallingscript)
        local sourceOK, source = pcall(debug.info, 1, "s")
        if not callerOK or not sourceOK or type(source) ~= "string" then
            self.HookError = "Caller inspection failed; aim hooks remain disabled to preserve the camera."
            Startup:Mark("aim-hooks.install.caller-error")
            return false, self.HookError
        end
        local hooks = environment.__NotificationNovaHooks
        if not hooks then hooks = {Version = VERSION}; environment.__NotificationNovaHooks = hooks end
        hooks.Session = nil
        -- Resolve identities outside the native callbacks. Unrelated property reads must not
        -- make IsA / GetMouse / camera-property calls or inspect the calling script.
        local mouseOK, mouse = pcall(function() return LocalPlayer:GetMouse() end)
        self.AimHookMouse = mouseOK and typeof(mouse) == "Instance" and mouse or nil
        self:RefreshAimCameraReferences()
        if not self.AimHookCameraConnection then
            self.AimHookCameraConnection = self:Connect(workspace:GetPropertyChangedSignal("CurrentCamera"), function()
                self:RefreshAimCameraReferences()
            end)
        end
        if not hooks.IndexInstalled then
            local oldIndex
            local inspectMethod, restoreMethod = getnamecallmethod, setnamecallmethod
            local function forwardIndex(method, object, key)
                if type(method) == "string" then pcall(restoreMethod, method) end
                return oldIndex(object, key)
            end
            local ok, err = pcall(function()
                oldIndex = hookmetamethod(game, "__index", function(object, key)
                    if key ~= "CFrame" and key ~= "CoordinateFrame" and key ~= "Hit" and key ~= "Target" and key ~= "UnitRay" then return oldIndex(object, key) end
                    local current = hooks.Session
                    if not current or not current.Alive or not current.HooksEnabled or not current.Cfg.KillAuraEnabled
                        or not current.Cfg.KillAuraNoCamRotation or not current.KaTarget then return oldIndex(object, key) end
                    local cameraRead = (key == "CFrame" or (key == "CoordinateFrame" and current.PlaceSupport.NoCamRotate == "InternalCamera"))
                        and current:IsAimReadCamera(object)
                    local mouseRead = (key == "Hit" or key == "Target" or key == "UnitRay")
                        and object == current.AimHookMouse and current.AimHookMouse ~= nil
                    if not cameraRead and not mouseRead then return oldIndex(object, key) end
                    local tokenOK, incomingMethod = pcall(inspectMethod)
                    if not tokenOK then return oldIndex(object, key) end
                    local routed, changed, value = pcall(function()
                        local part = redirectPart(hooks)
                        if not part then return false end
                        if cameraRead then
                            local original = forwardIndex(incomingMethod, object, key)
                            if typeof(original) == "CFrame" and (part.Position - original.Position).Magnitude > 0.001 then
                                return true, CFrame.lookAt(original.Position, part.Position)
                            end
                        elseif key == "Hit" then return true, CFrame.new(part.Position)
                        elseif key == "Target" then return true, part
                        elseif key == "UnitRay" then return true, aimRay(forwardIndex(incomingMethod, object, key), part.Position)
                        end
                        return false
                    end)
                    -- Classification and target inspection can perform nested namecalls.
                    -- Restore an existing token before either forwarding or returning a value.
                    if not routed or not changed then return forwardIndex(incomingMethod, object, key) end
                    if type(incomingMethod) == "string" then pcall(restoreMethod, incomingMethod) end
                    return value
                end)
                assert(type(oldIndex) == "function", "Index hook did not return an original function")
            end)
            hooks.IndexInstalled = ok
            if not ok then
                self.HookError = "Index hook unavailable: " .. tostring(err)
                Startup:Mark("aim-hooks.install.index-error")
                return false, self.HookError
            end
        end
        if not hooks.NamecallInstalled then
            local oldNamecall
            local restoreMethod = setnamecallmethod
            local function forward(method, object, ...)
                -- IsA / FindFirstChild in the routing helpers can change the native namecall token.
                restoreMethod(method)
                return oldNamecall(object, ...)
            end
            local ok, err = pcall(function()
                oldNamecall = hookmetamethod(game, "__namecall", function(object, ...)
                    if not hooks.Session then return oldNamecall(object, ...) end
                    local method = getnamecallmethod()
                    local cameraRay = method == "ViewportPointToRay" or method == "ScreenPointToRay"
                    local legacyRay = method == "FindPartOnRay" or method == "FindPartOnRayWithIgnoreList" or method == "FindPartOnRayWithWhitelist"
                    if typeof(object) ~= "Instance" or not ((cameraRay and hooks.Session:IsAimReadCamera(object))
                        or (object == workspace and (legacyRay or method == "Raycast"))) then return oldNamecall(object, ...) end
                    local routed, part = pcall(redirectPart, hooks)
                    if not routed or not part then return forward(method, object, ...) end
                    if cameraRay then return aimRay(forward(method, object, ...), part.Position) end
                    local args = table.pack(...)
                    if method == "Raycast" and typeof(args[1]) == "Vector3" and typeof(args[2]) == "Vector3" then
                        args[2] = aimRay(Ray.new(args[1], args[2]), part.Position).Direction
                    elseif legacyRay and typeof(args[1]) == "Ray" then
                        args[1] = aimRay(args[1], part.Position)
                    end
                    return forward(method, object, table.unpack(args, 1, args.n))
                end)
                assert(type(oldNamecall) == "function", "Namecall hook did not return an original function")
            end)
            hooks.NamecallInstalled = ok
            if not ok then
                self.HookError = "Namecall hook unavailable: " .. tostring(err)
                Startup:Mark("aim-hooks.install.namecall-error")
                return false, self.HookError
            end
        end
        self.HooksEnabled = hooks.IndexInstalled == true and hooks.NamecallInstalled == true
        if self.HooksEnabled then
            self:StartAimCameraTracking()
            hooks.Session = self
            self.HookError = nil
        end
        Startup:Mark(self.HooksEnabled and "aim-hooks.install.ready" or "aim-hooks.install.unavailable")
        local readyStatus = profile == "InternalCamera"
            and "Internal camera aim profile enabled; PlayerModule camera reads remain unchanged."
            or "Aim hooks enabled; camera modules keep their original view and collision rays."
        return self.HooksEnabled, self.HooksEnabled and readyStatus or "Aim hooks are unavailable."
    end

    function Session:RefreshAimHooks()
        if not self.Alive or not profile or self.Cfg.KillAuraNoCamRotation ~= true then
            local hooks = environment.__NotificationNovaHooks
            if hooks and hooks.Session == self then hooks.Session = nil end
            self.HooksEnabled, self.AimHooksRequested, self.HookError = false, false, nil
            self:StopAimCameraTracking()
            self.HookStatus = not self.Alive and "This session has ended."
                or (not profile and "No Cam Rotate is not available in this place." or "No Cam Rotate is off.")
            return false, self.HookStatus, false
        end
        if not self.Ready then
            self.HookStatus = "Aim hooks will activate when the interface is ready."
            return nil, self.HookStatus, false
        end
        -- A missing or broken executor API must not be retried on every settings refresh.
        -- Turning the option off and back on explicitly starts a new activation attempt.
        if self.AimHooksRequested then return self.HooksEnabled, self.HookStatus, false end
        self.AimHooksRequested = true
        local enabled, status = self:InstallAimHooks()
        self.HookStatus = status
        if not enabled then self.HookError = status end
        return enabled, status, true
    end
end
-- // ЭФФЕКТЫ И ШЕЙДЕРЫ
local SaturationEffect = Instance.new("ColorCorrectionEffect")
SaturationEffect.Name = "NotificationSaturation"
SaturationEffect.Enabled = false
SaturationEffect.Parent = Lighting
-- Platform: Roblox client / Luau; target: owned, change-driven World Color post-processing.
local function UpdateWorldShader()
    Session:ApplyWorldShader()
end

do
    local WHITE = Color3.new(1, 1, 1)
    local keys = {
        "WorldColorEnabled", "WorldColorShader", "WorldColorValue", "WorldColorTransparency", "WorldColorDarkness", "LowEndMode",
    }
    local atmosphereProperties = {Color = true, Decay = true, Density = true, Haze = true, Glare = true, Offset = true}
    local state = {
        Effects = {}, Values = {}, Connections = {}, ExpectedLighting = {},
        ExpectedAtmospheres = setmetatable({}, {__mode = "k"}),
        Dirty = true, Writing = false, Destroyed = false,
    }
    Session.WorldShaderState = state

    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end
    local function number(value, fallback, minimum, maximum)
        return finite(value) and math.clamp(value, minimum, maximum) or fallback
    end
    local function setting(key, fallback, minimum, maximum)
        return number(Cfg[key], fallback, minimum, maximum)
    end
    local function color(value, fallback)
        if typeof(value) ~= "Color3" or not finite(value.R) or not finite(value.G) or not finite(value.B) then return fallback end
        return Color3.new(math.clamp(value.R, 0, 1), math.clamp(value.G, 0, 1), math.clamp(value.B, 0, 1))
    end
    local function assign(object, values)
        for property, value in pairs(values) do
            if object[property] ~= value then object[property] = value end
        end
    end
    local function baseline(owner, object, property, fallback)
        local entry = Session.Overrides[owner]
        local value = entry and entry.Instance == object and entry.Values[property]
        if value == nil then value = object[property] end
        return value == nil and fallback or value
    end
    local function expectValues(object, values)
        local expected
        if object == Lighting then
            expected = state.ExpectedLighting
        else
            expected = state.ExpectedAtmospheres[object]
            if not expected then expected = {}; state.ExpectedAtmospheres[object] = expected end
        end
        for property, value in pairs(values) do expected[property] = value end
    end
    local function readExpectedValues(object, values)
        local expected = object == Lighting and state.ExpectedLighting or state.ExpectedAtmospheres[object]
        for property in pairs(values) do
            local ok, value = pcall(function() return object[property] end)
            if ok then expected[property] = value end
        end
    end
    local function override(owner, object, values)
        -- Roblox may defer Changed until after the setter returns. Record expected
        -- values before writing so our own delayed events never become new baselines.
        expectValues(object, values)
        Session:Override(owner, object, values)
        -- Numeric properties and Color3 channels can be quantized by the engine.
        -- Compare deferred events with stored values rather than Lua input doubles.
        readExpectedValues(object, values)
    end
    local function release(owner)
        local entry = Session.Overrides[owner]
        if entry then expectValues(entry.Instance, entry.Values) end
        Session:Release(owner)
        if entry then readExpectedValues(entry.Instance, entry.Values) end
    end
    local function markDirty()
        if state.Destroyed or state.Writing then return end
        state.Dirty = true
        Session.SceneDirty = true
    end
    local function effect(key, className)
        local object = state.Effects[key]
        if object and object.Parent == Lighting then return object end
        if object then pcall(function() object:Destroy() end) end
        object = Instance.new(className)
        object.Name = "NotificationWorld" .. key
        object.Enabled = false
        object.Parent = Lighting
        state.Effects[key] = object
        return object
    end
    local function disableEffects()
        for _, object in pairs(state.Effects) do
            pcall(function() if object.Enabled then object.Enabled = false end end)
        end
    end
    local function releaseAtmosphere()
        if state.AtmosphereConnection then state.AtmosphereConnection:Disconnect(); state.AtmosphereConnection = nil end
        release("WorldShaderAtmosphere")
        state.Atmosphere = nil
        if state.OwnedAtmosphere then pcall(function() state.OwnedAtmosphere.Parent = nil end) end
    end
    local function getAtmosphere()
        local target
        for _, child in ipairs(Lighting:GetChildren()) do
            if child:IsA("Atmosphere") and child ~= state.OwnedAtmosphere then target = child; break end
        end
        if target then
            if state.OwnedAtmosphere then pcall(function() state.OwnedAtmosphere.Parent = nil end) end
        else
            if not state.OwnedAtmosphere then
                local owned = Instance.new("Atmosphere")
                owned.Name = "NotificationWorldAtmosphere"
                assign(owned, {Color = WHITE, Decay = WHITE, Density = 0, Haze = 0, Glare = 0, Offset = 0})
                state.OwnedAtmosphere = owned
            end
            target = state.OwnedAtmosphere
        end
        if state.Atmosphere ~= target then
            releaseAtmosphere()
            state.Atmosphere = target
            state.AtmosphereConnection = target.Changed:Connect(function(property)
                if state.Writing or state.Destroyed or state.Atmosphere ~= target or not atmosphereProperties[property] then return end
                local expected = state.ExpectedAtmospheres[target]
                if expected and expected[property] == target[property] then return end
                -- Keep game-authored weather changes as the baseline restored on disable.
                local entry = Session.Overrides.WorldShaderAtmosphere
                if target ~= state.OwnedAtmosphere and entry and entry.Instance == target then entry.Values[property] = target[property] end
                markDirty()
            end)
        end
        if target == state.OwnedAtmosphere and target.Parent ~= Lighting then
            local attached = pcall(function() target.Parent = Lighting end)
            if not attached then
                -- A game cleanup can destroy an owned child between setting changes.
                releaseAtmosphere()
                state.OwnedAtmosphere = nil
                return getAtmosphere()
            end
        end
        return target
    end

    for _, signal in ipairs({Lighting.ChildAdded, Lighting.ChildRemoved}) do
        table.insert(state.Connections, signal:Connect(function(child)
            if child:IsA("Atmosphere") then markDirty(); return end
            for _, object in pairs(state.Effects) do if child == object then markDirty(); return end end
        end))
    end
    table.insert(state.Connections, Lighting.Changed:Connect(function(property)
        if state.Writing or state.Destroyed then return end
        local owner = property == "ExposureCompensation" and "WorldShaderExposure"
            or (property == "FogColor" or property == "FogEnd") and "Fog" or nil
        if not owner then return end
        if state.ExpectedLighting[property] == Lighting[property] then return end
        local entry = Session.Overrides[owner]
        if entry and entry.Instance == Lighting then entry.Values[property] = Lighting[property] end
        markDirty()
    end))

    function Session:ApplyWorldShader()
        if state.Destroyed or not self.Alive then return end
        local changed = state.Dirty
        for _, key in ipairs(keys) do
            local previous, current = state.Values[key], Cfg[key]
            local bothNaN = type(previous) == "number" and type(current) == "number" and previous ~= previous and current ~= current
            if previous ~= current and not bothNaN then state.Values[key] = current; changed = true end
        end
        if not changed then return end
        state.Dirty = false
        state.Writing = true
        local strength = setting("WorldColorTransparency", 0.5, 0, 1)
        if not Cfg.WorldColorEnabled or (Cfg.WorldColorShader and strength <= 0) then
            disableEffects()
            releaseAtmosphere()
            release("Fog")
            release("WorldShaderExposure")
            state.Writing = false
            return
        end

        local custom = color(Cfg.WorldColorValue, Color3.fromRGB(150, 50, 255))
        if not Cfg.WorldColorShader then
            -- Preserve the original plain World Color behavior, including intensity zero.
            override("Fog", Lighting, {FogColor = custom, FogEnd = 300 + (1 - strength) * 1500})
            disableEffects()
            releaseAtmosphere()
            release("WorldShaderExposure")
            state.Writing = false
            return
        end

        local fogColor = color(baseline("Fog", Lighting, "FogColor", WHITE), WHITE)
        local fogEnd = number(baseline("Fog", Lighting, "FogEnd", 100000), 100000, 0, 1000000)
        override("Fog", Lighting, {FogColor = fogColor:Lerp(custom, strength * 0.12), FogEnd = fogEnd})
        local lowEnd = Cfg.LowEndMode == true
        local darkness = setting("WorldColorDarkness", 1, 0, 5)
        -- Keep light in every color channel: grading adds the selected hue without
        -- the old saturated tint multiplying the whole world into a dark wash.
        local balancedTint = WHITE:Lerp(custom, 0.32)
        assign(effect("ColorCorrection", "ColorCorrectionEffect"), {
            TintColor = WHITE:Lerp(balancedTint, strength),
            Contrast = 0.28 * strength,
            Saturation = 0.18 * strength,
            Brightness = -darkness * 0.04 * strength,
            Enabled = true,
        })
        local exposureBase = number(baseline("WorldShaderExposure", Lighting, "ExposureCompensation", 0), 0, -5, 5)
        override("WorldShaderExposure", Lighting, {
            ExposureCompensation = math.clamp(exposureBase + (0.1 - darkness * 0.025) * strength, -5, 5),
        })
        assign(effect("Bloom", "BloomEffect"), {
            Intensity = 0.8 * strength * (lowEnd and 0.4 or 1),
            Size = lowEnd and 16 or 30,
            Threshold = lowEnd and 1.17 or 1.05,
            Enabled = true,
        })
        assign(effect("SunRays", "SunRaysEffect"), {
            Intensity = 0.07 * strength * (lowEnd and 0.35 or 1),
            Spread = 0.78,
            Enabled = true,
        })

        local atmosphere = getAtmosphere()
        local densityBase = number(baseline("WorldShaderAtmosphere", atmosphere, "Density", 0), 0, 0, 1)
        local hazeBase = number(baseline("WorldShaderAtmosphere", atmosphere, "Haze", 0), 0, 0, 10)
        local glareBase = number(baseline("WorldShaderAtmosphere", atmosphere, "Glare", 0), 0, 0, 10)
        local offsetBase = number(baseline("WorldShaderAtmosphere", atmosphere, "Offset", 0), 0, -1, 1)
        local colorBase = color(baseline("WorldShaderAtmosphere", atmosphere, "Color", WHITE), WHITE)
        local decayBase = color(baseline("WorldShaderAtmosphere", atmosphere, "Decay", WHITE), WHITE)
        local densityBlend = strength * (atmosphere == state.OwnedAtmosphere and 1 or 0.35)
        override("WorldShaderAtmosphere", atmosphere, {
            Color = colorBase:Lerp(WHITE:Lerp(custom, 0.45), strength),
            Decay = decayBase:Lerp(Color3.fromRGB(113, 127, 151):Lerp(custom, 0.3), strength),
            Density = densityBase + (0.23 - densityBase) * densityBlend,
            Haze = hazeBase + (1.25 - hazeBase) * strength,
            Glare = glareBase + (0.18 - glareBase) * strength,
            Offset = offsetBase + (0.12 - offsetBase) * strength,
        })
        state.Writing = false
    end

    function Session:DestroyWorldShader()
        if state.Destroyed then return end
        state.Destroyed = true
        state.Writing = true
        for _, connection in ipairs(state.Connections) do connection:Disconnect() end
        table.clear(state.Connections)
        releaseAtmosphere()
        release("Fog")
        release("WorldShaderExposure")
        for _, object in pairs(state.Effects) do pcall(function() object:Destroy() end) end
        table.clear(state.Effects)
        if state.OwnedAtmosphere then state.OwnedAtmosphere:Destroy(); state.OwnedAtmosphere = nil end
        table.clear(state.Values)
        table.clear(state.ExpectedLighting)
        table.clear(state.ExpectedAtmospheres)
        state.Writing = false
    end
end


-- Platform: Roblox client / Luau; target: continuous third-person camera follow smoothing.
-- Remove our previous translation before CameraModule reads last frame's camera.
-- The matching post-camera pass changes position only, so mouse orbit stays responsive.
do
    local ZERO = Vector3.zero
    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end
    local function finiteVector(value)
        return typeof(value) == "Vector3" and finite(value.X) and finite(value.Y) and finite(value.Z)
    end
    local function setting(key, fallback, minimum, maximum)
        local value = Cfg[key]
        return finite(value) and math.clamp(value, minimum, maximum) or fallback
    end
    -- Identity around zero, then a C2-continuous knee approaching the limit.
    -- A hard clamp turns a slow jump into full-speed motion the instant it hits a cap.
    local function softLimit(value, maximum)
        local magnitude = math.abs(value)
        local knee = maximum * 0.65
        if magnitude <= knee then return value end
        local room = maximum - knee
        local t = (magnitude - knee) / room
        local bounded = knee + room * t / math.sqrt(1 + t * t)
        return value < 0 and -bounded or bounded
    end
    -- Exact critically damped follow for an anchor moving linearly during a step.
    -- Velocity is in world space and survives takeoff, apex, landing and stopping.
    local function spring(offset, velocity, inputVelocity, frequency, dt)
        local decay = math.exp(-frequency * dt)
        local drive = velocity + offset * frequency + inputVelocity
        local steady = inputVelocity * (2 / frequency)
        return (offset + steady + drive * dt) * decay - steady,
            inputVelocity + (velocity - inputVelocity - drive * (frequency * dt)) * decay
    end
    local function frequencyStep(current, target, dt)
        local rate = 1 / 0.18
        local decay = math.exp(-rate * dt)
        return target + (current - target) * decay,
            target + (current - target) * ((1 - decay) / (rate * dt))
    end

    function Session:RestoreSoftCameraOffset()
        local state = self.SoftCameraState
        if not state or not state.AppliedCamera then return end
        local camera = state.AppliedCamera
        -- Restore only values we still own; a cutscene may have replaced them meanwhile.
        pcall(function()
            if camera.CFrame == state.AppliedCFrame then
                camera.CFrame = state.BaseCFrame
            elseif camera.CFrame.Position == state.AppliedCFrame.Position then
                -- A later pass may rotate the view without moving it. Keep that
                -- rotation, while still removing our owned world translation.
                camera.CFrame += state.BaseCFrame.Position - state.AppliedCFrame.Position
            end
            if camera.Focus == state.AppliedFocus then
                camera.Focus = state.BaseFocus
            elseif camera.Focus.Position == state.AppliedFocus.Position then
                camera.Focus += state.BaseFocus.Position - state.AppliedFocus.Position
            end
        end)
        state.AppliedCamera, state.AppliedCFrame, state.AppliedFocus = nil, nil, nil
        state.BaseCFrame, state.BaseFocus = nil, nil
    end

    function Session:ResetSoftCamera()
        self:RestoreSoftCameraOffset()
        self.SoftCameraState = nil
    end

    function Session:UpdateSoftCamera(dt)
        self:RestoreSoftCameraOffset()
        if not self.Alive or not self.Ready or not Cfg.SoftCameraEnabled
            or not finite(dt) or dt <= 0 or dt > 0.5 then
            self:ResetSoftCamera()
            return
        end
        local camera = workspace.CurrentCamera
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local head = character and character:FindFirstChild("Head")
        local subject = camera and camera.CameraSubject
        if not camera or not humanoid or humanoid.Health <= 0 or not root or not root.Parent
            or camera.CameraType == Enum.CameraType.Scriptable
            or LocalPlayer.CameraMode == Enum.CameraMode.LockFirstPerson
            or not subject or not subject:IsDescendantOf(character)
            or (camera.CFrame.Position - camera.Focus.Position).Magnitude <= 1
            or (head and (camera.CFrame.Position - head.Position).Magnitude <= 1)
            or not finiteVector(root.Position) or not finiteVector(camera.Focus.Position) then
            self:ResetSoftCamera()
            return
        end

        local lag = setting("SoftCameraLag", 0.14, 0.03, 0.25)
        local verticalTime = setting("SoftCameraVerticalSmoothness", 0.32, 0.12, 0.75)
        local maximum = setting("SoftCameraMaxOffset", 1.75, 0.1, 4)
        local verticalLimit = setting("SoftCameraVerticalLimit", 8, 2, 12)
        local anchor = camera.Focus.Position
        local state = self.SoftCameraState
        if not state or state.Camera ~= camera or state.Character ~= character or state.Root ~= root
            or state.Subject ~= subject then
            self:ResetSoftCamera()
            state = {Camera = camera, Character = character, Root = root, Subject = subject,
                PreviousPosition = root.Position, PreviousFocus = anchor,
                RawOffset = ZERO, Velocity = ZERO, Offset = ZERO,
                FrequencyXZ = 2 / lag, FrequencyY = 2 / verticalTime,
                Clearance = 1, ClearanceVelocity = 0}
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = {character, self.Effects}
            params.IgnoreWater = true
            params.RespectCanCollide = true
            state.RaycastParams = params
            self.SoftCameraState = state
            return
        end

        local position = root.Position
        local movement = position - state.PreviousPosition
        local focusMovement = anchor - state.PreviousFocus
        state.PreviousPosition = position
        state.PreviousFocus = anchor
        if movement.Magnitude > math.max(12, maximum * 8)
            or focusMovement.Magnitude > math.max(16, verticalLimit * 4) then
            state.Offset, state.RawOffset, state.Velocity = ZERO, ZERO, ZERO
            state.Clearance, state.ClearanceVelocity = 1, 0
            return
        end
        -- CameraModule may hold or soften its own focus height during a jump.
        -- Follow that resulting focus, rather than subtracting raw root motion from it.
        local inputVelocity = focusMovement / dt
        local inputXZ = Vector3.new(inputVelocity.X, 0, inputVelocity.Z)
        local activityXZ = inputXZ.Magnitude ^ 2 / (inputXZ.Magnitude ^ 2 + 4)
        local activityY = inputVelocity.Y ^ 2 / (inputVelocity.Y ^ 2 + 4)
        local returnSpeed = setting("SoftCameraReturnSpeed", 14, 6, 30)
        local movingXZ, movingY = 2 / lag, 2 / verticalTime
        local restXZ = math.min(returnSpeed, movingXZ * 1.65)
        local restY = math.min(returnSpeed, movingY * 1.65)
        local targetXZ = restXZ + (movingXZ - restXZ) * activityXZ
        local targetY = restY + (movingY - restY) * activityY
        local offsetXZ = Vector3.new(state.RawOffset.X, 0, state.RawOffset.Z)
        local velocityXZ = Vector3.new(state.Velocity.X, 0, state.Velocity.Z)
        local offsetY, velocityY = state.RawOffset.Y, state.Velocity.Y
        -- Small analytical steps also make changing response settings behave alike
        -- at 30/60/144 FPS; there is no unbounded catch-up loop after a long frame.
        local steps = math.min(60, math.max(1, math.ceil(dt * 120)))
        local h = dt / steps
        for _ = 1, steps do
            local frequencyXZ, frequencyY
            state.FrequencyXZ, frequencyXZ = frequencyStep(state.FrequencyXZ, targetXZ, h)
            state.FrequencyY, frequencyY = frequencyStep(state.FrequencyY, targetY, h)
            offsetXZ, velocityXZ = spring(offsetXZ, velocityXZ, inputXZ, frequencyXZ, h)
            offsetY, velocityY = spring(offsetY, velocityY, inputVelocity.Y, frequencyY, h)
        end
        state.RawOffset = Vector3.new(offsetXZ.X, offsetY, offsetXZ.Z)
        state.Velocity = Vector3.new(velocityXZ.X, velocityY, velocityXZ.Z)
        local horizontal = offsetXZ.Magnitude
        if horizontal > 0 then offsetXZ *= softLimit(horizontal, maximum) / horizontal end
        state.Offset = Vector3.new(offsetXZ.X, softLimit(offsetY, verticalLimit), offsetXZ.Z)
        if state.Offset.Magnitude < 0.000001 and state.Velocity.Magnitude < 0.00001 then
            state.Offset, state.RawOffset, state.Velocity = ZERO, ZERO, ZERO
            return
        end

        -- Keep the small added translation out of nearby collidable walls. The game
        -- camera still owns its normal zoom/occlusion solver and viewing direction.
        local applied = state.Offset
        local clearance = 1
        local hit = applied.Magnitude > 0.000001
            and workspace:Raycast(camera.CFrame.Position, applied, state.RaycastParams)
        if hit then
            local distance = math.max(0, hit.Distance - 0.15)
            clearance = math.clamp(distance / applied.Magnitude, 0, 1)
        end
        if clearance < state.Clearance then
            -- Entering a wall must stop immediately; leaving it eases back out.
            state.Clearance, state.ClearanceVelocity = clearance, 0
        else
            local error, velocity = spring(state.Clearance - clearance, state.ClearanceVelocity, 0, 14, dt)
            state.Clearance = math.clamp(clearance + error, 0, clearance)
            state.ClearanceVelocity = state.Clearance >= clearance and 0 or velocity
        end
        applied *= state.Clearance
        if applied.Magnitude < 0.000001 then return end
        state.BaseCFrame, state.BaseFocus = camera.CFrame, camera.Focus
        state.AppliedCamera = camera
        state.AppliedCFrame = camera.CFrame + applied
        state.AppliedFocus = camera.Focus + applied
        camera.CFrame, camera.Focus = state.AppliedCFrame, state.AppliedFocus
    end

    function Session:DestroySoftCamera()
        self:ResetSoftCamera()
        RunService:UnbindFromRenderStep(self.RenderName .. "_SoftCameraBefore")
        RunService:UnbindFromRenderStep(self.RenderName .. "_SoftCameraAfter")
    end

    RunService:BindToRenderStep(Session.RenderName .. "_SoftCameraBefore", 199, function()
        Session:RestoreSoftCameraOffset()
    end)
    RunService:BindToRenderStep(Session.RenderName .. "_SoftCameraAfter", 201, function(dt)
        Session:UpdateSoftCamera(dt)
    end)
end


-- Platform: Roblox client / Luau; target: compatible client fall-speed damage checks.
-- This is a velocity reset, not a universal server-side damage bypass.
do
    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end
    local function liveAirborneBody(character, humanoid, root)
        if not character or character ~= LocalPlayer.Character or not root or not root.Parent
            or not root:IsA("BasePart") or root.Anchored or not humanoid or not humanoid.Parent
            or character:FindFirstChild("HumanoidRootPart") ~= root or character:FindFirstChildOfClass("Humanoid") ~= humanoid
            or humanoid.Health <= 0 or humanoid.Sit or humanoid.SeatPart
            or humanoid.FloorMaterial ~= Enum.Material.Air then return false end
        return true
    end
    local function airborne(character, humanoid, root)
        if not liveAirborneBody(character, humanoid, root) or humanoid.PlatformStand then return false end
        local state = humanoid:GetState()
        return state ~= Enum.HumanoidStateType.Dead and state ~= Enum.HumanoidStateType.Seated
            and state ~= Enum.HumanoidStateType.Swimming and state ~= Enum.HumanoidStateType.Climbing
            and state ~= Enum.HumanoidStateType.Physics and state ~= Enum.HumanoidStateType.Ragdoll
            and state ~= Enum.HumanoidStateType.FallingDown and state ~= Enum.HumanoidStateType.GettingUp
    end

    -- Only replace the Y component we still own. Jumps, external impulses and
    -- other movement modules may have changed it after our PostSimulation pass.
    function Session:RestoreNoFallVelocity()
        local pending = self.NoFallPending
        self.NoFallPending = nil
        if not pending or not liveAirborneBody(pending.Character, pending.Humanoid, pending.Root) then return end
        local root = pending.Root
        if (root.Position - pending.Position).Magnitude > 64 then return end
        local current = root.AssemblyLinearVelocity
        if finite(current.X) and finite(current.Y) and finite(current.Z) and math.abs(current.Y) <= 0.0001 then
            root.AssemblyLinearVelocity = Vector3.new(current.X, pending.VelocityY, current.Z)
        end
    end

    function Session:ResetNoFall(restorePending)
        if restorePending then self:RestoreNoFallVelocity() else self.NoFallPending = nil end
        self.NoFallFlight = nil
    end

    function Session:NoFallPreSimulation()
        -- Restore before physics so gravity, collisions and the fall trajectory
        -- use the original speed instead of repeatedly starting from zero.
        self:RestoreNoFallVelocity()
        if not self.Ready or not Cfg.NoFallEnabled or not Cfg.NoFallVelocityReset then self.NoFallFlight = nil end
    end

    function Session:NoFallPostSimulation(dt)
        if not self.Ready or not Cfg.NoFallEnabled or not Cfg.NoFallVelocityReset then self:ResetNoFall(true); return end
        if not finite(dt) or dt <= 0 or dt > 0.5 then self:ResetNoFall(true); return end
        -- A second post callback without a pre callback must not overwrite saved speed.
        if self.NoFallPending then return end
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local flight = self.NoFallFlight
        if flight and (flight.Character ~= character or flight.Root ~= root or flight.Humanoid ~= humanoid
            or not root or (root.Position - flight.Position).Magnitude > 64) then
            self.NoFallFlight, flight = nil, nil
        end
        if not airborne(character, humanoid, root) then
            local landed = flight and humanoid and humanoid.Health > 0
                and humanoid.FloorMaterial ~= Enum.Material.Air and not humanoid.Sit and not humanoid.SeatPart
            self.NoFallFlight = nil
            if landed and Cfg.NoFallLandingNotify and not window.Destroyed
                and tick() - (self.NoFallLastNotice or -math.huge) >= 1 then
                self.NoFallLastNotice = tick()
                window:Notify({Title="notification", Text="Landed. Fall velocity reset was applied.", Kind="info", Duration=2})
            end
            return
        end
        local velocity = root.AssemblyLinearVelocity
        if not finite(velocity.X) or not finite(velocity.Y) or not finite(velocity.Z) then self:ResetNoFall(false); return end
        local minimum = Cfg.NoFallMinSpeed
        minimum = finite(minimum) and math.clamp(minimum, 1, 150) or 1
        if flight then flight.Position = root.Position end
        if velocity.Y > -minimum then return end
        self.NoFallPending = {Character=character, Humanoid=humanoid, Root=root,
            VelocityY=velocity.Y, Position=root.Position}
        self.NoFallFlight = flight or {Character=character, Humanoid=humanoid, Root=root, Position=root.Position}
        root.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
    end

    Session:Connect(RunService.PreSimulation, function() Session:NoFallPreSimulation() end)
    Session:Connect(RunService.PostSimulation, function(dt) Session:NoFallPostSimulation(dt) end)
end


-- Platform: Roblox client / Luau; target: explicitly named local fall-damage scripts.
-- Name matching is a heuristic. It cannot disable server-owned damage logic.
do
    local names = {falldamage=true, falldamagescript=true, falldamageclient=true, clientfalldamage=true}
    local scopes, scripts, lifetime = {}, {}, {}
    local stopped, queued, errors = false, false, 0
    local refresh
    local function disconnect(bucket)
        for _, connection in ipairs(bucket) do pcall(function() connection:Disconnect() end) end
        table.clear(bucket)
    end
    local function enabled()
        return not stopped and Session.Ready and Cfg.NoFallEnabled and Cfg.NoFallClientScripts
    end
    local function matched(script)
        return names[script.Name:lower():gsub("[%s_%-]", "")] == true
    end
    local function contained(script)
        for scope in pairs(scopes) do
            if scope.Parent and script:IsDescendantOf(scope) then return true end
        end
        return false
    end
    local function release(script, record)
        local original = record.Original
        record.Original = nil
        if original ~= nil then
            local ok = pcall(function() script.Enabled = original end)
            if not ok then errors += 1 end
        end
    end
    local function forget(script)
        local record = scripts[script]
        if not record then return end
        release(script, record)
        disconnect(record.Connections)
        scripts[script] = nil
    end
    local function later()
        if stopped or queued then return end
        queued = true
        task.defer(function()
            queued = false
            if not stopped then refresh(false) end
        end)
    end
    local function connect(bucket, event, callback)
        local ok, connection = pcall(function() return event:Connect(callback) end)
        if ok then table.insert(bucket, connection) else errors += 1 end
    end
    local function scriptChanged(instance)
        if instance:IsA("LocalScript") then later() end
    end
    local function scopeChanged(instance)
        if instance:IsA("PlayerScripts") or instance:IsA("PlayerGui") then later() end
    end
    local function observe(script, reapply)
        if not script:IsA("LocalScript") then return end
        local record = scripts[script]
        if not record then
            record = {Connections={}, Eligible=false}
            scripts[script] = record
            connect(record.Connections, script:GetPropertyChangedSignal("Name"), later)
            connect(record.Connections, script:GetPropertyChangedSignal("Parent"), later)
            -- A third party may re-enable its script. This event only updates
            -- status; only an explicit rescan may disable an eligible script again.
            connect(record.Connections, script:GetPropertyChangedSignal("Enabled"), function()
                if not stopped then Session:UpdateNoFallScriptStatus() end
            end)
        end
        local eligible = enabled() and matched(script)
        if not eligible then
            release(script, record)
        elseif reapply or not record.Eligible then
            local ok, original = pcall(function() return script.Enabled end)
            if not ok then
                errors += 1
            elseif original == true then
                local changed = pcall(function() script.Enabled = false end)
                if changed then record.Original = original else errors += 1 end
            end
        end
        record.Eligible = eligible
    end

    function Session:GetNoFallScriptStatus()
        local count, disabled = 0, 0
        for script, record in pairs(scripts) do
            local ok, isMatch, isDisabled = pcall(function()
                return contained(script) and matched(script), script.Enabled == false
            end)
            if ok and isMatch then
                count += 1
                if record.Original ~= nil and isDisabled then disabled += 1 end
            end
        end
        local state = enabled() and "" or "Local control off. "
        local velocity = Cfg.NoFallEnabled and Cfg.NoFallVelocityReset and "on" or "off"
        return string.format("%sMatched: %d | Disabled: %d | Errors: %d. Velocity: %s. Local name matches; damage protection unverified.",
            state, count, disabled, errors, velocity)
    end

    function Session:UpdateNoFallScriptStatus()
        if type(self.NoFallStatusChanged) == "function" then
            pcall(self.NoFallStatusChanged, self:GetNoFallScriptStatus())
        end
    end

    refresh = function(reapply)
        if stopped then return end
        local desired = {}
        if Session.Ready then
            local character = LocalPlayer.Character
            local playerScripts = LocalPlayer:FindFirstChildOfClass("PlayerScripts")
            local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if character and character.Parent then desired[character] = true end
            if playerScripts then desired[playerScripts] = true end
            if playerGui then desired[playerGui] = true end
        end
        for scope, bucket in pairs(scopes) do
            if not desired[scope] then disconnect(bucket); scopes[scope] = nil end
        end
        for scope in pairs(desired) do
            if not scopes[scope] then
                local bucket = {}
                scopes[scope] = bucket
                connect(bucket, scope.DescendantAdded, scriptChanged)
                -- Removing fires before ancestry is changed, so recheck deferred.
                connect(bucket, scope.DescendantRemoving, scriptChanged)
                connect(bucket, scope:GetPropertyChangedSignal("Parent"), later)
            end
        end
        for script in pairs(scripts) do
            if not contained(script) then forget(script) end
        end
        for scope in pairs(scopes) do
            for _, script in ipairs(scope:GetDescendants()) do observe(script, reapply) end
        end
        Session:UpdateNoFallScriptStatus()
    end

    function Session:RefreshNoFallScripts()
        if stopped then return end
        errors = 0
        refresh(true)
    end

    function Session:DestroyNoFallScripts()
        if stopped then return end
        stopped = true
        disconnect(lifetime)
        for _, bucket in pairs(scopes) do disconnect(bucket) end
        table.clear(scopes)
        for script in pairs(scripts) do forget(script) end
        self:UpdateNoFallScriptStatus()
    end

    connect(lifetime, LocalPlayer.CharacterAdded, later)
    connect(lifetime, LocalPlayer:GetPropertyChangedSignal("Character"), later)
    connect(lifetime, LocalPlayer.ChildAdded, scopeChanged)
    connect(lifetime, LocalPlayer.ChildRemoved, scopeChanged)
end

local ThemeObjects = {Backgrounds = {}, Strokes = {}, Texts = {}, SecondaryTexts = {}, Inputs = {}, InputBackgrounds = {}}
local HitSounds = { "rbxassetid://140604838213617", "rbxassetid://130201387574815", "rbxassetid://135478009117226", "rbxassetid://96735711388006", "rbxassetid://126048302910782", "rbxassetid://7255642553" }

local NotificationGui = Instance.new("ScreenGui", CoreGui)
Session.OverlayGui = NotificationGui
NotificationGui.Name = "Notification_Final"; NotificationGui.IgnoreGuiInset = true; NotificationGui.ResetOnSpawn = false 

local Esp2DFolder = Instance.new("Folder", NotificationGui); Esp2DFolder.Name = "ESP2D_Storage"
local ArrowsFolder = Instance.new("Folder", NotificationGui); ArrowsFolder.Name = "Arrows_Storage"

