-- Platform: Roblox client / Luau; target: preloaded, bounded hit sounds with friend exclusion.
Session.HitFeedbackSounds = setmetatable({}, {__mode = "k"})
do
    local soundService = game:GetService("SoundService")
    local debris = game:GetService("Debris")
    local records, serial = {}, 0
    local maxSounds, lifetime = 10, 10

    local function selectedSoundId()
        if #HitSounds == 0 then return nil end
        local index = math.clamp(math.floor(tonumber(Cfg.HitSoundMode) or 1), 1, #HitSounds)
        return HitSounds[index]
    end

    local function release(sound, record, destroy)
        if record.Released then return end
        record.Released = true
        records[sound], Session.HitFeedbackSounds[sound] = nil, nil
        if record.Ended then record.Ended:Disconnect() end
        if record.Destroying then record.Destroying:Disconnect() end
        if destroy then sound:Destroy() end
    end

    function Session:PrepareHitSound()
        if not self.Alive or not Cfg.HitSoundEnabled then return end
        local id = selectedSoundId()
        if not id then return end
        local template = self.HitSoundTemplate
        if template and template.Parent and template.SoundId == id then return template end
        if template then template:Destroy() end
        template = Instance.new("Sound")
        template.Name, template.SoundId = "NotificationHitSoundWarmup", id
        template.Volume, template.Looped, template.PlayOnRemove = 0, false, false
        template.Parent = soundService
        self.HitSoundTemplate = template
        -- Configuration changes warm only the selected asset. Preload may yield;
        -- it never runs inside the damage/input path and never starts playback.
        task.defer(function()
            if not self.Alive or not Cfg.HitSoundEnabled or self.HitSoundTemplate ~= template then return end
            pcall(function() game:GetService("ContentProvider"):PreloadAsync({template}) end)
        end)
        return template
    end

    function Session:ClearHitSounds()
        for sound, record in pairs(records) do release(sound, record, true) end
        table.clear(self.HitFeedbackSounds)
        if self.HitSoundTemplate then
            self.HitSoundTemplate:Destroy()
            self.HitSoundTemplate = nil
        end
    end

    function Session:PlayHitFeedback(character)
        if not self.Alive or not Cfg.HitSoundEnabled then return false end
        local userId = self:CharacterUserId(character)
        if self:IsFriend(userId) then return false end
        local id = selectedSoundId()
        if not id then return false end

        local count, oldest, oldestRecord = 0, nil, nil
        for sound, record in pairs(records) do
            if not sound.Parent then
                release(sound, record, false)
            else
                count += 1
                if not oldestRecord or record.Serial < oldestRecord.Serial then
                    oldest, oldestRecord = sound, record
                end
            end
        end
        if count >= maxSounds and oldest then release(oldest, oldestRecord, true) end

        local template = self.HitSoundTemplate
        local sound = if template and template.Parent and template.SoundId == id
            then template:Clone() else Instance.new("Sound")
        sound.Name, sound.SoundId = "NotificationHitSound", id
        sound.Volume, sound.Looped, sound.PlayOnRemove, sound.TimePosition = 2, false, false, 0
        sound.Parent = soundService
        serial += 1
        local record = {Serial = serial}
        records[sound], self.HitFeedbackSounds[sound] = record, userId or 0
        record.Ended = sound.Ended:Connect(function() release(sound, record, true) end)
        record.Destroying = sound.Destroying:Connect(function() release(sound, record, false) end)
        -- A cold asset may take longer than a second to become playable. Ended
        -- handles normal cleanup; the failsafe bounds failed/inaccessible assets.
        debris:AddItem(sound, lifetime)
        local ok = pcall(function() sound:Play() end)
        if not ok then release(sound, record, true) end
        return ok
    end
end

-- Platform: Roblox Luau; target: custom arrow images without distance captions.
-- Insert after ArrowsFolder/EspCache creation, before GetEspElements.
Session.ArrowTextureId = nil
Session.ArrowTextureReady = false
Session.ArrowTextureError = nil
Session.ArrowTextureNotified = false

function Session:ReportArrowTextureFailure(reason)
    if not self.Alive then return end
    self.ArrowTextureError = tostring(reason or "The custom arrow image is unavailable.")
    if self.ArrowTextureNotified then return end
    self.ArrowTextureNotified = true
    local suffix = self.ArrowTextureId and " Loading can still finish later." or " The arrow images remain hidden."
    pcall(function()
        window:Notify({Title = "Arrows", Text = self.ArrowTextureError .. suffix, Kind = "warning"})
    end)
end

function Session:CreateArrow(player)
    local arrowUI = Nova.U.new("Frame", {
        Name = player.Name .. "_Arrow", Size = UDim2.fromOffset(40, 40),
        BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = false,
        AnchorPoint = Vector2.new(0.5, 0.5), Rotation = 0, Visible = false,
        Parent = ArrowsFolder,
    })
    local arrowImage = Nova.U.new("ImageLabel", {
        Name = "Symbol", BackgroundTransparency = 1, BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1), AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5), Image = self.ArrowTextureId or "",
        ImageRectOffset = Vector2.zero, ImageRectSize = Vector2.zero,
        ImageColor3 = Cfg.ArrowsColor, ImageTransparency = 0,
        ScaleType = Enum.ScaleType.Fit, Visible = true, Parent = arrowUI,
    })
    return arrowUI, arrowImage
end

function Session:HideArrow(cache)
    if cache.Arrow.Visible then cache.Arrow.Visible = false end
end

function Session:UpdateArrow(cache, targetRoot, localRoot, cameraFrame, viewport)
    if self.Alive and Cfg.ArrowsEnabled then self:EnsureArrowTexture() end
    local imageLabel = cache.ArrowSym
    if not self.Alive or not Cfg.ArrowsEnabled or not targetRoot or not localRoot
        or not self.ArrowTextureId then
        self:HideArrow(cache)
        return false
    end
    -- As with Target ESP, assign the PNG and let Roblox render/load the image.
    -- IsLoaded must never gate the visibility of its own parent.
    if imageLabel.Image ~= self.ArrowTextureId then imageLabel.Image = self.ArrowTextureId end
    imageLabel.Visible = true
    local distance = (targetRoot.Position - localRoot.Position).Magnitude
    if distance > (tonumber(Cfg.ArrowsDistance) or 100) then
        self:HideArrow(cache)
        return false
    end
    local relative = cameraFrame:PointToObjectSpace(targetRoot.Position)
    if math.abs(relative.X) + math.abs(relative.Z) < 0.0001 then
        self:HideArrow(cache)
        return false
    end
    local angle = math.atan2(relative.X, -relative.Z)
    local dx, dy = math.sin(angle), -math.cos(angle)
    local size = math.clamp(tonumber(Cfg.ArrowsSize) or 22, 8, 60)
    local imageRadius = size * 0.707107
    local radius = math.min(150, math.max(8, math.min(viewport.X, viewport.Y) / 2 - imageRadius - 4))
    local color = Cfg.ArrowsColor
    cache.Arrow.Size = UDim2.fromOffset(size, size)
    cache.Arrow.Position = UDim2.fromOffset(viewport.X / 2 + dx * radius, viewport.Y / 2 + dy * radius)
    -- The supplied image points UP, as did the old triangle: 0 = front/up; 90 = right.
    imageLabel.Rotation = math.deg(angle)
    imageLabel.ImageColor3 = color
    cache.Arrow.Visible = true
    if imageLabel.IsLoaded then
        self.ArrowTextureReady = true
        self.ArrowTextureError = nil
    end

    return true
end

-- Resolve once on first use, after startup. New players share the URI.
function Session:EnsureArrowTexture()
    if not self.Alive or self.ArrowTextureId or self.ArrowTextureRequested then return end
    self.ArrowTextureRequested = true
    task.defer(function()
    if not Session.Alive then return end
    Startup:Mark("arrows-png.begin")
    local ok, id, assetError = pcall(ArrowEspAsset.Get)
    Startup:Mark(ok and id and "arrows-png.ready" or "arrows-png.unavailable")
    if not Session.Alive then return end
    if not ok or type(id) ~= "string" or id == "" then
        Session:ReportArrowTextureFailure(ok and (assetError or ArrowEspAsset.Error) or id)
        return
    end
    Session.ArrowTextureId = id
    for _, cache in pairs(EspCache) do
        if cache.ArrowSym and cache.ArrowSym.Parent then
            cache.ArrowSym.Image = id
            cache.ArrowSym.Visible = true
        end
    end

    -- Preloading is only a hint. A slow preload/local IsLoaded flag must not
    -- hide the PNG or generate a false loading error after an arbitrary timeout.
    task.spawn(function()
        if not Session.Alive then return end
        pcall(function() game:GetService("ContentProvider"):PreloadAsync({id}) end)
    end)
    end)
end

-- Platform: Roblox client / Luau; target: bounded, textured Notification Nova World Cubes.
do
    local cubes = {}
    local MAX_CUBES = 200
    local SPAWN_BUDGET = 8
    local FADE_TIME = 0.65
    local updateDebt = 0
    local faceGradient = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(110, 125, 160))
    local faces = {Enum.NormalId.Front, Enum.NormalId.Back, Enum.NormalId.Left, Enum.NormalId.Right, Enum.NormalId.Top, Enum.NormalId.Bottom}
    local palette = {
        Color3.fromRGB(94, 131, 255), Color3.fromRGB(63, 219, 244),
        Color3.fromRGB(173, 104, 255), Color3.fromRGB(249, 126, 209),
    }
    local atlasId = nil
    local atlasRequested = false
    local folder = Instance.new("Folder")
    folder.Name = "Notification_WorldCubes"
    folder.Parent = Session.Effects
    Session.WorldCubes = cubes
    Session.WorldCubesFolder = folder

    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end

    local function bounded(value, fallback, minimum, maximum)
        return finite(value) and math.clamp(value, minimum, maximum) or fallback
    end

    local function randomBetween(minimum, maximum)
        return minimum + (maximum - minimum) * math.random()
    end

    local function smooth(value)
        value = math.clamp(value, 0, 1)
        return value * value * (3 - 2 * value)
    end

    local function requestAtlas()
        if atlasRequested then return end
        atlasRequested = true
        task.spawn(function()
            local ok, value = pcall(CubeTextureAsset.Get)
            if not Session.Alive then return end
            if ok and type(value) == "string" and value ~= "" then
                atlasId = value
            else
                Session.WorldCubeTextureError = CubeTextureAsset.Error or "Custom texture loading is unavailable; native crystal faces are active."
            end
        end)
    end

    local function removeCube(index)
        local entry = table.remove(cubes, index)
        if entry then entry.Part:Destroy() end
    end

    function Session:ClearWorldCubes()
        for index = #cubes, 1, -1 do removeCube(index) end
        updateDebt = 0
    end

    local function setOpacity(entry, opacity)
        opacity = math.clamp(opacity, 0, 1)
        if entry.Opacity and math.abs(entry.Opacity - opacity) < 0.003 then return end
        entry.Opacity = opacity
        entry.Part.Transparency = 1 - opacity
        entry.Edge.Transparency = 1 - opacity * 0.72
        for _, face in ipairs(entry.Faces) do
            face.Base.BackgroundTransparency = 1 - opacity
            face.Image.ImageTransparency = 1 - opacity * 0.58
            for _, line in ipairs(face.Lines) do line.BackgroundTransparency = 1 - opacity * 0.88 end
        end
    end

    local function pattern(face, texture, color)
        for _, line in ipairs(face.Lines) do line:Destroy() end
        table.clear(face.Lines)
        local function line(x1, y1, x2, y2, width, tint)
            local dx, dy = x2 - x1, y2 - y1
            local stroke = Instance.new("Frame")
            stroke.Name, stroke.BorderSizePixel = "CrystalLine", 0
            stroke.AnchorPoint = Vector2.new(0.5, 0.5)
            stroke.Position = UDim2.fromScale((x1 + x2) / 2, (y1 + y2) / 2)
            stroke.Size = UDim2.fromScale(math.sqrt(dx * dx + dy * dy), (width or 3) / 512)
            stroke.Rotation = math.deg(math.atan2(dy, dx))
            stroke.BackgroundColor3 = tint or color
            stroke.BackgroundTransparency, stroke.ZIndex = 1, 4
            stroke.Parent = face.Base
            table.insert(face.Lines, stroke)
        end
        local pale = color:Lerp(Color3.new(1, 1, 1), 0.65)
        if texture == 1 then
            for n = 0, 2 do
                local y = 0.24 + n * 0.22
                line(0.14, y + 0.16, 0.5, y - 0.05, 7 - n)
                line(0.5, y - 0.05, 0.86, y + 0.02, 7 - n, pale)
            end
        elseif texture == 2 then
            line(0.12, 0.22, 0.5, 0.22, 5); line(0.5, 0.22, 0.5, 0.5, 5)
            line(0.5, 0.5, 0.86, 0.5, 5); line(0.22, 0.42, 0.22, 0.8, 5)
            line(0.22, 0.8, 0.7, 0.8, 5); line(0.7, 0.8, 0.7, 0.65, 5)
            line(0.68, 0.25, 0.84, 0.25, 9, pale)
        elseif texture == 3 then
            for _, point in ipairs({{0.25,0.28}, {0.7,0.38}, {0.42,0.73}}) do
                local x, y = point[1], point[2]
                line(x-0.07,y,x+0.07,y,4,pale); line(x,y-0.07,x,y+0.07,4,pale)
            end
            line(0.25,0.28,0.7,0.38,2); line(0.7,0.38,0.42,0.73,2)
        else
            line(0.12,0.18,0.8,0.82,4,pale); line(0.12,0.18,0.72,0.2,4)
            line(0.72,0.2,0.8,0.82,4); line(0.12,0.18,0.22,0.78,4)
            line(0.22,0.78,0.8,0.82,4,pale); line(0.22,0.78,0.72,0.2,4)
        end
    end

    local function applyAppearance(entry, size, color, texture)
        if entry.Size ~= size then
            entry.Size = size
            entry.Part.Size = Vector3.new(size, size, size)
            entry.Edge.LineThickness = math.clamp(size * 0.025, 0.009, 0.035)
        end
        local canvas = Cfg.LowEndMode and 256 or 512
        if entry.Canvas ~= canvas then
            entry.Canvas = canvas
            for _, face in ipairs(entry.Faces) do face.Surface.CanvasSize = Vector2.new(canvas, canvas) end
        end
        if entry.Color == color and entry.Texture == texture and entry.Asset == atlasId then return end
        entry.Color, entry.Texture, entry.Asset = color, texture, atlasId
        local accent = palette[texture]:Lerp(color, 0.25)
        entry.Part.Color = accent:Lerp(Color3.new(0, 0, 0), 0.65)
        entry.Edge.Color3 = accent:Lerp(Color3.new(1, 1, 1), 0.38)
        local column, row = (texture - 1) % 2, math.floor((texture - 1) / 2)
        for _, face in ipairs(entry.Faces) do
            face.Base.BackgroundColor3 = accent:Lerp(Color3.new(0, 0, 0), 0.75)
            face.Gradient.Color = faceGradient
            face.Gradient.Rotation = 35 + (texture - 1) * 25
            pattern(face, texture, accent)
            face.Image.ImageColor3 = color
            -- Select a quadrant in normalized coordinates. Full-image sampling
            -- remains correct if Roblox scales the 2x2 atlas during decoding.
            face.Image.Position = UDim2.fromScale(-column, -row)
            face.Image.Image = atlasId or ""
            face.Image.Visible = atlasId ~= nil
        end
        entry.Opacity = nil
    end

    local function seed(entry, center)
        local angle = randomBetween(0, math.pi * 2)
        local radius = math.sqrt(randomBetween(36, 576))
        entry.Origin = center + Vector3.new(math.cos(angle) * radius, randomBetween(-0.5, 9), math.sin(angle) * radius)
        entry.Age = 0
        entry.Lifetime = randomBetween(13, 21)
        entry.Time = randomBetween(0, 12)
        entry.Phase = randomBetween(0, math.pi * 2)
        entry.Angles = Vector3.new(randomBetween(0, math.pi), randomBetween(0, math.pi), randomBetween(0, math.pi))
        entry.Spin = Vector3.new(randomBetween(-0.28, 0.28), randomBetween(0.22, 0.46), randomBetween(-0.2, 0.2))
        entry.RecycleAge = nil
        entry.Opacity = nil
        setOpacity(entry, 0)
        entry.Part.CFrame = CFrame.new(entry.Origin) * CFrame.Angles(entry.Angles.X, entry.Angles.Y, entry.Angles.Z)
    end

    local function createCube(center, size, color, texture)
        local part = Instance.new("Part")
        part.Name = "WorldCube"
        part.Shape = Enum.PartType.Block
        part.Size = Vector3.new(size, size, size)
        part.Anchored = true
        part.CanCollide = false
        part.CanTouch = false
        part.CanQuery = false
        part.CastShadow = false
        part.Material = Enum.Material.Metal
        part.Reflectance = 0.12
        part.Transparency = 1
        part.TopSurface = Enum.SurfaceType.Smooth
        part.BottomSurface = Enum.SurfaceType.Smooth
        local edge = Instance.new("SelectionBox")
        edge.Name, edge.Adornee, edge.SurfaceTransparency = "CrystalEdges", part, 1
        edge.Transparency, edge.Parent = 1, part
        local entry = {Part = part, Edge = edge, Faces = {}, RetireAge = 0}
        for _, direction in ipairs(faces) do
            local surface = Instance.new("SurfaceGui")
            surface.Name = "Face" .. direction.Name
            surface.Face = direction
            surface.Adornee = part
            surface.AlwaysOnTop = false
            surface.LightInfluence = 0.25
            surface.Brightness = 1
            surface.MaxDistance = 60
            surface.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
            surface.CanvasSize = Vector2.new(512, 512)
            surface.ZOffset = 0.002
            surface.Active = false
            surface.Parent = part

            local base = Instance.new("Frame")
            base.Name = "NativeCrystal"
            base.Size = UDim2.fromScale(1, 1)
            base.BorderSizePixel = 0
            base.BackgroundTransparency = 1
            base.ClipsDescendants = true
            base.ZIndex = 1
            base.Parent = surface
            local gradient = Instance.new("UIGradient")
            gradient.Parent = base
            local image = Instance.new("ImageLabel")
            image.Name = "AtlasTexture"
            image.BackgroundTransparency = 1
            image.BorderSizePixel = 0
            image.Size = UDim2.fromScale(2, 2)
            image.ImageRectOffset = Vector2.new(0, 0)
            image.ImageRectSize = Vector2.new(0, 0)
            image.ImageTransparency = 1
            image.ScaleType = Enum.ScaleType.Stretch
            image.ZIndex = 3
            image.Visible = false
            image.Parent = base
            table.insert(entry.Faces, {Surface = surface, Base = base, Gradient = gradient, Lines = {}, Image = image})
        end
        applyAppearance(entry, size, color, texture)
        seed(entry, center)
        part.Parent = folder
        table.insert(cubes, entry)
        return entry
    end

    function Session:UpdateWorldCubes(dt)
        local camera = workspace.CurrentCamera
        if not self.Alive or not Cfg.WorldParticlesEnabled or not camera then
            if #cubes > 0 then self:ClearWorldCubes() end
            return
        end
        if not folder.Parent then self:ClearWorldCubes(); return end
        requestAtlas()
        local delta = finite(dt) and math.clamp(dt, 0, 0.25) or 0
        if Cfg.LowEndMode then
            updateDebt += delta
            if updateDebt < 1/30 and #cubes > 0 then return end
            delta, updateDebt = updateDebt, 0
        else updateDebt = 0 end
        local amount = math.floor(bounded(Cfg.WorldParticlesAmount, 40, 1, Cfg.LowEndMode and 40 or MAX_CUBES))
        local size = bounded(Cfg.WorldCubeSize, 0.45, 0.15, 1.5)
        local speed = bounded(Cfg.WorldCubeSpeed, 0.6, 0.1, 2)
        local texture = math.floor(bounded(Cfg.WorldCubeTexture, 1, 1, 4))
        local color = typeof(Cfg.WorldParticlesColor) == "Color3" and Cfg.WorldParticlesColor or Color3.new(1, 1, 1)
        local center = camera.CFrame.Position
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root and root:IsA("BasePart") and (root.Position - center).Magnitude < 24 then
            center = root.Position + Vector3.new(0, 2, 0)
        end
        for _ = 1, math.min(Cfg.LowEndMode and 2 or SPAWN_BUDGET, math.max(0, amount - #cubes)) do createCube(center, size, color, texture) end

        for index = #cubes, 1, -1 do
            local entry = cubes[index]
            if not entry.Part.Parent then
                removeCube(index)
            else
                applyAppearance(entry, size, color, texture)
                entry.Age += delta
                entry.Time += delta * speed
                entry.Angles += entry.Spin * (delta * speed)
                local phase, time = entry.Phase, entry.Time
                local offset = Vector3.new(math.sin(time * 0.63 + phase) * 0.7, math.sin(time * 0.95 + phase) * 0.8, math.cos(time * 0.57 + phase) * 0.7)
                local position = entry.Origin + offset
                local distance = (position - center).Magnitude
                if distance > 40 then
                    -- Teleports recycle the same objects while fully invisible.
                    seed(entry, center)
                    position = entry.Origin
                elseif distance > 32 or entry.RecycleAge then
                    entry.RecycleAge = (entry.RecycleAge or 0) + delta
                    if entry.RecycleAge >= FADE_TIME then seed(entry, center); position = entry.Origin end
                elseif entry.Age >= entry.Lifetime then
                    seed(entry, center)
                    position = entry.Origin
                end
                if index > amount then entry.RetireAge += delta else entry.RetireAge = 0 end
                if entry.RetireAge >= FADE_TIME then
                    removeCube(index)
                else
                    local opacity = smooth(entry.Age / FADE_TIME) * smooth((entry.Lifetime - entry.Age) / 1.1)
                    if entry.RecycleAge then opacity *= 1 - smooth(entry.RecycleAge / FADE_TIME) end
                    if entry.RetireAge > 0 then opacity *= 1 - smooth(entry.RetireAge / FADE_TIME) end
                    setOpacity(entry, opacity)
                    entry.Part.CFrame = CFrame.new(position) * CFrame.Angles(entry.Angles.X, entry.Angles.Y, entry.Angles.Z)
                end
            end
        end
    end
end

-- Platform: Roblox client / Luau; target: idle visuals and character traversal caches.
do
    Session.EmptyPlayers = {}
    local renderDebt, chamsDebt = 0, 0
    function Session:PlayerVisualDue(dt, chams)
        if not Cfg.LowEndMode then renderDebt, chamsDebt = 0, 0; return true end
        if chams then
            chamsDebt += math.max(0, dt)
            if self.ChamsForce or chamsDebt >= 0.1 then chamsDebt = 0; self.ChamsForce = false; return true end
        else
            renderDebt += math.max(0, dt)
            if self.PlayerVisualForce or renderDebt >= 1/30 then renderDebt = 0; self.PlayerVisualForce = false; return true end
        end
        return false
    end
    local parts, indexes, connections = {}, {}, {}
    local currentCharacter
    local function add(part)
        if part:IsA("BasePart") and not indexes[part] then
            table.insert(parts, part); indexes[part] = #parts
        end
    end
    local function remove(part)
        local index = indexes[part]
        if not index then return end
        local last = parts[#parts]
        parts[#parts] = nil
        indexes[part] = nil
        if last ~= part then parts[index] = last; indexes[last] = index end
    end
    function Session:ClearCharacterParts()
        for _, connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections); table.clear(parts); table.clear(indexes)
        currentCharacter = nil
    end
    function Session:GetCharacterParts(character)
        if character ~= currentCharacter then
            self:ClearCharacterParts()
            currentCharacter = character
            if character then
                for _, part in ipairs(character:GetDescendants()) do add(part) end
                self:Connect(character.DescendantAdded, add, connections)
                self:Connect(character.DescendantRemoving, remove, connections)
            end
        end
        return parts
    end
    local previousBox, previousArrows, previousChams
    function Session:SyncPlayerVisualActivation()
        if previousBox == Cfg.Esp2DBoxEnabled and previousArrows == Cfg.ArrowsEnabled
            and previousChams == Cfg.ChamsEnabled then return end
        previousBox, previousArrows, previousChams = Cfg.Esp2DBoxEnabled, Cfg.ArrowsEnabled, Cfg.ChamsEnabled
        self.PlayerVisualForce, self.ChamsForce = true, true
        for _, cache in pairs(EspCache) do
            if not previousBox and cache.Box2D.Visible then cache.Box2D.Visible = false end
            if not previousArrows then self:HideArrow(cache) end
            if not previousChams and cache.ChamsHighlight.Enabled then cache.ChamsHighlight.Enabled = false end
        end
    end
end


-- Platform: Roblox client / Luau; target: cached Box ESP appearance matching the Nova interface.
-- Shared menu shadows and card details with perspective-correct nametags.
do
    local WHITE, BLACK = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
    local REFERENCE_TANGENT = math.tan(math.rad(35))
    local function finite(value, fallback)
        value = tonumber(value)
        return if value and value == value and math.abs(value) < math.huge then value else fallback
    end
    local function make(class, parent, name)
        local object = Instance.new(class)
        object.Name, object.Parent = name, parent
        return object
    end
    local function corner(parent)
        return make("UICorner", parent, "Corner")
    end
    local function stroke(parent, thickness, transparency)
        local object = make("UIStroke", parent, "Outline")
        object.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        object.Thickness, object.Transparency = thickness, transparency
        return object
    end
    local function frame(parent, name, transparency, z)
        local object = make("Frame", parent, name)
        object.BorderSizePixel, object.BackgroundTransparency, object.ZIndex = 0, transparency, z or 1
        return object
    end
    local function texture(parent, kind, name, radius, z)
        -- Nova owns the cached texture and its radius refresh. Creation is once per player.
        local ok, image = pcall(Nova.Tex.image, parent, kind, {
            Name = name, Size = UDim2.fromScale(1, 1), SliceScale = radius,
            ImageColor3 = WHITE, ZIndex = z,
        })
        return if ok then image else nil
    end
    local function shadow(parent, name, z)
        local image = texture(parent, "shadow9", name, 0.625, z)
        if image then image.ImageColor3 = BLACK; return image, true end
        local fallback = frame(parent, name, 0.65, z)
        fallback.BackgroundColor3 = BLACK
        corner(fallback).CornerRadius = UDim.new(0, 8)
        return fallback, false
    end
    local function tint(image, color)
        if image then image.ImageColor3 = color end
    end
    local function alpha(image, value)
        if image then image.ImageTransparency = value end
    end
    local function retarget(image, radius)
        if not image then return end
        local info = Nova.Tex.tracked[image]
        if info then info.base = radius; Nova.Tex.retarget(image) end
    end
    function Session:CreateBoxEsp(cache, player, parent)
        local box = frame(parent, player.Name .. "_2DBox", 1, 2)
        box.Visible, box.ClipsDescendants = false, false
        cache.Box2D, cache.BoxCorner = box, corner(box)
        cache.BoxStroke = stroke(box, 1.2, 0.12)
        cache.BoxGrad = make("UIGradient", cache.BoxStroke, "EdgeLighting")
        cache.BoxGrad.Color, cache.BoxGrad.Rotation = ColorSequence.new(WHITE, Color3.fromRGB(184, 188, 201)), 90
        cache.BoxRim = texture(box, "rim9", "MenuRim", 4 / 14, 3)
        -- Four outside-only clips reuse the actual menu shadow. Its opaque center can
        -- never cover the player when the optional box fill is disabled.
        cache.BoxShadowClips = {}
        for _, name in ipairs({"Top", "Bottom", "Left", "Right"}) do
            local clip = frame(box, "Shadow" .. name, 1, 0)
            clip.ClipsDescendants = true
            local image = texture(clip, "shadow9", "MenuShadow", 0.625, 0)
            if image then image.ImageColor3 = BLACK end
            cache.BoxShadowClips[#cache.BoxShadowClips + 1] = {Frame = clip, Image = image}
        end
        local fallback = frame(box, "OutlineShadowFallback", 1, 0)
        fallback.Position, fallback.Size = UDim2.fromOffset(0, 2), UDim2.fromScale(1, 1)
        cache.BoxShadowFallback, cache.BoxShadowCorner = fallback, corner(fallback)
        cache.BoxShadowStroke = stroke(fallback, 3, 0.6)
        cache.BoxShadowStroke.Color = BLACK
        fallback.Visible = cache.BoxShadowClips[1].Image == nil

        -- The zero-size anchor keeps the panel above the head. UIScale affects the
        -- complete card, shadow, text and top gap, without rounding TextSize per frame.
        local nameRoot = frame(box, "NameAnchor", 1, 5)
        nameRoot.Position, nameRoot.Size = UDim2.fromScale(0.5, 0), UDim2.fromOffset(0, 0)
        cache.NameRoot, cache.NameScale = nameRoot, make("UIScale", nameRoot, "PerspectiveScale")
        cache.NameShadow, cache.NameShadowIsImage = shadow(nameRoot, "MenuShadow", 4)
        cache.NameShadow.AnchorPoint = Vector2.new(0.5, 1)
        local plate = frame(nameRoot, "Nameplate", 0.03, 5)
        plate.AnchorPoint, plate.Position = Vector2.new(0.5, 1), UDim2.fromOffset(0, -7)
        cache.NamePlate, cache.NameCorner, cache.NameStroke = plate, corner(plate), stroke(plate, 1, 0.85)
        cache.NameCardGradient = make("UIGradient", plate, "CardGradient")
        cache.NameCardGradient.Rotation = 90
        cache.NameGloss = texture(plate, "gloss9", "Gloss", 8 / 14, 5)
        cache.NameGrain = texture(plate, "grain", "Grain", 1, 5)
        cache.NameRim = texture(plate, "rim9", "MenuRim", 8 / 14, 7)
        cache.NameCardStyle = {Card = plate, CardGrad = cache.NameCardGradient, Gloss = cache.NameGloss, Grain = cache.NameGrain}
        local label = make("TextLabel", plate, "Nametag")
        label.BackgroundTransparency, label.BorderSizePixel, label.ZIndex = 1, 0, 6
        label.TextStrokeTransparency, label.TextWrapped = 1, false
        label.TextTruncate = Enum.TextTruncate.AtEnd
        label.TextXAlignment, label.TextYAlignment = Enum.TextXAlignment.Center, Enum.TextYAlignment.Center
        label.Position, label.Size = UDim2.fromOffset(10, 0), UDim2.new(1, -20, 1, 0)
        cache.NameTag = label

        cache.HealthShadow, cache.HealthShadowIsImage = shadow(box, "HealthShadow", 0)
        local rail = frame(box, "HealthBarBack", 0.03, 3)
        rail.ClipsDescendants = false
        cache.HealthBack, cache.HealthCorner, cache.HealthStroke = rail, corner(rail), stroke(rail, 1, 0.7)
        cache.HealthRim = texture(rail, "rim9", "MenuRim", 3 / 14, 5)
        local fill = frame(rail, "HealthBarFill", 0, 4)
        fill.AnchorPoint, fill.Position = Vector2.new(0, 1), UDim2.fromScale(0, 1)
        fill.Size = UDim2.fromScale(1, 1)
        cache.HealthFill, cache.HealthFillCorner = fill, corner(fill)
        cache.HealthGradient = make("UIGradient", fill, "HealthGradient")
        cache.HealthGradient.Rotation = 90
        cache.HealthGradF = fill
    end

    function Session:UpdateBoxEspStyle(cache, player, depth, viewportHeight, fieldOfView)
        local tokens, ui, fonts = Nova.Theme.tokens, Nova.U, Nova.Font
        local sync = Cfg.Esp2DBoxSyncColor ~= false
        local accent = if sync then tokens.Accent else Cfg.Esp2DBoxColor
        if typeof(accent) ~= "Color3" then accent = tokens.Accent end
        local fillColor = Cfg.Esp2DBoxFillColor
        if typeof(fillColor) ~= "Color3" then fillColor = accent end
        local opacity = math.clamp(finite(window.Opacity, 1), 0.5, 1)
        local cardStyle, intensity = window.CardStyle or "Glass", math.clamp(finite(window.BgIntensity, 1), 0, 1.5)
        if cache.StyleAccent ~= accent or cache.StyleFillColor ~= fillColor
            or cache.StyleSurface ~= tokens.Surface or cache.StyleElevated ~= tokens.Elevated
            or cache.StyleText ~= tokens.Text or cache.StyleGlass ~= tokens.Glass
            or cache.StyleSync ~= sync or cache.StyleSuccess ~= tokens.Success or cache.StyleDanger ~= tokens.Danger
            or cache.StyleCard ~= cardStyle or cache.StyleOpacity ~= opacity or cache.StyleIntensity ~= intensity then
            cache.StyleAccent, cache.StyleFillColor, cache.StyleSync = accent, fillColor, sync
            cache.StyleSurface, cache.StyleElevated = tokens.Surface, tokens.Elevated
            cache.StyleText, cache.StyleGlass = tokens.Text, tokens.Glass
            cache.StyleSuccess, cache.StyleDanger = tokens.Success, tokens.Danger
            cache.StyleCard, cache.StyleOpacity, cache.StyleIntensity = cardStyle, opacity, intensity
            cache.BoxStroke.Color = accent
            tint(cache.BoxRim, tokens.Glass)
            cache.Box2D.BackgroundColor3 = if sync then tokens.Surface:Lerp(accent, 0.12) else fillColor
            cache.NamePlate.BackgroundColor3, cache.NameTag.TextColor3 = tokens.Surface, tokens.Text
            cache.NameStroke.Color = tokens.Glass
            tint(cache.NameRim, tokens.Glass)
            window:_applyCardStyle(cache.NameCardStyle)
            if cardStyle == "Tinted" and not sync then
                cache.NameCardGradient.Color = ColorSequence.new(WHITE:Lerp(accent, 0.05), WHITE:Lerp(accent, 0.34))
            end
            cache.NamePlate.BackgroundTransparency = 1 - (1 - cache.NamePlate.BackgroundTransparency) * opacity
            if cache.NameGloss then cache.NameGloss.ImageTransparency = 1 - (1 - cache.NameGloss.ImageTransparency) * opacity end
            if cache.NameGrain then cache.NameGrain.ImageTransparency = math.clamp(1 - (1 - cache.NameGrain.ImageTransparency) * intensity * opacity, 0, 1) end
            cache.NameStroke.Transparency, cache.NameTag.TextTransparency = 1 - 0.15 * opacity, 1 - opacity
            alpha(cache.NameRim, 1 - 0.5 * opacity)
            if cache.NameShadowIsImage then cache.NameShadow.ImageTransparency = 1 - 0.48 * opacity
            else cache.NameShadow.BackgroundTransparency = 1 - 0.35 * opacity end
            cache.BoxStroke.Transparency = 1 - 0.88 * opacity
            alpha(cache.BoxRim, 1 - 0.45 * opacity)
            for _, piece in ipairs(cache.BoxShadowClips) do alpha(piece.Image, 1 - 0.65 * opacity) end
            cache.BoxShadowStroke.Transparency = 1 - 0.4 * opacity
            cache.HealthBack.BackgroundColor3, cache.HealthStroke.Color = tokens.Elevated, tokens.Glass
            cache.HealthBack.BackgroundTransparency, cache.HealthStroke.Transparency = 1 - 0.97 * opacity, 1 - 0.3 * opacity
            cache.HealthFill.BackgroundTransparency = 1 - opacity
            tint(cache.HealthRim, tokens.Glass); alpha(cache.HealthRim, 1 - 0.45 * opacity)
            if cache.HealthShadowIsImage then cache.HealthShadow.ImageTransparency = 1 - 0.45 * opacity
            else cache.HealthShadow.BackgroundTransparency = 1 - 0.35 * opacity end
            cache.HealthGradient.Color = ColorSequence.new(WHITE, Color3.fromRGB(194, 199, 211))
            cache.HealthStyleDirty = true
        end
        local fillAlpha = if Cfg.Esp2DBoxFillEnabled then math.clamp(finite(Cfg.Esp2DBoxFillTrans, 0.5), 0, 1) else 1
        local actualFillAlpha = 1 - (1 - fillAlpha) * opacity
        if cache.StyleFillAlpha ~= actualFillAlpha then
            cache.StyleFillAlpha, cache.Box2D.BackgroundTransparency = actualFillAlpha, actualFillAlpha
        end
        local radiusMultiplier = math.clamp(finite(ui.radiusMult, 1), 0, 2)
        local baseRadius = math.max(0, finite(Cfg.Esp2DBoxRounding, 4))
        local radius, cardRadius = baseRadius * radiusMultiplier, 8 * radiusMultiplier
        if cache.StyleRadius ~= radius or cache.StyleCardRadius ~= cardRadius then
            cache.StyleRadius, cache.StyleCardRadius = radius, cardRadius
            local rounded = UDim.new(0, radius)
            cache.BoxCorner.CornerRadius, cache.BoxShadowCorner.CornerRadius = rounded, rounded
            cache.NameCorner.CornerRadius = UDim.new(0, cardRadius)
            local railRadius = UDim.new(0, math.min(3, cardRadius))
            cache.HealthCorner.CornerRadius, cache.HealthFillCorner.CornerRadius = railRadius, railRadius
            if not cache.NameShadowIsImage then cache.NameShadow.Corner.CornerRadius = UDim.new(0, cardRadius + 1) end
            if not cache.HealthShadowIsImage then cache.HealthShadow.Corner.CornerRadius = railRadius end
            retarget(cache.BoxRim, baseRadius)
            if cache.BoxRim then cache.BoxRim.Visible = radius > 0 end
            if cache.NameRim then cache.NameRim.Visible = cardRadius > 0 end
            if cache.NameGloss then cache.NameGloss.Visible = cardRadius > 0 end
            if cache.HealthRim then cache.HealthRim.Visible = cardRadius > 0 end
        end
        local width, height = math.max(0, finite(cache.Box2D.Size.X.Offset, 0)), math.max(0, finite(cache.Box2D.Size.Y.Offset, 0))
        if cache.ShadowWidth ~= width or cache.ShadowHeight ~= height then
            cache.ShadowWidth, cache.ShadowHeight = width, height
            local pad = 20
            local clips = cache.BoxShadowClips
            clips[1].Frame.Position, clips[1].Frame.Size = UDim2.fromOffset(-pad, -pad), UDim2.fromOffset(width + pad * 2, pad)
            clips[2].Frame.Position, clips[2].Frame.Size = UDim2.fromOffset(-pad, height), UDim2.fromOffset(width + pad * 2, pad + 3)
            clips[3].Frame.Position, clips[3].Frame.Size = UDim2.fromOffset(-pad, 0), UDim2.fromOffset(pad, height)
            clips[4].Frame.Position, clips[4].Frame.Size = UDim2.fromOffset(width, 0), UDim2.fromOffset(pad, height)
            for _, piece in ipairs(clips) do
                if piece.Image then piece.Image.Size = UDim2.fromOffset(width + pad * 2, height + pad * 2) end
            end
            if clips[1].Image then clips[1].Image.Position = UDim2.fromOffset(0, 3) end
            if clips[2].Image then clips[2].Image.Position = UDim2.fromOffset(0, -height - pad + 3) end
            if clips[3].Image then clips[3].Image.Position = UDim2.fromOffset(0, -pad + 3) end
            if clips[4].Image then clips[4].Image.Position = UDim2.fromOffset(-width - pad, -pad + 3) end
        end
        if cache.StyleFont ~= fonts.id then
            cache.StyleFont = fonts.id
            cache.NameTag.FontFace = fonts.Semi()
        end
        local cameraDepth = if depth == nil then 20 else finite(depth, 0)
        local viewport = if viewportHeight == nil then 720 else finite(viewportHeight, 0)
        local fov = math.clamp(finite(fieldOfView, 70), 1, 179)
        local perspective = if cameraDepth > 0.05 and viewport > 0 then
            math.min(6, 20 / cameraDepth * (viewport / 720) * REFERENCE_TANGENT / math.tan(math.rad(fov * 0.5))) else 0
        if cache.NamePerspectiveScale ~= perspective then
            cache.NamePerspectiveScale, cache.NameScale.Scale = perspective, perspective
        end
        local showName = Cfg.Esp2DBoxNametagsEnabled == true and perspective >= 0.035
        if cache.NameRoot.Visible ~= showName then cache.NameRoot.Visible = showName end
        if cache.NamePlate.Visible ~= showName then cache.NamePlate.Visible = showName end
        if cache.NameTag.Visible ~= showName then cache.NameTag.Visible = showName end
        if showName then
            local size = math.max(8, math.floor(finite(Cfg.Esp2DBoxNametagsScale, 14) * finite(ui.textScale, 1) + 0.5))
            local name = tostring(player.DisplayName or player.Name)
            if cache.StyleTextSize ~= size or cache.StyleName ~= name then
                cache.StyleTextSize, cache.StyleName = size, name
                cache.NameTag.Text, cache.NameTag.TextSize = name, size
                local count = utf8.len(name) or #name
                local panelWidth, panelHeight = math.clamp(math.ceil(count * size * 0.63) + 20, 72, 260), size + 12
                cache.NamePlate.Size = UDim2.fromOffset(panelWidth, panelHeight)
                if cache.NameShadowIsImage then
                    cache.NameShadow.Size, cache.NameShadow.Position = UDim2.fromOffset(panelWidth + 40, panelHeight + 40), UDim2.fromOffset(0, 16)
                else
                    cache.NameShadow.Size, cache.NameShadow.Position = UDim2.fromOffset(panelWidth + 2, panelHeight + 2), UDim2.fromOffset(0, -4)
                end
            end
        end
        local showHealth = Cfg.Esp2DBoxHealthBarEnabled == true
        if cache.HealthBack.Visible ~= showHealth then cache.HealthBack.Visible = showHealth end
        if cache.HealthShadow.Visible ~= showHealth then cache.HealthShadow.Visible = showHealth end
        if showHealth then
            local border = math.clamp(finite(Cfg.Esp2DBoxHealthBarBorder, 1), 0, 5)
            if cache.HealthBorder ~= border then
                cache.HealthBorder = border
                cache.HealthStroke.Thickness, cache.HealthStroke.Enabled = border, border > 0
                cache.HealthBack.Size, cache.HealthBack.Position = UDim2.new(0, 4, 1, 0), UDim2.new(0, -(8 + border), 0, 0)
                if cache.HealthShadowIsImage then
                    cache.HealthShadow.Size, cache.HealthShadow.Position = UDim2.new(0, 44, 1, 40), UDim2.new(0, -(28 + border), 0, -17)
                else
                    cache.HealthShadow.Size, cache.HealthShadow.Position = UDim2.new(0, 6, 1, 2), UDim2.new(0, -(9 + border), 0, 1)
                end
            end
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local health, maximum = humanoid and humanoid.Health or 0, humanoid and humanoid.MaxHealth or 0
            local fraction = if finite(health, 0) == health and finite(maximum, 0) == maximum and maximum > 0 then math.clamp(health / maximum, 0, 1) else 0
            if cache.HealthFraction ~= fraction or cache.HealthStyleDirty then
                cache.HealthFraction = fraction
                cache.HealthFill.Size, cache.HealthFill.Visible = UDim2.fromScale(1, fraction), fraction > 0
                cache.HealthFill.BackgroundColor3 = if sync then accent else tokens.Danger:Lerp(tokens.Success, fraction)
                cache.HealthStyleDirty = false
            end
        end
    end
end
-- End cached Box ESP appearance.

local function GetEspElements(player)
    if not EspCache[player] then
        local cache = {}
        Session:CreateBoxEsp(cache, player, Esp2DFolder)

        local chamsHL = Instance.new("Highlight", Chams3DFolder); chamsHL.Name = player.Name .. "_Chams"; chamsHL.Enabled = false
        cache.ChamsHighlight = chamsHL

        local arrowUI, arrowSym = Session:CreateArrow(player)
        cache.Arrow = arrowUI; cache.ArrowSym = arrowSym
        EspCache[player] = cache
    end
    return EspCache[player]
end

Session:Connect(Players.PlayerRemoving, function(player)
    if EspCache[player] then
        if EspCache[player].Box2D then EspCache[player].Box2D:Destroy() end
        if EspCache[player].ChamsHighlight then EspCache[player].ChamsHighlight:Destroy() end
        if EspCache[player].Arrow then EspCache[player].Arrow:Destroy() end
        EspCache[player] = nil; EspHiddenState[player] = nil
    end
end)

-- // CORE LOGIC
local function IsVisible(targetPart)
    if not targetPart or not targetPart.Parent or not targetPart:IsA("BasePart") then return false end
    local Camera = workspace.CurrentCamera; if not Camera then return false end
    local char = LocalPlayer.Character
    if not char or not char:FindFirstChild("HumanoidRootPart") then return false end
    local origin = Camera.CFrame.Position; local direction = targetPart.Position - origin
    if not Session:IsFiniteVector(origin) or not Session:IsFiniteVector(direction) then return false end
    if direction.Magnitude <= 0.001 then return true end
    local raycastParams = RaycastParams.new(); raycastParams.FilterDescendantsInstances = {char, Camera, targetPart.Parent, Chams3DFolder, Session.Effects, Session.WorldCubesFolder}; raycastParams.FilterType = Enum.RaycastFilterType.Exclude
    return workspace:Raycast(origin, direction, raycastParams) == nil 
end

-- Platform: Roblox client / Luau; target: independent aim, aura and orbit target locks.
do
    local selected = {}
    local leaving = setmetatable({}, {__mode = "k"})
    local localCharacter
    local function clear()
        table.clear(selected)
        Session.AimbotTarget, Session.KaTarget, Session.StrafeTarget = nil, nil, nil
        SharedTarget, SharedKaTarget = nil, nil
    end
    function Session:ResetTargetLocks()
        clear()
        localCharacter = nil
    end
    local function better(candidate, best)
        if not best then return true end
        if candidate.Distance ~= best.Distance then return candidate.Distance < best.Distance end
        return candidate.Player.UserId < best.Player.UserId
    end
    local function choose(slot, active, locked, candidates, best)
        if not active then selected[slot] = nil; return nil end
        local previous = selected[slot]
        local current = previous and candidates[previous.Player]
        local nextTarget = if locked and current and current.Character == previous.Character then current else best
        selected[slot] = nextTarget
        return nextTarget and nextTarget.Player or nil
    end
    function Session:UpdateTargets()
        if not self.Alive or not self.Ready then clear(); return end
        local character = LocalPlayer.Character
        if character ~= localCharacter then clear(); localCharacter = character end
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not character or not character.Parent or not root or not humanoid or humanoid.Health <= 0 then
            clear(); return
        end
        local wantGeneral = Cfg.AimbotEnabled or Cfg.TargetStrafeOrbitEnabled or Cfg.TargetHudEnabled
            or Cfg.TargetESPSquareEnabled or Cfg.ArrowsEnabled or Cfg.DamageNumbersEnabled
        if not wantGeneral and not Cfg.KillAuraEnabled then clear(); return end
        local general, aura = {}, {}
        local closestGeneral, closestAura
        for _, player in ipairs(Players:GetPlayers()) do
            local model = player.Character
            local part = model and model:FindFirstChild("HumanoidRootPart")
            local hum = model and model:FindFirstChildOfClass("Humanoid")
            if player ~= LocalPlayer and not self:IsFriend(player) and not leaving[player] and model and model.Parent and part and hum and hum.Health > 0 then
                local distance = (part.Position - root.Position).Magnitude
                local sameTeam = player.Team ~= nil and player.Team == LocalPlayer.Team
                local ignoredTeam = player.Team and Cfg["AimbotIgnore_" .. player.Team.Name]
                local generalEligible = wantGeneral and distance < Cfg.AimbotMaxDistance
                    and (not Cfg.AimbotTeamCheck or not sameTeam) and not ignoredTeam
                local auraEligible = Cfg.KillAuraEnabled and distance <= Cfg.KillAuraRange
                local visible = false
                if auraEligible or (generalEligible and Cfg.AimbotWallCheck) then visible = IsVisible(part) end
                local candidate = {Player=player, Character=model, Distance=distance}
                if generalEligible and (not Cfg.AimbotWallCheck or visible) then
                    general[player] = candidate
                    if better(candidate, closestGeneral) then closestGeneral = candidate end
                end
                if auraEligible and visible then
                    aura[player] = candidate
                    if better(candidate, closestAura) then closestAura = candidate end
                end
            end
        end
        self.AimbotTarget = choose("Aim", Cfg.AimbotEnabled, Cfg.AimbotTargetLock, general, closestGeneral)
        self.StrafeTarget = choose("Strafe", Cfg.TargetStrafeOrbitEnabled, Cfg.TargetStrafeTargetLock, general, closestGeneral)
        self.KaTarget = choose("Aura", Cfg.KillAuraEnabled, Cfg.KillAuraTargetLock, aura, closestAura)
        SharedKaTarget = self.KaTarget
        -- Keep the existing common visual target useful without coupling the locks.
        SharedTarget = self.AimbotTarget or self.StrafeTarget or (closestGeneral and closestGeneral.Player)
    end
    Session:Connect(Players.PlayerRemoving, function(player)
        leaving[player] = true
        for slot, record in pairs(selected) do
            if record.Player == player then selected[slot] = nil end
        end
        Session:UpdateTargets()
    end)
    task.spawn(function()
        while Session.Alive do
            -- Active melee needs prompt acquisition; idle visuals keep the cheaper cadence.
            task.wait(Cfg.KillAuraEnabled and 0.05 or 0.2)
            if not Session.Alive then break end
            Session:UpdateTargets()
        end
    end)
end


task.spawn(function()
    while Session.Alive do
        task.wait(3)
        if not Session.Alive then break end 
        if Cfg.AntiFlingEnabled then
            local newCache = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and not Session:IsFriend(p) and p.Character then
                    local parts = {}
                    local desc = p.Character:GetDescendants()
                    for j = 1, #desc do if desc[j]:IsA("BasePart") then table.insert(parts, desc[j]) end end
                    if #parts > 0 then newCache[p] = parts end
                end
            end
            AntiFlingCache = newCache
        else
            if next(AntiFlingCache) ~= nil then AntiFlingCache = {} end
            Session:RestoreAntiFling()
        end
    end
end)

-- Platform: Roblox client / Luau; target: bounded 3D liquid hit splashes.
do
    local drops, LIMIT, STEP = {}, 160, 1 / 60
    local accumulator = 0
    local folder = Instance.new("Folder")
    folder.Name, folder.Parent = "Notification_HitSplashes", Session.Effects
    Session.HitSplashes, Session.HitSplashFolder = drops, folder
    local function number(value, fallback, low, high)
        return type(value) == "number" and value == value and math.abs(value) < math.huge and math.clamp(value, low, high) or fallback
    end
    local function remove(index)
        local drop = table.remove(drops, index)
        if drop then drop.Part:Destroy() end
    end
    function Session:ClearHitSplashes()
        for i = #drops, 1, -1 do remove(i) end
        accumulator = 0
    end
    function Session:ClearFriendlyHitSplashes()
        for i = #drops, 1, -1 do
            if self:IsFriend(drops[i].UserId) then remove(i) end
        end
    end
    function Session:EmitHitSplash(position, normal, ignoreCharacter)
        if not self.Alive or not Cfg.DamageParticlesEnabled or typeof(position) ~= "Vector3" then return end
        local userId = self:CharacterUserId(ignoreCharacter)
        if self:IsFriend(userId) then return end
        local limit = Cfg.LowEndMode and 64 or LIMIT
        local amount = math.floor(number(Cfg.ParticleAmount, 8, 1, Cfg.LowEndMode and 12 or 40))
        local speed = number(Cfg.ParticleSpeed, 16, 1, 60)
        local camera = workspace.CurrentCamera
        local direction = typeof(normal) == "Vector3" and normal or (camera and camera.CFrame.Position - position or Vector3.new(0, 1, 0))
        direction = direction.Magnitude > 0.001 and direction.Unit or Vector3.new(0, 1, 0)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local exclusions = {self.Effects}
        if LocalPlayer.Character then table.insert(exclusions, LocalPlayer.Character) end
        if ignoreCharacter then table.insert(exclusions, ignoreCharacter) end
        params.FilterDescendantsInstances = exclusions
        params.IgnoreWater = true
        for i = 1, amount do
            while #drops >= limit do remove(1) end
            local randomDirection = Vector3.new(math.random() * 2 - 1, math.random() * 1.4, math.random() * 2 - 1)
            local heading = direction * 0.8 + randomDirection
            if heading.Magnitude < 0.01 then heading = Vector3.new(0, 1, 0) end
            local velocity = heading.Unit * speed * (0.55 + math.random() * 0.6)
            local part = Instance.new("Part")
            part.Name, part.Size = "LiquidDroplet", Vector3.one
            part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery = true, false, false, false
            part.CastShadow, part.Material, part.Reflectance = false, Enum.Material.SmoothPlastic, 0.18
            part.Color, part.Transparency = Cfg.ParticleColor, 0.07
            part.CFrame = CFrame.lookAt(position, position + velocity)
            local mesh = Instance.new("SpecialMesh")
            mesh.MeshType = Enum.MeshType.Sphere
            mesh.Scale = Vector3.new(0.1, 0.1, 0.2)
            mesh.Parent, part.Parent = part, folder
            local weight = (i % 3 == 0 and 0.55 or 1) * (0.75 + math.random() * 0.5)
            table.insert(drops, {Part = part, Mesh = mesh, Position = position, Previous = position, Velocity = velocity,
                UserId = userId, Age = 0, Lifetime = 0.85 + math.random() * 0.5, Weight = weight, Params = params})
        end
    end
    function Session:UpdateHitSplashes(dt)
        if not self.Alive or not Cfg.DamageParticlesEnabled then self:ClearHitSplashes(); return end
        if #drops == 0 then accumulator = 0; return end
        while Cfg.LowEndMode and #drops > 64 do remove(#drops) end
        local step = Cfg.LowEndMode and 1/30 or STEP
        local delta = number(dt, 0, 0, 0.1)
        local thickness = number(Cfg.ParticleThickness, 0.13, 0.025, 0.6)
        local size = number(Cfg.ParticleSize, 4, 0.1, 20)
        local gravity = Vector3.new(0, -number(workspace.Gravity, 196.2, 0, 1000) * 0.32, 0)
        accumulator += delta
        local drag = math.exp(-0.65 * step)
        while accumulator + 1e-9 >= step do
            accumulator = math.max(0, accumulator - step)
            for i = #drops, 1, -1 do
                local drop = drops[i]
                drop.Age += step
                drop.Previous = drop.Position
                if not drop.Part.Parent or drop.Age >= drop.Lifetime then remove(i)
                elseif not drop.ImpactAge then
                    local displacement = drop.Velocity * step + gravity * (step * step * 0.5)
                    local hit = workspace:Raycast(drop.Position, displacement, drop.Params)
                    drop.Velocity = (drop.Velocity + gravity * step) * drag
                    if hit then
                        drop.Position = hit.Position + hit.Normal * 0.015
                        drop.Normal, drop.ImpactAge = hit.Normal, drop.Age
                        drop.Lifetime = math.min(drop.Lifetime, drop.Age + 0.65)
                        drop.Previous = drop.Position
                    else drop.Position += displacement end
                end
            end
        end
        for _, drop in ipairs(drops) do
            local diameter = thickness * drop.Weight * math.sqrt(size / 4)
            local fade = math.clamp((drop.Lifetime - drop.Age) / 0.28, 0, 1)
            fade = fade * fade * (3 - 2 * fade)
            local shrink = 0.35 + fade * 0.65
            if drop.Part.Color ~= Cfg.ParticleColor then drop.Part.Color = Cfg.ParticleColor end
            local opacity = 1 - fade * 0.93
            if drop.Part.Transparency ~= opacity then drop.Part.Transparency = opacity end
            if drop.ImpactAge then
                local spread = 1 + math.clamp((drop.Age - drop.ImpactAge) / 0.18, 0, 1) * 2.5
                drop.Mesh.Scale = Vector3.new(diameter * spread, diameter * spread, math.max(0.015, diameter * 0.15)) * shrink
                if not drop.ImpactDrawn then
                    drop.ImpactDrawn = true
                    drop.Part.CFrame = CFrame.lookAt(drop.Position, drop.Position + drop.Normal)
                end
            else
                local length = math.max(diameter, diameter + size * 0.085 * math.clamp(drop.Velocity.Magnitude / 16, 0, 2.5))
                drop.Mesh.Scale = Vector3.new(diameter, diameter, length) * shrink
                local point = drop.Previous:Lerp(drop.Position, math.clamp(accumulator / step, 0, 1))
                local direction = drop.Velocity.Magnitude > 0.001 and drop.Velocity.Unit or Vector3.new(0, -1, 0)
                drop.Part.CFrame = CFrame.lookAt(point, point + direction)
            end
        end
    end
end

-- Asset-free jump rings: surface-aligned, bounded and owned by this session.
do
    local SEGMENTS = 48
    local MAX_RINGS = 8
    local LIFETIME = 0.8
    local STEP = math.pi * 2 / SEGMENTS
    local UP = Vector3.new(0, 1, 0)
    local segmentDirections = {}
    Session.JumpCircles = {}

    for index = 1, SEGMENTS do
        local angle = (index - 1) * STEP
        segmentDirections[index] = {
            Offset = Vector3.new(math.cos(angle), 0, math.sin(angle)),
            Rotation = CFrame.Angles(0, -angle - math.pi / 2, 0),
        }
    end

    local function removeRing(index)
        local ring = table.remove(Session.JumpCircles, index)
        if ring then ring.Folder:Destroy() end
    end

    function Session:ClearJumpCircles()
        for index = #self.JumpCircles, 1, -1 do removeRing(index) end
    end

    local function drawRing(ring, progress)
        local eased = 1 - (1 - progress) ^ 4
        local radius = ring.StartRadius + (ring.EndRadius - ring.StartRadius) * eased
        -- Read the setting each frame so existing rings respond immediately.
        -- Limiting the band to its radius keeps a visible hole at small sizes.
        local width = math.min(radius, math.clamp(tonumber(Cfg.JumpCircleThickness) or 0.15, 0.025, 0.6))
        ring.Width = width
        -- Tangent intersections keep even the thinnest large rings connected.
        local length = math.max(0.025, 2 * radius * math.tan(STEP * ring.Stride / 2) + width * 0.2)
        local frame = ring.Frame
        if ring.Support then
            if not ring.Support.Parent then return false end
            frame = ring.Support.CFrame * ring.LocalFrame
        end
        local transparency = 0.12 + 0.88 * progress * progress
        for index, part in ipairs(ring.Parts) do
            if not part.Parent then return false end
            local direction = segmentDirections[1 + (index - 1) * ring.Stride]
            part.Size = Vector3.new(length, 0.045, width)
            part.CFrame = frame * CFrame.new(direction.Offset * radius) * direction.Rotation
            part.Transparency = transparency
        end
        return true
    end

    local function CreateJumpCircle(character, humanoid)
        if not Session.Alive or not Cfg.JumpVisualCirclesEnabled then return false end
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not root or not root:IsA("BasePart") or not humanoid or humanoid.Health <= 0 then return false end

        -- HipHeight excludes the R6 leg. The ray also handles scaled R15 rigs
        -- and airborne jumps, without assuming a fixed 2.9-stud root offset.
        local footDistance = root.Size.Y * 0.5 + math.max(0, tonumber(humanoid.HipHeight) or 0)
        if humanoid.RigType == Enum.HumanoidRigType.R6 then
            local leg = character:FindFirstChild("Left Leg") or character:FindFirstChild("Right Leg")
            if leg and leg:IsA("BasePart") then footDistance += leg.Size.Y end
        end
        local excluded = {Session.Effects, character}
        for _, player in ipairs(Players:GetPlayers()) do
            if player.Character and player.Character ~= character then table.insert(excluded, player.Character) end
        end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = excluded
        params.IgnoreWater = true
        params.RespectCanCollide = true
        local hit = workspace:Raycast(root.Position + UP * 0.5, -UP * math.max(64, footDistance + 8), params)
        -- Do not manufacture a floating floor when jumping over the void.
        if not hit or hit.Normal.Magnitude < 0.001 then return false end

        local normal = hit.Normal.Unit
        local reference = math.abs(normal.Y) > 0.95 and Vector3.new(1, 0, 0) or UP
        local right = reference:Cross(normal).Unit
        local frame = CFrame.fromMatrix(hit.Position + normal * 0.055, right, normal, right:Cross(normal))
        local endRadius = math.clamp(tonumber(Cfg.JumpCircleMaximumSize) or 12, 1, 60) * 0.5
        local folder = Instance.new("Folder")
        folder.Name = "JumpCircle"
        local ring = {
            Folder = folder,
            Parts = {},
            Frame = frame,
            Birth = tick(),
            StartRadius = math.max(0.08, math.min(endRadius * 0.32, math.max(root.Size.X, root.Size.Z) * 0.3)),
            EndRadius = endRadius,
            Stride = Cfg.LowEndMode and 2 or 1,
        }
        if hit.Instance and hit.Instance:IsA("BasePart") and not hit.Instance:IsA("Terrain") then
            ring.Support = hit.Instance
            ring.LocalFrame = hit.Instance.CFrame:Inverse() * frame
        end
        for index = 1, SEGMENTS / ring.Stride do
            local part = Instance.new("Part")
            part.Name = "Arc" .. index
            part.Size = Vector3.new(0.05, 0.045, 0.025)
            part.Anchored = true
            part.CanCollide = false
            part.CanTouch = false
            part.CanQuery = false
            part.CastShadow = false
            part.Material = Enum.Material.Neon
            part.Color = Cfg.JumpCircleEffectColor
            part.TopSurface = Enum.SurfaceType.Smooth
            part.BottomSurface = Enum.SurfaceType.Smooth
            part.Parent = folder
            ring.Parts[index] = part
        end
        if not drawRing(ring, 0) then folder:Destroy(); return false end
        while #Session.JumpCircles >= MAX_RINGS do removeRing(1) end
        folder.Parent = Session.Effects
        table.insert(Session.JumpCircles, ring)
        return true
    end

    function Session:OnCharacterJump(character, humanoid, active)
        if not self.Alive or character ~= LocalPlayer.Character or humanoid.Parent ~= character then return false end
        if not active then
            if self.JumpHumanoid == humanoid then self.JumpStateActive = false end
            return false
        end
        if humanoid.Health <= 0 or (self.JumpHumanoid == humanoid and self.JumpStateActive) then return false end
        self.JumpHumanoid = humanoid
        self.JumpStateActive = true
        lastRealJumpTime = tick()
        return CreateJumpCircle(character, humanoid)
    end

    function Session:RequestInfiniteJump(character, humanoid)
        if not self.Alive or not Cfg.InfJumpEnabled or character ~= LocalPlayer.Character then return false end
        if not humanoid or humanoid.Parent ~= character or humanoid.Health <= 0 then return false end
        -- JumpRequest can repeat while held. Only a genuine state transition
        -- creates an impulse and lets Humanoid.Jumping emit the single ring.
        if humanoid:GetState() == Enum.HumanoidStateType.Jumping then return false end
        humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        return true
    end

    Session:Connect(RunService.Heartbeat, function()
        if not Cfg.JumpVisualCirclesEnabled then
            if #Session.JumpCircles > 0 then Session:ClearJumpCircles() end
            return
        end
        local now = tick()
        for index = #Session.JumpCircles, 1, -1 do
            local ring = Session.JumpCircles[index]
            local progress = math.clamp((now - ring.Birth) / LIFETIME, 0, 1)
            if progress >= 1 or not ring.Folder.Parent or not drawRing(ring, progress) then removeRing(index) end
        end
    end)
end

