-- Platform: Roblox client / Luau; target: head-anchored Target HUD placement.
do
    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end
    local function validPoint(point)
        return point and finite(point.X) and finite(point.Y) and finite(point.Z) and point.Z > 0.05
    end
    function Session:UpdateHudPlacement(character)
        local following = Cfg.TargetHudInPlayer == true
        TargetHUD.Active = not following
        if following then
            -- Tracking never writes the independent draggable screen position.
            Hud.DragInput, Hud.DragStart, Hud.DragOrigin = nil, nil, nil
            Hud.Following = true
        elseif Hud.Following then
            Hud.Following = false
            TargetHUD.Position = Cfg.TargetHudPosition
        end
        if not following then self:ClampHudPosition(false); return true end
        local camera = workspace.CurrentCamera
        local head = character and character:FindFirstChild("Head")
        if not camera or not head or not head:IsA("BasePart") then return false end
        local viewport = camera.ViewportSize
        if not finite(viewport.X) or not finite(viewport.Y) or viewport.X < 1 or viewport.Y < 1 then return false end
        local center, onScreen = Session:ProjectToViewport(camera, head.Position)
        if not onScreen or not validPoint(center) or center.X < 0 or center.X > viewport.X
            or center.Y < 0 or center.Y > viewport.Y then return false end
        -- The pixel gap starts at the projected edge of the head, not its center.
        -- Hitbox may enlarge the invisible Head while its visible copy keeps the
        -- original dimensions. Position the HUD against the visible head.
        local original = Cfg.HitboxEnabled and OrigPartData[head]
        local headSize = original and original.Size or head.Size
        local radius = math.max(headSize.X, headSize.Z) * 0.5
        local edge = Session:ProjectToViewport(camera, head.Position + camera.CFrame.RightVector * radius)
        if not validPoint(edge) then return false end
        local halfWidth = math.abs(edge.X - center.X)
        local gap = Cfg.TargetHudHeadDistance
        gap = finite(gap) and math.clamp(gap, 0, 240) or 24
        local scale = Hud.Scale.Scale
        local width, height = TargetHUD.Size.X.Offset * scale, TargetHUD.Size.Y.Offset * scale
        local x = Cfg.TargetHudSide == 2 and (center.X - halfWidth - gap - width)
            or (center.X + halfWidth + gap)
        local maxX, maxY = math.max(4, viewport.X - width - 4), math.max(4, viewport.Y - height - 4)
        TargetHUD.Position = UDim2.fromOffset(math.clamp(x, 4, maxX), math.clamp(center.Y - height * 0.5, 4, maxY))
        return true
    end

    function Session:RefreshHudPlacement()
        local character = Hud.PlacementCharacter
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local placed = self:UpdateHudPlacement(character)
        TargetHUD.Visible = Cfg.TargetHudEnabled and humanoid ~= nil and humanoid.Health > 0 and placed
    end
end

local lastTargetUserId = nil; local lastTargetHealth = nil; local lastDamageTimeHUD = 0; local currentTween = nil; local lastTargetHudBarColor = nil

-- Platform: Roblox client / Luau; target: Notification Nova target-health damage numbers.
do
    local numbers = {}
    local observer = {Generation = 0, Connections = {}}
    local sequence = 0
    local MAX_NUMBERS = 24
    Session.DamageNumbers = numbers

    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end

    local function bounded(value, fallback, low, high)
        return finite(value) and math.clamp(value, low, high) or fallback
    end

    local function anchor(character)
        if not character then return nil end
        for _, name in ipairs({"Head", "HumanoidRootPart"}) do
            local part = character:FindFirstChild(name)
            if part and part:IsA("BasePart") then return part end
        end
        return nil
    end

    local function positionOf(part)
        return part and part.Parent and (part.Position + Vector3.new(0, 0.65, 0)) or nil
    end

    local function damageColor()
        if Cfg.DamageNumbersSyncColor ~= false then
            return Cfg.TargetHudDamageColor or Color3.fromRGB(255, 75, 105)
        end
        return Cfg.DamageNumbersColor or Color3.fromRGB(255, 75, 105)
    end

    local function dispose(index)
        local entry = table.remove(numbers, index)
        if not entry then return end
        -- Short-lived labels leave registries immediately instead of waiting for Nova's sweep.
        Nova.U.textReg[entry.Label] = nil
        Nova.Theme.registry[entry.Label] = nil
        entry.Label:Destroy()
    end

    local function resetObserver()
        observer.Generation += 1
        for _, connection in ipairs(observer.Connections) do connection:Disconnect() end
        table.clear(observer.Connections)
        observer.Player, observer.Character, observer.Humanoid = nil, nil, nil
        observer.PreviousHealth, observer.LastPosition = nil, nil
    end

    function Session:ClearDamageNumbers(reset)
        for i = #numbers, 1, -1 do dispose(i) end
        if reset then resetObserver() end
    end
    function Session:ClearFriendlyDamageNumbers()
        for i = #numbers, 1, -1 do
            if self:IsFriend(numbers[i].UserId) then dispose(i) end
        end
        if self:IsFriend(observer.Player) then resetObserver() end
    end

    local function showDamage(amount, character)
        if not Session.Alive or not Cfg.DamageNumbersEnabled or not finite(amount) or amount <= 0 then return end
        local userId = Session:CharacterUserId(character)
        if Session:IsFriend(userId) then return end
        local part = anchor(character)
        local point = positionOf(part) or observer.LastPosition
        if not point then return end
        if #numbers >= MAX_NUMBERS then dispose(1) end
        sequence += 1
        local size = bounded(Cfg.DamageNumbersSize, 20, 12, 48)
        local nearest = math.floor(amount + 0.5)
        local value
        if amount >= 1 and math.abs(amount - nearest) < 0.001 then
            value = string.format("%.0f", nearest)
        elseif amount >= 0.1 then
            value = string.format("%.1f", amount)
        else
            value = string.format("%.2g", amount)
        end
        local label = Nova.U.new("TextLabel", {
            Name = "DamageNumber", Text = "-" .. value, AnchorPoint = Vector2.new(0.5, 0.5),
            Size = UDim2.fromOffset(math.max(96, (#value + 1) * size * 0.8 + 16), size * 2 + 12),
            BackgroundTransparency = 1, BorderSizePixel = 0, FontFace = Nova.Font.Bold(),
            TextSize = size, TextColor3 = damageColor(), TextTransparency = 1,
            TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Center,
            Visible = false, ZIndex = 18, Parent = NotificationGui,
        })
        local scale = Nova.U.new("UIScale", {Name = "DamageScale", Parent = label})
        table.insert(numbers, {
            Label = label, Scale = scale, Part = part, Position = point, Age = 0, UserId = userId,
            Lifetime = bounded(Cfg.DamageNumbersLifetime, 1.1, 0.35, 3),
            Rise = bounded(Cfg.DamageNumbersRise, 56, 0, 160),
            Lane = ((sequence - 1) % 3 - 1) * 12,
        })
    end

    function Session:ObserveDamageTarget(player)
        if self:IsFriend(player) then player = nil end
        if not self.Alive or not Cfg.DamageNumbersEnabled then
            if observer.Humanoid or #numbers > 0 then self:ClearDamageNumbers(true) end
            return
        end
        local character = player and player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if observer.Player == player and observer.Character == character and observer.Humanoid == humanoid then
            observer.LastPosition = positionOf(anchor(character)) or observer.LastPosition
            return
        end
        resetObserver()
        if not humanoid then return end
        observer.Player, observer.Character, observer.Humanoid = player, character, humanoid
        observer.LastPosition = positionOf(anchor(character))
        -- Acquiring/reacquiring a target establishes a baseline, never an apparent hit.
        observer.PreviousHealth = finite(humanoid.Health) and math.max(0, humanoid.Health) or nil
        local generation = observer.Generation
        self:Connect(humanoid.HealthChanged, function(nextHealth)
            if observer.Generation ~= generation or observer.Humanoid ~= humanoid then return end
            if not finite(nextHealth) then observer.PreviousHealth = nil; return end
            local health = math.max(0, nextHealth)
            local previous = observer.PreviousHealth
            observer.PreviousHealth = health
            observer.LastPosition = positionOf(anchor(character)) or observer.LastPosition
            if Cfg.DamageNumbersEnabled and previous and health < previous then
                -- A lethal change reaches this handler before target acquisition drops the dead player.
                showDamage(previous - health, character)
            end
        end, observer.Connections)
    end

    local function smooth(value)
        value = math.clamp(value, 0, 1)
        return value * value * (3 - 2 * value)
    end

    function Session:UpdateDamageNumbers(dt)
        if not self.Alive or not Cfg.DamageNumbersEnabled then
            if observer.Humanoid or #numbers > 0 then self:ClearDamageNumbers(true) end
            return
        end
        if #numbers == 0 then return end
        local camera = workspace.CurrentCamera
        local motion = Nova.Motion.enabled
        local uiScale = window.Scale and window.Scale.Scale or window.OverlayScale or 1
        local color = damageColor()
        local delta = finite(dt) and math.max(dt, 0) or 0
        for i = #numbers, 1, -1 do
            local entry = numbers[i]
            entry.Age += delta
            if entry.Age >= entry.Lifetime or not entry.Label.Parent then
                dispose(i)
            else
                entry.Position = positionOf(entry.Part) or entry.Position
                local label = entry.Label
                local age, lifetime = entry.Age, entry.Lifetime
                local progress = age / lifetime
                local fadeIn = math.min(0.12, lifetime * 0.2)
                local fadeOut = math.min(0.42, lifetime * 0.4)
                local opacity = smooth(age / fadeIn) * smooth((lifetime - age) / fadeOut)
                label.TextTransparency = 1 - opacity
                label.TextStrokeTransparency = 1 - opacity * 0.55
                if label.TextColor3 ~= color then label.TextColor3 = color end
                -- Reduced motion keeps the requested short fade but removes travel and the size pop.
                local pop = 1
                local rise, side = 0, 0
                if motion then
                    if age < fadeIn then
                        pop = 0.72 + 0.46 * smooth(age / fadeIn)
                    else
                        pop = 1.18 - 0.18 * smooth((age - fadeIn) / 0.16)
                    end
                    rise = entry.Rise * (1 - (1 - progress) ^ 2)
                    side = entry.Lane * smooth(age / fadeIn)
                end
                local nextScale = uiScale * pop
                if entry.Scale.Scale ~= nextScale then entry.Scale.Scale = nextScale end
                if camera then
                    local screen, onScreen = Session:ProjectToViewport(camera, entry.Position)
                    label.Visible = onScreen and screen.Z > 0
                    if label.Visible then label.Position = UDim2.fromOffset(screen.X + side, screen.Y - rise) end
                else
                    label.Visible = false
                end
            end
        end
    end
end

local ESPMain = Instance.new("Frame", NotificationGui)
ESPMain.Name = "Notification_TargetESP"
ESPMain.BackgroundTransparency = 1
ESPMain.AnchorPoint = Vector2.new(0.5,0.5)
ESPMain.Visible = false
ESPMain.BorderSizePixel = 0

local function targetImage(name, scale, transparency, z)
    local layer = Instance.new("ImageLabel", ESPMain)
    layer.Name = name
    layer.BackgroundTransparency = 1
    layer.AnchorPoint = Vector2.new(0.5,0.5)
    layer.Position = UDim2.fromScale(0.5,0.5)
    layer.Size = UDim2.fromScale(scale,scale)
    layer.ImageTransparency = transparency
    layer.ImageRectOffset = Vector2.new(0,0)
    layer.ImageRectSize = Vector2.new(0,0)
    layer.ScaleType = Enum.ScaleType.Fit
    layer.ZIndex = z
    layer.Image = ""
    return layer
end
-- Both layers use the exact original PNG; no generated corners or substitute symbols.
local targetEspGlow = targetImage("Glow",1.055,0.82,4)
local targetEspTexture = targetImage("Texture",1,0,6)

local function targetEspFinite(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end

function Session:UpdateTargetEspLayout(point, onScreen, viewport, verticalFov)
    -- Size describes a world-space marker: the reference is 20 studs at 720p/70 degrees.
    -- A fixed pixel size incorrectly grows relative to a player as they move away.
    if not onScreen or not point or not viewport
        or not targetEspFinite(point.X) or not targetEspFinite(point.Y)
        or not targetEspFinite(point.Z) or point.Z <= 0.05
        or not targetEspFinite(viewport.X) or not targetEspFinite(viewport.Y)
        or viewport.X < 1 or viewport.Y < 1 then
        ESPMain.Visible = false
        return false
    end
    local fov = tonumber(verticalFov)
    local configuredSize = tonumber(Cfg.TargetESPSquareSize)
    if not targetEspFinite(fov) or fov <= 0 or fov >= 180
        or not targetEspFinite(configuredSize) or configuredSize <= 0 then
        ESPMain.Visible = false
        return false
    end
    local size = configuredSize * (20 / point.Z) * (viewport.Y / 720)
        * (math.tan(math.rad(35)) / math.tan(math.rad(fov * 0.5)))
    if not targetEspFinite(size) or size < 0.75 then
        ESPMain.Visible = false
        return false
    end
    -- Keep near-plane crossings from creating enormous GUI allocations.
    size = math.min(size, math.max(viewport.X, viewport.Y) * 2)
    ESPMain.Position = UDim2.fromOffset(point.X, point.Y)
    ESPMain.Size = UDim2.fromOffset(size, size)
    ESPMain.Visible = true
    return true
end

function Session:EnsureTargetEspTexture()
    if not self.Alive or self.TargetEspTextureRequested then return end
    self.TargetEspTextureRequested = true
    task.defer(function()
    if not Session.Alive then return end
    Startup:Mark("target-png.begin")
    local id = TargetEspAsset.Get()
    Startup:Mark(id and "target-png.ready" or "target-png.unavailable")
    if not Session.Alive then return end
    if not id then Session.TargetEspTextureError = TargetEspAsset.Error; return end
    targetEspTexture.Image, targetEspGlow.Image = id, id
    task.spawn(function()
        pcall(function() game:GetService("ContentProvider"):PreloadAsync({targetEspTexture,targetEspGlow}) end)
    end)
    local deadline = tick() + 8
    while Session.Alive and not targetEspTexture.IsLoaded and tick() < deadline do task.wait(0.05) end
    if Session.Alive and not targetEspTexture.IsLoaded then
        -- Keep the URI assigned: a slow load is allowed to finish after this deadline.
        Session.TargetEspTextureError = "The supplied Target ESP PNG is still loading or could not be decoded."
    end
    end)
end
function Session:UpdateTargetEspTexture(color)
    self:EnsureTargetEspTexture()
    targetEspTexture.ImageColor3, targetEspGlow.ImageColor3 = color, color
    targetEspGlow.ImageTransparency = 1-math.clamp(Cfg.TargetESPGlow,0,1)*0.3
    if targetEspTexture.IsLoaded then
        self.TargetEspTextureError = nil
    elseif self.TargetEspTextureError and not self.TargetEspTextureNotified then
        self.TargetEspTextureNotified = true
        window:Notify({Title="Target ESP",Text=self.TargetEspTextureError,Kind="warning"})
    end
end

-- Platform: Roblox client / Luau; target: serialized aura input attempts, not server-confirmed hits.
do
    local state = {Pending=nil, Unreleased=nil, NextAttack=0, RetryAt=0, ReleaseAt=0, Dispatching=false, Cancel=false, Stopped=false,
        SuccessfulDispatches=0, FailedDispatches=0, LastBackend=nil, LastError=nil}
    Session.AuraAttackState = state
    local releaseName = Session.RenderName .. "_AuraInputRelease"
    local HOLD_TIME, RETRY_TIME, RELEASE_GAP = 0.025, 0.08, 0.01
    local function finite(n) return type(n) == "number" and n == n and math.abs(n) < math.huge end
    local function safeCall(callback)
        local ok, result = pcall(callback)
        return ok and result ~= false, if ok then nil else tostring(result), ok and result == false
    end
    local function active()
        return not state.Stopped and Session.Alive and Session.Ready and Cfg.KillAuraEnabled == true
    end
    local function uiClear()
        local ok, clear = pcall(function()
            return not window.IsOpen and not window.Listening and not window.KbCap
                and not UserInputService:GetFocusedTextBox() and not window:PointerOverUI()
        end)
        return ok and clear
    end
    local function targetInfo(player)
        if not active() or not uiClear() or player ~= Session.KaTarget or typeof(player) ~= "Instance"
            or not player:IsA("Player") or player.Parent ~= Players or player == LocalPlayer or Session:IsFriend(player) then return nil end
        local character, localCharacter = player.Character, LocalPlayer.Character
        local root = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
        local humanoid = localCharacter and localCharacter:FindFirstChildOfClass("Humanoid")
        local part = character and character:FindFirstChild("HumanoidRootPart")
        local targetHumanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not localCharacter or not localCharacter.Parent or not character or not character.Parent
            or not root or not root:IsA("BasePart") or not part or not part:IsA("BasePart")
            or not humanoid or humanoid.Health <= 0 or not targetHumanoid or targetHumanoid.Health <= 0 then return nil end
        local range, clickRange = tonumber(Cfg.KillAuraRange), tonumber(Cfg.KillAuraClickRange)
        if not finite(range) or not finite(clickRange) then return nil end
        local distance = (part.Position - root.Position).Magnitude
        if not finite(distance) or distance > math.min(range, clickRange) then return nil end
        return part, localCharacter
    end
    local function releaseOwned()
        RunService:UnbindFromRenderStep(releaseName)
        local pending = state.Pending or state.Unreleased
        state.Pending, state.Unreleased = nil, nil
        if not pending then return true end
        -- Clear ownership first so a synchronous input callback cannot release twice.
        local ok, err = safeCall(pending.Release)
        if not ok and pending.ReleaseFallback then ok, err = safeCall(pending.ReleaseFallback) end
        if not ok then
            state.Unreleased = pending
            state.LastError = "Input release failed: " .. tostring(err or pending.Backend)
        end
        state.ReleaseAt = tick() + RELEASE_GAP
        return ok
    end
    local function releaseStep()
        local pending = state.Pending
        if not pending then RunService:UnbindFromRenderStep(releaseName); return end
        if not active() or not uiClear() or not targetInfo(pending.Target) or tick() >= pending.ReleaseAt then releaseOwned() end
    end
    local function vimEvents()
        local available, method = pcall(function() return VirtualInputManager.SendMouseButtonEvent end)
        if not available or type(method) ~= "function" then return nil end
        local camera = workspace.CurrentCamera
        if not camera then return nil end
        local viewport = camera.ViewportSize
        if not viewport or not finite(viewport.X) or not finite(viewport.Y) or viewport.X <= 0 or viewport.Y <= 0 then return nil end
        local x, y = math.floor(viewport.X / 2), math.floor(viewport.Y / 2)
        local function send(down) return VirtualInputManager:SendMouseButtonEvent(x, y, 0, down, game, 1) end
        return function() return send(true) end, function() return send(false) end
    end
    local function dispatch(backend, press, release, fallbackRelease, target)
        -- The press APIs can synchronously fire input callbacks: keep cancellation explicit.
        state.Dispatching, state.Cancel = true, false
        local ok, err, rejected = safeCall(press)
        state.Dispatching = false
        if not ok then
            -- Explicit rejection means no press was owned (e.g. Studio has no equipped Tool).
            if rejected then state.LastError = backend .. " rejected input"; return false, not state.Cancel end
            -- A throwing backend may have partially pressed before reporting its error.
            local released = safeCall(release)
            if not released and fallbackRelease then released = safeCall(fallbackRelease) end
            if not released then
                state.Unreleased = {Backend=backend, Release=release, ReleaseFallback=fallbackRelease, Target=target}
            end
            state.LastError = err or (backend .. " rejected input")
            return false, released and not state.Cancel
        end
        state.Pending = {Backend=backend, Release=release, ReleaseFallback=fallbackRelease,
            Target=target, ReleaseAt=tick() + HOLD_TIME}
        if state.Cancel or not active() or not targetInfo(target) then
            releaseOwned()
            return true, false
        end
        RunService:BindToRenderStep(releaseName, 2002, releaseStep)
        return true, false
    end
    function Session:TryAuraAttack(target)
        local now = tick()
        if state.Dispatching or state.Pending or state.Unreleased or now < state.NextAttack or now < state.RetryAt or now < state.ReleaseAt then return false end
        local part, character = targetInfo(target)
        if not part then return false end
        local pressVim, releaseVim = vimEvents()
        local succeeded, mayFallback = false, true
        local touchOnly = UserInputService.TouchEnabled == true and UserInputService.MouseEnabled ~= true
            and UserInputService.KeyboardEnabled ~= true
        if touchOnly then
            local tool = character:FindFirstChildOfClass("Tool")
            if tool and tool.Enabled ~= false then
                succeeded, mayFallback = dispatch("Tool", function() return tool:Activate() end,
                    function() return tool:Deactivate() end, nil, target)
            end
        end
        if not succeeded and mayFallback and targetInfo(target) and type(mouse1press) == "function" and type(mouse1release) == "function" then
            local press, release = mouse1press, mouse1release
            succeeded, mayFallback = dispatch("Mouse", press, release, releaseVim, target)
        end
        if not succeeded and mayFallback and targetInfo(target) and pressVim then
            succeeded = dispatch("VirtualInput", pressVim, releaseVim, nil, target)
        end
        if not succeeded then
            state.FailedDispatches += 1
            state.RetryAt = tick() + RETRY_TIME
            return false
        end
        -- A dispatched input is not proof that the game accepted an attack or damage.
        state.SuccessfulDispatches += 1
        state.LastBackend = state.Pending and state.Pending.Backend or "Cancelled"
        state.LastError, state.RetryAt = nil, 0
        local speed = tonumber(Cfg.KillAuraSpeed)
        if not finite(speed) then speed = 1 end
        state.NextAttack = tick() + math.clamp(speed, 0.5, 50) / 10
        if active() and targetInfo(target) == part and target.Character == part.Parent then
            self:RecordFeedbackAttack(part.Parent, part.Position, nil, "aura")
        end
        return true
    end
    function Session:ResetAuraAttack()
        if state.Dispatching then state.Cancel = true end
        releaseOwned()
        state.NextAttack, state.RetryAt = 0, 0
    end
    function Session:DestroyAuraAttack()
        if state.Stopped then return end
        self:ResetAuraAttack()
        state.Stopped = true
    end
end

local lastStrafeJumpTime = 0; local nextStrafeJumpDelay = math.random(1, 8) / 10; local currentKaStrafeDir = 1; local nextKaStrafeDirChange = 0
local lastEspTargetUserId = nil; local lastEspTargetHealth = nil; local lastDamageTimeESP = 0
local AnimLagAccumulator = 0; local WasAnimLagging = false

table.insert(Connections, RunService.Stepped:Connect(function(time, dt)
    local char = LocalPlayer.Character
    if not char then return end

    if Cfg.NoClipEnabled then
        for _, part in ipairs(Session:GetCharacterParts(char)) do if part.Parent then if OrigNoClipStates[part] == nil then OrigNoClipStates[part] = part.CanCollide end; part.CanCollide = false end end
    elseif not Cfg.NoClipEnabled and next(OrigNoClipStates) ~= nil then
        for part, state in pairs(OrigNoClipStates) do if part and part.Parent then part.CanCollide = state end end; table.clear(OrigNoClipStates)
    end

    if Cfg.AntiFlingEnabled then
        for plr, parts in pairs(AntiFlingCache) do
            if not Session:IsFriend(plr) and plr.Character and parts[1] and parts[1].Parent then
                for i = 1, #parts do
                    local part = parts[i]
                    if part.Parent then
                        if Session.AntiFlingParts[part] == nil then Session.AntiFlingParts[part] = if OrigPartData[part] then OrigPartData[part].CanCollide else part.CanCollide end
                        part.CanCollide = false
                    end
                end
            end
        end
    end
    
    if Cfg.AnimLagEnabled then
        local hum = char:FindFirstChild("Humanoid")
        if hum then
            local animator = hum:FindFirstChild("Animator")
            if animator then
                AnimLagAccumulator = AnimLagAccumulator + dt
                local interval = 1 / math.clamp(tonumber(Cfg.AnimLagFPS) or 5, 1, 60)
                local doUpdate = AnimLagAccumulator >= interval
                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do if Session.AnimationSpeeds[track] == nil then Session.AnimationSpeeds[track] = track.Speed end; track:AdjustSpeed(0); if doUpdate and track.Length > 0 then local pos = track.TimePosition + AnimLagAccumulator * Session.AnimationSpeeds[track]; track.TimePosition = track.Looped and (pos % track.Length) or math.min(pos, track.Length) end end
                if doUpdate then AnimLagAccumulator = 0 end
                WasAnimLagging = true
            end
        end
    elseif WasAnimLagging then
        Session:RestoreAnimations()
        WasAnimLagging = false; AnimLagAccumulator = 0
    end
end))

task.spawn(function()
    while Session.Alive do
