                                if not OrigPartData[head] then OrigPartData[head] = {Size = head.Size, Trans = head.Transparency, CanCollide = if Session.AntiFlingParts[head] ~= nil then Session.AntiFlingParts[head] else head.CanCollide, Massless = head.Massless} end
                                
                                if isHitboxActive then
                                    local targetSize = OrigPartData[head].Size * mult
                                    if head.Size ~= targetSize then
                                        head.Size = targetSize; head.Transparency = 1; head.CanCollide = false; head.Massless = true
                                        local face = head:FindFirstChildOfClass("Decal"); if face then if not OrigPartData[face] then OrigPartData[face] = {Trans = face.Transparency} end; face.Transparency = 1 end
                                        
                                        if not plChar:FindFirstChild("Notification_FakeHead") then
                                            local archivable = head.Archivable; head.Archivable = true; local fakeHead = head:Clone(); head.Archivable = archivable; fakeHead.Name = "Notification_FakeHead"; fakeHead.CanQuery = false; fakeHead.CanTouch = false
                                            for _, v in ipairs(fakeHead:GetChildren()) do if v:IsA("Attachment") or v:IsA("Weld") or v:IsA("WeldConstraint") or v:IsA("Motor6D") or v:IsA("Script") or v:IsA("LocalScript") then v:Destroy() end end
                                            fakeHead.Size = OrigPartData[head].Size; fakeHead.Transparency = OrigPartData[head].Trans; fakeHead.CanCollide = false; fakeHead.Massless = true
                                            local fakeFace = fakeHead:FindFirstChildOfClass("Decal"); if fakeFace and OrigPartData[face] then fakeFace.Transparency = OrigPartData[face].Trans end
                                            local w = Instance.new("WeldConstraint"); w.Part0 = head; w.Part1 = fakeHead; w.Parent = fakeHead; fakeHead.Parent = plChar
                                        end
