                                        head.Size = OrigPartData[head].Size; head.Transparency = OrigPartData[head].Trans; head.CanCollide = OrigPartData[head].CanCollide; head.Massless = OrigPartData[head].Massless
                                        local face = head:FindFirstChildOfClass("Decal"); if face and OrigPartData[face] then face.Transparency = OrigPartData[face].Trans end
                                        local fakeH = plChar:FindFirstChild("Notification_FakeHead"); if fakeH then fakeH:Destroy() end
                                    end
                                end
                            end
                        end
                    end
                end
            else
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LocalPlayer and player.Character then
                        local head = player.Character:FindFirstChild("Head")
                        if head and OrigPartData[head] and head.Size ~= OrigPartData[head].Size then
                            head.Size = OrigPartData[head].Size; head.Transparency = OrigPartData[head].Trans; head.CanCollide = OrigPartData[head].CanCollide; head.Massless = OrigPartData[head].Massless
                            local face = head:FindFirstChildOfClass("Decal"); if face and OrigPartData[face] then face.Transparency = OrigPartData[face].Trans end
                            local fakeH = player.Character:FindFirstChild("Notification_FakeHead"); if fakeH then fakeH:Destroy() end
                        end
                    end
                end
            end
        end)
    end
end)

local GhostModel = nil
local GhostPartsArray = {}
local GhostHistory = {}
local lastGhostColor = nil
local lastGhostTrans = nil
local lastGhostDelTex = nil
local currentGhostCharRef = nil

local function UpdateGhostAppearance()
    if not GhostModel then return end
    local trans = (tonumber(Cfg.ClientSideTransparency) or 50) / 100
    local delTex = Cfg.ClientSideDelTexture
    local gColor = Cfg.ClientSideColor
    local bc = GhostModel:FindFirstChildOfClass("BodyColors"); if bc then bc:Destroy() end
    for i = 1, #GhostPartsArray do
        local p = GhostPartsArray[i].ghost
        if p and p:IsA("BasePart") then
            if p.Transparency ~= trans then p.Transparency = trans end
            if p.Color ~= gColor then p.Color = gColor end
            if delTex then p.Material = Enum.Material.SmoothPlastic; if p:IsA("MeshPart") then p.TextureID = "" end end
        end
    end
end

table.insert(Connections, RunService.Heartbeat:Connect(function(dt)
    local Camera = workspace.CurrentCamera; if not Camera then return end
    local char = LocalPlayer.Character
    local camPos = Camera.CFrame.Position
    
    if Cfg.ClientSideEnabled and char then
        if currentGhostCharRef ~= char or (lastGhostDelTex ~= nil and lastGhostDelTex ~= Cfg.ClientSideDelTexture) then
            if GhostModel then GhostModel:Destroy() end; GhostModel = nil; GhostPartsArray = {}; GhostHistory = {}; currentGhostCharRef = char; lastGhostDelTex = Cfg.ClientSideDelTexture
        end
        if not GhostModel or GhostModel.Parent ~= Chams3DFolder then
            GhostModel = Session:BuildCosmeticGhost(char)
            GhostPartsArray = {}
            if not GhostModel then return end
            -- All scripts, joints and physics controllers were removed while detached.
            GhostModel.Parent = Chams3DFolder
            for _, realPart in ipairs(char:GetDescendants()) do
                if realPart:IsA("BasePart") and realPart.Name ~= "HumanoidRootPart" then
                    local ghostPart = nil
                    if realPart.Parent == char then ghostPart = GhostModel:FindFirstChild(realPart.Name)
                    elseif realPart.Parent:IsA("Accessory") then local acc = GhostModel:FindFirstChild(realPart.Parent.Name); if acc then ghostPart = acc:FindFirstChild(realPart.Name) end end
                    if ghostPart and ghostPart:IsA("BasePart") then table.insert(GhostPartsArray, {real = realPart, ghost = ghostPart}) end
                end
            end
            lastGhostColor = Cfg.ClientSideColor; lastGhostTrans = Cfg.ClientSideTransparency; UpdateGhostAppearance()
        end
        local currentTrans = tonumber(Cfg.ClientSideTransparency) or 50
        if lastGhostColor ~= Cfg.ClientSideColor or lastGhostTrans ~= currentTrans then lastGhostColor = Cfg.ClientSideColor; lastGhostTrans = currentTrans; UpdateGhostAppearance() end
        local poseTime = tick()
        local currentPose
        while #GhostHistory > 1 and (GhostHistory[2].t <= poseTime - 0.1 or #GhostHistory >= 64) do
            currentPose = table.remove(GhostHistory, 1)
        end
        currentPose = currentPose or {parts = {}}
        currentPose.t = poseTime
        table.clear(currentPose.parts)
        for i = 1, #GhostPartsArray do local p = GhostPartsArray[i]; currentPose.parts[p.real] = p.real.CFrame end
        table.insert(GhostHistory, currentPose)
        local targetTime = tick() - 0.1; local targetPose = GhostHistory[#GhostHistory]
        for i = #GhostHistory, 1, -1 do if GhostHistory[i].t <= targetTime then targetPose = GhostHistory[i]; break end end
        if targetPose then for i = 1, #GhostPartsArray do local p = GhostPartsArray[i]; p.ghost.CFrame = targetPose.parts[p.real] end end
    else
        if GhostModel then GhostModel:Destroy(); GhostModel = nil; GhostPartsArray = {}; GhostHistory = {}; currentGhostCharRef = nil end
    end

    Session:SyncPlayerVisualActivation()
    local allPlayers = Cfg.ChamsEnabled and Session:PlayerVisualDue(dt, true) and Players:GetPlayers() or Session.EmptyPlayers
    for i = 1, #allPlayers do
        local player = allPlayers[i]
        if player ~= LocalPlayer then
            local plChar = player.Character
            local espCache = GetEspElements(player)
            local hasHRP = plChar and plChar:FindFirstChild("HumanoidRootPart")
            
            local sameTeam = (player.Team == LocalPlayer.Team and player.Team ~= nil)
            local isIgnoredTeam = player.Team and Cfg["ChamsIgnore_" .. player.Team.Name]

            if Cfg.ChamsEnabled and not Session:IsFriend(player) and hasHRP and (not Cfg.ChamsTeamCheck or not sameTeam) and not isIgnoredTeam then
                
                if espCache.ChamsHighlight.Adornee ~= plChar then espCache.ChamsHighlight.Adornee = plChar end
                if not espCache.ChamsHighlight.Enabled then espCache.ChamsHighlight.Enabled = true end
                
                if espCache.ChamsHighlight.FillColor ~= Cfg.ChamsColor then espCache.ChamsHighlight.FillColor = Cfg.ChamsColor end
                if espCache.ChamsHighlight.FillTransparency ~= Cfg.ChamsFillTransparency then espCache.ChamsHighlight.FillTransparency = Cfg.ChamsFillTransparency end
                
                if espCache.ChamsHighlight.OutlineColor ~= Cfg.ChamsOutlineColor then espCache.ChamsHighlight.OutlineColor = Cfg.ChamsOutlineColor end
                if espCache.ChamsHighlight.OutlineTransparency ~= Cfg.ChamsOutlineTransparency then espCache.ChamsHighlight.OutlineTransparency = Cfg.ChamsOutlineTransparency end
                
                local targetDepth = Cfg.ChamsWallhack and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
                if espCache.ChamsHighlight.DepthMode ~= targetDepth then espCache.ChamsHighlight.DepthMode = targetDepth end
            else
                if espCache.ChamsHighlight.Enabled then espCache.ChamsHighlight.Enabled = false end
            end
        end
    end
end))

-- Platform: Roblox client / Luau; target: change-driven scene settings.
do
    local keys = {"CustomFovEnabled", "CustomFovValue", "FullBrightEnabled", "WorldColorEnabled", "WorldColorValue", "FullBrightTime", "TimeChangerEnabled", "TimeChangerHours", "SaturationEnabled", "SaturationValue", "ThirdPersonEnabled", "ThirdPersonDistance", "WorldColorShader", "WorldColorTransparency", "WorldColorDarkness", "LowEndMode"}
    local values, lastCamera, cameraConnection = {}, nil, nil
    Session.SceneDirty = true
    for _, property in ipairs({"CameraMode", "CameraMinZoomDistance", "CameraMaxZoomDistance"}) do
        Session:Connect(LocalPlayer:GetPropertyChangedSignal(property), function() Session.SceneDirty = true end)
    end
    Session:Connect(Lighting.Changed, function(property)
        if property == "Ambient" or property == "OutdoorAmbient" or property == "GlobalShadows"
            or property == "ClockTime" or property == "FogColor" or property == "FogStart"
            or property == "FogEnd" or property == "ExposureCompensation" then Session.SceneDirty = true end
    end)
    function Session:UpdateSceneSettings()
        local Camera = workspace.CurrentCamera
        if not Camera then return end
        local changed = self.SceneDirty or Camera ~= lastCamera
        if Camera ~= lastCamera then
            if cameraConnection then cameraConnection:Disconnect() end
            cameraConnection = self:Connect(Camera:GetPropertyChangedSignal("FieldOfView"), function() self.SceneDirty = true end)
            lastCamera = Camera
        end
        for _, key in ipairs(keys) do
            if values[key] ~= Cfg[key] then values[key] = Cfg[key]; changed = true end
        end
        if not changed then return end
        self.SceneDirty = false
    if Cfg.CustomFovEnabled then Session:Override("FOV", Camera, {FieldOfView = Cfg.CustomFovValue}) else Session:Release("FOV") end
    if Cfg.FullBrightEnabled then
        Session:Override("Ambient", Lighting, {Ambient = Color3.new(1,1,1), OutdoorAmbient = Color3.new(1,1,1)})
        Session:Override("Shadows", Lighting, {GlobalShadows = false})
    else
        Session:Release("Shadows")
        if Cfg.WorldColorEnabled and not Cfg.WorldColorShader then
            Session:Override("Ambient", Lighting, {Ambient = Cfg.WorldColorValue, OutdoorAmbient = Cfg.WorldColorValue})
        else Session:Release("Ambient") end
    end
    if Cfg.FullBrightEnabled or Cfg.TimeChangerEnabled then
        Session:Override("Time", Lighting, {ClockTime = Cfg.FullBrightEnabled and Cfg.FullBrightTime or Cfg.TimeChangerHours})
    else Session:Release("Time") end
    UpdateWorldShader()
    SaturationEffect.Enabled = Cfg.SaturationEnabled
    SaturationEffect.Saturation = Cfg.SaturationValue / 10
    if Cfg.ThirdPersonEnabled then
        Session:Override("CameraMode", LocalPlayer, {CameraMode = Enum.CameraMode.Classic, CameraMinZoomDistance = Cfg.ThirdPersonDistance, CameraMaxZoomDistance = Cfg.ThirdPersonDistance})
    else Session:Release("CameraMode") end

    

    end
end

-- // РЕНДЕР СТЕП
RunService:BindToRenderStep(Session.RenderName, 202, function(dt)
    if not Session.Alive or not Session.Ready then return end
    Session:UpdateDamageNumbers(dt)
    Session:UpdateWorldCubes(dt)
    Session:UpdateHitSplashes(dt)
    local Camera = workspace.CurrentCamera; if not Camera then return end
    local char = LocalPlayer.Character
    local target = not Session:IsFriend(SharedTarget) and SharedTarget or nil
    local currentKaTarget = not Session:IsFriend(SharedKaTarget) and SharedKaTarget or nil
    local camCFrame = Camera.CFrame
    local camPos = camCFrame.Position

    local hudTarget = if Cfg.TargetHudOnlyKillaura then currentKaTarget else target
    Session:ObserveDamageTarget(hudTarget)
    local espTarget = if Cfg.TargetESPOnlyKillaura then currentKaTarget else target

    Session:UpdateSceneSettings()

    if char and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChild("Humanoid") then
        local hum = char.Humanoid
        local hrp = char.HumanoidRootPart
        local state = hum:GetState()
        local isAirborne = (state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Jumping)
        local isMoving = hum.MoveDirection.Magnitude > 0
        local airStrafeVelocity = Session:GetAirStrafeVelocity(char, hum, hrp)
        
        if Cfg.SpeedEnabled then
            Session:Override("Speed", hum, {WalkSpeed = Cfg.WalkSpeedValue})
            if Cfg.SpeedACMode then
                local baseline = Session.Overrides.Speed.Values.WalkSpeed
                hum.WalkSpeed = baseline
                local extraSpeed = Cfg.WalkSpeedValue - baseline
                if extraSpeed > 0 and isMoving and not airStrafeVelocity then hrp.CFrame += hum.MoveDirection * extraSpeed * math.min(dt, 0.1) end
            end
        else
            Session:Release("Speed")
        end

        if Cfg.VelocityEnabled then
            local current = hrp.AssemblyLinearVelocity
            local speed = Cfg.SpeedEnabled and Cfg.WalkSpeedValue or hum.WalkSpeed
            local desired = hum.MoveDirection * speed
            local retentionH = (Cfg.VelocityHorizontal / 100) ^ math.max(dt * 60, 0.01)
            local x = desired.X + (current.X - desired.X) * retentionH
            local z = desired.Z + (current.Z - desired.Z) * retentionH
            local y = current.Y
            local jumping = tick() - math.max(lastRealJumpTime, lastKillStrafeJumpTime, lastCriticalJumpTime) < 0.3
            if y > 0 and not jumping and not UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                y *= (Cfg.VelocityVertical / 100) ^ math.max(dt * 60, 0.01)
            end
            hrp.AssemblyLinearVelocity = Vector3.new(x, y, z)
        end

        -- Air Strafe owns horizontal movement after knockback damping; Y is left intact.
        if airStrafeVelocity then
            local current = hrp.AssemblyLinearVelocity
            hrp.AssemblyLinearVelocity = Vector3.new(airStrafeVelocity.X, current.Y, airStrafeVelocity.Z)
        end
        if Cfg.StrafeEnabled and hum.MoveDirection.Magnitude > 0 and not airStrafeVelocity then 
            local currentSpeed = Cfg.SpeedEnabled and Cfg.WalkSpeedValue or hum.WalkSpeed; local instantVel = hum.MoveDirection.Unit * currentSpeed; hrp.AssemblyLinearVelocity = Vector3.new(instantVel.X, hrp.AssemblyLinearVelocity.Y, instantVel.Z) 
        elseif Cfg.StrafeEnabled and hum.MoveDirection.Magnitude == 0 then 
            hrp.AssemblyLinearVelocity = Vector3.new(0, hrp.AssemblyLinearVelocity.Y, 0) 
        end
        
        if Cfg.SpiderEnabled and UserInputService:IsKeyDown(Enum.KeyCode.Space) then
            local rayParams = RaycastParams.new(); rayParams.FilterDescendantsInstances = {char, ChamsFolder, Chams3DFolder, Session.Effects, Session.WorldCubesFolder}; rayParams.FilterType = Enum.RaycastFilterType.Exclude
            local dirs = {hrp.CFrame.LookVector, -hrp.CFrame.LookVector, hrp.CFrame.RightVector, -hrp.CFrame.RightVector}; local touching = false
            for _, dir in ipairs(dirs) do
                local ray1 = workspace:Raycast(hrp.Position, dir * 2.5, rayParams); local ray2 = workspace:Raycast(hrp.Position + Vector3.new(0, 1, 0), dir * 2.5, rayParams); local ray3 = workspace:Raycast(hrp.Position - Vector3.new(0, 1, 0), dir * 2.5, rayParams)
                local function checkRay(r) return r and r.Instance and r.Instance:IsA("BasePart") and r.Instance.CanCollide end
                if checkRay(ray1) or checkRay(ray2) or checkRay(ray3) then touching = true; break end
            end
            if touching then hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, tonumber(Cfg.SpiderSpeed) or 45, hrp.AssemblyLinearVelocity.Z) end
        end

        local isFirstPerson = char:FindFirstChild("Head") and (camCFrame.Position - char.Head.Position).Magnitude <= 1.5

        if Cfg.ViewHandsEnabled and isFirstPerson then
            local xOff = tonumber(Cfg.ViewHandsOffsetX) or 0
            local yOff = tonumber(Cfg.ViewHandsOffsetY) or 0
            local zOff = tonumber(Cfg.ViewHandsOffsetZ) or 0
            local head = char:FindFirstChild("Head")
            
            for i = 1, #ViewHandsParts do local part = ViewHandsParts[i]; if part.Parent then if Session.ArmTransparency[part] == nil then Session.ArmTransparency[part] = part.LocalTransparencyModifier end; part.LocalTransparencyModifier = 0 end end
            
            local velocity = hrp.AssemblyLinearVelocity
            local flatSpeed = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
            
            idleTime = idleTime + dt
            local idleBob = CFrame.new(math.cos(idleTime * 1.5) * 0.01, math.sin(idleTime * 3) * 0.015, 0)
            
            if isMoving and flatSpeed > 1 and not isAirborne then
                local speedMult = math.clamp(flatSpeed / 16, 0.5, 1.5)
                walkTime = walkTime + dt * (10 * speedMult)
                local bX = math.cos(walkTime * 0.5) * (0.15 * speedMult)
                local bY = math.sin(walkTime) * (0.12 * speedMult)
                local bRoll = math.sin(walkTime * 0.5) * (0.05 * speedMult)
                targetBob = CFrame.new(bX, bY, 0) * CFrame.Angles(0, 0, bRoll)
            else
                targetBob = CFrame.new()
            end
            currentBob = currentBob:Lerp(targetBob, 1 - math.exp(-12 * dt))
            
            local vY = velocity.Y
            local clampedY = math.clamp(vY / 50, -1, 1)
            targetJumpOffset = CFrame.new(0, -clampedY * 0.5, clampedY * 0.15) * CFrame.Angles(math.rad(clampedY * 25), 0, 0)
            currentJumpOffset = currentJumpOffset:Lerp(targetJumpOffset, 1 - math.exp(-15 * dt))
            
            local mouseDelta = UserInputService:GetMouseDelta()
            targetSway = CFrame.Angles(
                math.clamp(-mouseDelta.Y * 0.002, -0.15, 0.15),
                math.clamp(-mouseDelta.X * 0.0025, -0.15, 0.15),
                math.clamp(-mouseDelta.X * 0.0015, -0.1, 0.1)
            )
            swayCFrame = swayCFrame:Lerp(targetSway, 1 - math.exp(-10 * dt))

            for i = 1, #CurrentArmJoints do
                local j = CurrentArmJoints[i]
                if j.Parent and Session:IsFiniteFrame(j.C0) then
                    local origC0 = OrigMotorC0[j] or j.C0
                    local torso = j.Part0
                    
                    if torso and head then
                        local visualOffset = swayCFrame * currentJumpOffset * currentBob * idleBob * CFrame.new(xOff, yOff, zOff)
                        
                        if Cfg.ViewHandsCameraLock then
                            local headOffset = head.CFrame:Inverse() * torso.CFrame
                            local targetC0 = torso.CFrame:Inverse() * camCFrame * visualOffset * headOffset * origC0
                            Session:WriteArmC0(j, j.C0:Lerp(targetC0, 1 - math.exp(-25 * dt)))
                        else
                            local right = camCFrame.RightVector * visualOffset.X
                            local up = camCFrame.UpVector * visualOffset.Y
                            local fwd = camCFrame.LookVector * visualOffset.Z
                            local localOffset = torso.CFrame:VectorToObjectSpace(right + up + fwd)
                            local targetC0 = CFrame.new(origC0.Position + localOffset) * origC0.Rotation * visualOffset.Rotation
                            Session:WriteArmC0(j, j.C0:Lerp(targetC0, 1 - math.exp(-20 * dt)))
                        end
                    end
                end
            end
        else
            Session:RestoreArms()
            Session:RestoreArmJoints()
        end
    end

    local localHrp = char and char:FindFirstChild("HumanoidRootPart")
    
    Session:SyncPlayerVisualActivation()
    local allPlayers = (Cfg.Esp2DBoxEnabled or Cfg.ArrowsEnabled) and Session:PlayerVisualDue(dt, false) and Players:GetPlayers() or Session.EmptyPlayers
    for i = 1, #allPlayers do
        local player = allPlayers[i]
        if player ~= LocalPlayer then
            local plChar = player.Character
            local espCache = GetEspElements(player)
            local hasHRP = plChar and plChar:FindFirstChild("HumanoidRootPart")
            
            local sameTeam = (player.Team == LocalPlayer.Team and player.Team ~= nil)
            local isIgnoredTeam = player.Team and Cfg["Esp2DBoxIgnore_" .. player.Team.Name]

            if Cfg.Esp2DBoxEnabled and not Session:IsFriend(player) and hasHRP and (not Cfg.Esp2DBoxTeamCheck or not sameTeam) and not isIgnoredTeam then
                local hrp = plChar.HumanoidRootPart; local pos, onScreen = Session:ProjectToViewport(Camera, hrp.Position)
                if onScreen then
                    local head = plChar:FindFirstChild("Head"); 
                    local topPos = head and head.Position + Vector3.new(0, 1.2, 0) or hrp.Position + Vector3.new(0, 3.5, 0); 
                    local bottomPos = hrp.Position - Vector3.new(0, 3.5, 0)
                    local topScreen = Session:ProjectToViewport(Camera, topPos); local bottomScreen = Session:ProjectToViewport(Camera, bottomPos)
                    local height = math.abs(bottomScreen.Y - topScreen.Y); local baseMultiplier = tonumber(Cfg.Esp2DBoxSize) or 1; local finalHeight = height * baseMultiplier; local width = (height / 1.5) * baseMultiplier * Session:GetStretchFactor(Camera) 
                    
                    if not espCache.Box2D.Visible then espCache.Box2D.Visible = true end
                    if espCache.Width ~= width or espCache.Height ~= finalHeight then
                        espCache.Width, espCache.Height = width, finalHeight
                        espCache.Box2D.Size = UDim2.fromOffset(width, finalHeight)
                    end
                    local x, y = pos.X - width/2, pos.Y - finalHeight/2
                    if espCache.X ~= x or espCache.Y ~= y then
                        espCache.X, espCache.Y = x, y
                        espCache.Box2D.Position = UDim2.fromOffset(x, y)
                    end
                    
                    Session:UpdateBoxEspStyle(espCache, player, pos.Z, Camera.ViewportSize.Y, Camera.FieldOfView)
                elseif espCache.Box2D.Visible then 
                    espCache.Box2D.Visible = false 
                end
            elseif espCache.Box2D.Visible then 
                espCache.Box2D.Visible = false 
            end

            if Cfg.ArrowsEnabled and not Session:IsFriend(player) and hasHRP and localHrp then
                Session:UpdateArrow(espCache, plChar.HumanoidRootPart, localHrp, camCFrame, Camera.ViewportSize)
            else
                Session:HideArrow(espCache)
            end
        end
    end
    
    if Cfg.ChinaHatAccessoryEnabled and char and char:FindFirstChild("Head") then HatPart.Transparency = Cfg.ChinaHatTransparency; HatPart.Color = Cfg.ChinaHatAccessoryColor; HatMesh.Scale = Vector3.new(Cfg.ChinaHatWidthScale, Cfg.ChinaHatHeightScale, Cfg.ChinaHatWidthScale); HatPart.CFrame = char.Head.CFrame * CFrame.new(0, Cfg.ChinaHatHeightOffset, 0) else HatPart.Transparency = 1 end

    Session:UpdateTargetHUD(hudTarget, dt)

    if Cfg.TargetESPSquareEnabled and espTarget and espTarget.Character and espTarget.Character:FindFirstChild("HumanoidRootPart") then
        local espHum = espTarget.Character:FindFirstChild("Humanoid")
        if espHum then if lastEspTargetUserId ~= espTarget.UserId then lastEspTargetUserId = espTarget.UserId; lastEspTargetHealth = espHum.Health; lastDamageTimeESP = 0 end; if lastEspTargetHealth and espHum.Health < lastEspTargetHealth then lastDamageTimeESP = tick() end; lastEspTargetHealth = espHum.Health end
        local currentEspColor = Cfg.TargetESPSquareColor
        if Cfg.TargetESPDamageColorEnabled then local timeSinceDmgEsp = tick() - lastDamageTimeESP; if timeSinceDmgEsp < 0.6 then currentEspColor = Cfg.TargetESPDamageColor:Lerp(Cfg.TargetESPSquareColor, timeSinceDmgEsp / 0.6) end end
        local pos, onScreen = Session:ProjectToViewport(Camera, espTarget.Character.HumanoidRootPart.Position)
        if Session:UpdateTargetEspLayout(pos, onScreen, Camera.ViewportSize, Camera.FieldOfView) then
            ESPMain.Rotation = (tick() * 60 * Cfg.TargetESPRotationSpeed) % 360 
            Session:UpdateTargetEspTexture(currentEspColor)
        elseif ESPMain.Visible then 
            ESPMain.Visible = false 
        end
    elseif ESPMain.Visible then 
        ESPMain.Visible = false; lastEspTargetUserId = nil; lastEspTargetHealth = nil 
    end

    local didRotateHRP = false

    local strafeTarget = not Session:IsFriend(Session.StrafeTarget) and Session.StrafeTarget or nil
    if Cfg.TargetStrafeOrbitEnabled and strafeTarget and strafeTarget.Character and strafeTarget.Character:FindFirstChild("HumanoidRootPart") and localHrp then
        local angle = tick() * Cfg.TargetStrafeOrbitSpeed; local offset = Vector3.new(math.cos(angle), 0, math.sin(angle)) * Cfg.TargetStrafeOrbitRadius; localHrp.CFrame = CFrame.new(strafeTarget.Character.HumanoidRootPart.Position + offset, strafeTarget.Character.HumanoidRootPart.Position)
        didRotateHRP = true 
    end
    
    if Cfg.KillAuraEnabled and char and localHrp and currentKaTarget and currentKaTarget.Character then
        local targetPart = currentKaTarget.Character:FindFirstChild("HumanoidRootPart")
        if targetPart then
            local hrp = localHrp; local dist = (hrp.Position - targetPart.Position).Magnitude
            if dist <= Cfg.KillAuraRange and IsVisible(targetPart) then
                if Cfg.KillStrafeEnabled and char:FindFirstChild("Humanoid") then
                    local flatToTarget = Vector3.new(targetPart.Position.X - hrp.Position.X, 0, targetPart.Position.Z - hrp.Position.Z); local distFlat = flatToTarget.Magnitude
                    if distFlat > 0.1 then
                        if tick() > nextKaStrafeDirChange then currentKaStrafeDir = -currentKaStrafeDir; nextKaStrafeDirChange = tick() + (math.random(40, 90) / 100) end
                        local dirToTarget = flatToTarget.Unit; local rightDir = dirToTarget:Cross(Vector3.new(0, 1, 0)).Unit * currentKaStrafeDir; local noise = math.sin(tick() * 4) * 0.3; local currentOrbitDist = tonumber(Cfg.KillStrafeDistance) or 1; local distanceError = distFlat - (currentOrbitDist + noise); local moveDir = (dirToTarget * distanceError + rightDir * 3).Unit
                        char.Humanoid:Move(moveDir, false); local kStrafeSpeed = tonumber(Cfg.KillStrafeSpeed) or 20; hrp.AssemblyLinearVelocity = Vector3.new(moveDir.X * kStrafeSpeed, hrp.AssemblyLinearVelocity.Y, moveDir.Z * kStrafeSpeed)
                        local shouldJump = true; if Cfg.CriticalsNoKillStrafeJump then shouldJump = false end
                        if shouldJump and tick() - lastStrafeJumpTime > nextStrafeJumpDelay then if char.Humanoid.FloorMaterial ~= Enum.Material.Air then char.Humanoid.Jump = true; lastStrafeJumpTime = tick(); lastKillStrafeJumpTime = tick(); nextStrafeJumpDelay = math.random(1, 8) / 10 end end
                    end
                end

                if Session.PlaceSupport.NoCamRotate and Cfg.KillAuraNoCamRotation then
                    local facing = Session.PlaceSupport.TurnBody and Session:HorizontalFacing(hrp.Position, targetPart.Position)
                    if facing and Session.PlaceSupport.TurnBody then
                        local savedVel = hrp.AssemblyLinearVelocity
                        Session:Override("Rotation", char.Humanoid, {AutoRotate = false})
                        hrp.CFrame = facing
                        hrp.AssemblyLinearVelocity = savedVel
                        didRotateHRP = true
                    end
                else 
                    local cameraDelta = targetPart.Position - camPos
                    if Session:IsFiniteVector(cameraDelta) and cameraDelta.Magnitude > 0.001 then
                        local up = math.abs(cameraDelta.Unit.Y) > 0.999 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
                        local aim = CFrame.lookAt(camPos, targetPart.Position, up)
                        if Session:IsFiniteFrame(aim) then
                            Camera.CFrame = camCFrame:Lerp(aim, (1 - (1 - Cfg.AimbotSmoothness) ^ math.max(dt * 60, 0.01)))
                        end
                    end
                    local facing = Session:HorizontalFacing(hrp.Position, targetPart.Position)
                    if facing then
                        local savedVel = hrp.AssemblyLinearVelocity
                        Session:Override("Rotation", char.Humanoid, {AutoRotate = false})
                        hrp.CFrame = facing
                        hrp.AssemblyLinearVelocity = savedVel
                        didRotateHRP = true
                    end
                end
                
                Session:TryAuraAttack(currentKaTarget)

            end
        end
    end

    if not didRotateHRP and Cfg.JitterEnabled and char and char:FindFirstChild("Humanoid") and localHrp then
        local hrp = localHrp
        Session:Override("Rotation", char.Humanoid, {AutoRotate = false})
        
        local state = char.Humanoid:GetState()
        if Cfg.JitterSpinAtJump and (state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Jumping) then 
            local spinSpeed = tonumber(Cfg.JitterSpinSpeed) or 20
            local spinAngle = math.rad((tick() * spinSpeed * 15) % 360)
            local spinFrame = CFrame.new(hrp.Position) * CFrame.Angles(0, spinAngle, 0)
            if Session:IsFiniteFrame(spinFrame) then hrp.CFrame = spinFrame; didRotateHRP = true end
        else 
            local jitterSign = (math.floor(tick() * (Cfg.JitterSpeed or 15)) % 2 == 0) and 1 or -1
            local jitterYaw = math.rad(Cfg.JitterRange or 45) * jitterSign
            local baseYaw = (tonumber(Cfg.JitterYawMode) == 2) and math.pi or 0
            local totalYaw = baseYaw + jitterYaw 
            
            local lookVec = camCFrame.LookVector; if char.Humanoid.MoveDirection.Magnitude > 0 then lookVec = char.Humanoid.MoveDirection end
            local baseRot = Session:HorizontalFacing(hrp.Position, hrp.Position + lookVec)
                or Session:HorizontalFacing(hrp.Position, hrp.Position + hrp.CFrame.LookVector)
            if baseRot then
                local jitterFrame = baseRot * CFrame.Angles(0, totalYaw, 0)
                if Session:IsFiniteFrame(jitterFrame) then hrp.CFrame = jitterFrame; didRotateHRP = true end
            end
        end
    end
    
    if not didRotateHRP then Session:Release("Rotation") end

    if Cfg.CriticalsEnabled and char and localHrp and char:FindFirstChild("Humanoid") then
        local canCrit = true; if Cfg.CriticalsOnlyKillAura and not Cfg.KillAuraEnabled then canCrit = false end
        if canCrit and char.Humanoid.FloorMaterial ~= Enum.Material.Air then
            localHrp.CFrame = localHrp.CFrame + Vector3.new(0, 1, 0); localHrp.AssemblyLinearVelocity = Vector3.new(localHrp.AssemblyLinearVelocity.X, 0, localHrp.AssemblyLinearVelocity.Z); lastCriticalJumpTime = tick()
        end
    end

    local aimTarget = not Session:IsFriend(Session.AimbotTarget) and Session.AimbotTarget or nil
    if not Cfg.KillAuraEnabled and Cfg.AimbotEnabled and aimTarget and aimTarget.Character and aimTarget.Character:FindFirstChild("Head") and localHrp then
        Camera.CFrame = camCFrame:Lerp(CFrame.new(camPos, aimTarget.Character.Head.Position), (1 - (1 - Cfg.AimbotSmoothness) ^ math.max(dt * 60, 0.01)))
    end
end)

-- // INFINITE JUMP LOGIC
table.insert(Connections, UserInputService.JumpRequest:Connect(function()
    if Cfg.InfJumpEnabled then
        local char = LocalPlayer.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then Session:RequestInfiniteJump(char, hum) end
        end
    end
end))

local function UpdateViewHandsParts(char)
    ViewHandsParts = {}
    CurrentArmJoints = {}
    if not char then return end
    local armNames = { ["Left Arm"] = true, ["Right Arm"] = true, ["LeftHand"] = true, ["RightHand"] = true, ["LeftLowerArm"] = true, ["RightLowerArm"] = true, ["LeftUpperArm"] = true, ["RightUpperArm"] = true }
    for _, p in ipairs(char:GetDescendants()) do 
        if p:IsA("BasePart") and armNames[p.Name] then table.insert(ViewHandsParts, p) end 
    end
    
    local hum = char:FindFirstChild("Humanoid")
    if hum then
        if hum.RigType == Enum.HumanoidRigType.R15 then
            local r = char:FindFirstChild("RightUpperArm") and char.RightUpperArm:FindFirstChild("RightShoulder")
            local l = char:FindFirstChild("LeftUpperArm") and char.LeftUpperArm:FindFirstChild("LeftShoulder")
            if r then table.insert(CurrentArmJoints, r) end
            if l then table.insert(CurrentArmJoints, l) end
        else
            local t = char:FindFirstChild("Torso")
            if t then
                local r = t:FindFirstChild("Right Shoulder")
                local l = t:FindFirstChild("Left Shoulder")
                if r then table.insert(CurrentArmJoints, r) end
                if l then table.insert(CurrentArmJoints, l) end
            end
        end

    end
end

local function ConnectJumpAndHands(char)
    Session:ClearCharacterParts()
    Session:ResetTargetLocks()
    Session:ResetSoftCamera()
    Session:ResetNoFall(false)
    Session:RefreshNoFallScripts()
    if Session.ResetAuraAttack then Session:ResetAuraAttack() end
    for _, connection in ipairs(Session.CharacterConnections) do connection:Disconnect() end
    table.clear(Session.CharacterConnections)
    Session:ClearJumpCircles()
    Session:ClearHitSplashes()
    Session.JumpHumanoid = nil
    Session.JumpStateActive = false
    Session:RestoreArms()
    Session:RestoreAnimations()
    Session:Release("Speed")
    Session:Release("Rotation")
    Session:RestoreArmJoints()
    for part, state in pairs(OrigNoClipStates) do if part.Parent then part.CanCollide = state end end
    table.clear(OrigMotorC0)
    table.clear(OrigNoClipStates)
    ViewHandsParts = {}
    CurrentArmJoints = {}
    local generation = (Session.CharacterGeneration or 0) + 1
    Session.CharacterGeneration = generation
    task.spawn(function()
        local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 10)
        if not Session.Alive or Session.CharacterGeneration ~= generation or char ~= LocalPlayer.Character or not hum then return end
        Session:Connect(hum.Jumping, function(active)
            Session:OnCharacterJump(char, hum, active)
        end, Session.CharacterConnections)
        UpdateViewHandsParts(char)
        local refreshPending = false
        local function refresh(desc)
            if not desc:IsA("BasePart") and not desc:IsA("Motor6D") then return end
            if refreshPending then return end
            refreshPending = true
            task.defer(function()
                refreshPending = false
                if Session.Alive and Session.CharacterGeneration == generation then UpdateViewHandsParts(char) end
            end)
        end
        Session:Connect(char.DescendantAdded, refresh, Session.CharacterConnections)
        Session:Connect(char.DescendantRemoving, refresh, Session.CharacterConnections)
    end)
end
Session:Connect(LocalPlayer.CharacterAdded, ConnectJumpAndHands)
if LocalPlayer.Character then ConnectJumpAndHands(LocalPlayer.Character) end

-- Platform: Roblox client / Luau; target: immediate removal of effects on friends.
function Session:ApplyFriendExclusions()
    self:PruneFriendlyFeedback()
    -- Changing friends invalidates eligibility, including previously locked targets.
    self:UpdateTargets()
    for _, player in ipairs(Players:GetPlayers()) do
        if self:IsFriend(player) then
            local character = player.Character
            AntiFlingCache[player] = nil
            if character then
                for instance, data in pairs(OrigPartData) do
                    if instance:IsDescendantOf(character) then
                        pcall(function()
                            if instance:IsA("BasePart") then
                                instance.Size, instance.CanCollide, instance.Massless = data.Size, data.CanCollide, data.Massless
                            end
                            instance.Transparency = data.Trans
                        end)
                        OrigPartData[instance] = nil
                    end
                end
                for part, original in pairs(self.AntiFlingParts) do
                    if part:IsDescendantOf(character) then
                        part.CanCollide = original
                        self.AntiFlingParts[part] = nil
                    end
                end
                local fake = character:FindFirstChild("Notification_FakeHead")
                if fake then fake:Destroy() end
            end
            local cache = EspCache[player]
            if cache then
                cache.Box2D.Visible, cache.Arrow.Visible, cache.ChamsHighlight.Enabled = false, false, false
                EspHiddenState[player] = nil
            end
        end
    end
    self:ClearFriendlyHitSplashes()
    self:ClearFriendlyDamageNumbers()
    for sound, userId in pairs(self.HitFeedbackSounds) do
        if self:IsFriend(userId) then sound:Destroy(); self.HitFeedbackSounds[sound] = nil end
    end
    local hudTarget = if Cfg.TargetHudOnlyKillaura then SharedKaTarget else SharedTarget
    self:ObserveDamageTarget(hudTarget)
    self:UpdateTargetHUD(hudTarget, 0)
    -- Re-render a new target on the next frame; never leave the old marker on a friend.
    ESPMain.Visible = false
    lastEspTargetUserId, lastEspTargetHealth = nil, nil
    self.PlayerVisualForce, self.ChamsForce = true, true
end
-- End immediate friend exclusions.

function Session:RestoreHitboxes()
    for instance, data in pairs(OrigPartData) do
        if instance.Parent then
            pcall(function()
                if instance:IsA("BasePart") then
                    instance.Size = data.Size
                    instance.CanCollide = data.CanCollide
                    instance.Massless = data.Massless
                end
                instance.Transparency = data.Trans
            end)
        end
    end
    table.clear(OrigPartData)
    for _, player in ipairs(Players:GetPlayers()) do
        local fake = player.Character and player.Character:FindFirstChild("Notification_FakeHead")
        if fake then fake:Destroy() end
    end
end

function Session:Changed(key)
    if key == "SoftCameraEnabled" and not Cfg.SoftCameraEnabled then self:ResetSoftCamera() end
    if key == "StretchScreenEnabled" or key == "StretchScreenAmount" then self:RefreshStretchScreen() end
    if key == "KillAuraEnabled" and not Cfg.KillAuraEnabled then self:ResetAuraAttack() end
    if key == "KillAuraNoCamRotation" then self:RefreshAimHooks() end
    if key:match("^BridgeViewmodel") then self:RefreshBridgeViewmodel() end
    if key == "HitSoundEnabled" or key == "HitSoundOnDamage" or key == "DamageParticlesEnabled" or key == "HitParticlesOnDamage" then
        self:RefreshHitFeedback(key)
    end
    if key == "HitSoundEnabled" or key == "HitSoundMode" then
        if Cfg.HitSoundEnabled then self:PrepareHitSound() else self:ClearHitSounds() end
    end
    if key == "Friends" then self:FriendsChanged() end
    self.PlayerVisualForce, self.ChamsForce = true, true
    if key == "NoFallEnabled" or key == "NoFallClientScripts" or key == "NoFallVelocityReset" then
        if not Cfg.NoFallEnabled or not Cfg.NoFallVelocityReset then self:ResetNoFall(true) end
        self:RefreshNoFallScripts()
    end
    if key == "DamageParticlesEnabled" and not Cfg.DamageParticlesEnabled then self:ClearHitSplashes() end
    if key == "WorldParticlesEnabled" and not Cfg.WorldParticlesEnabled then self:ClearWorldCubes() end
    if key == "DamageNumbersEnabled" and not Cfg.DamageNumbersEnabled then self:ClearDamageNumbers(true) end
    if key == "JumpVisualCirclesEnabled" and not Cfg.JumpVisualCirclesEnabled then self:ClearJumpCircles() end
    if key == "SpeedEnabled" and not Cfg.SpeedEnabled then self:Release("Speed") end
    if key == "HitboxEnabled" and not Cfg.HitboxEnabled then self:RestoreHitboxes() end
    if key == "AntiFlingEnabled" and not Cfg.AntiFlingEnabled then self:RestoreAntiFling() end
    if key == "AnimLagEnabled" and not Cfg.AnimLagEnabled then self:RestoreAnimations() end
    if key == "NoClipEnabled" and not Cfg.NoClipEnabled then
        for part, state in pairs(OrigNoClipStates) do if part.Parent then part.CanCollide = state end end
        table.clear(OrigNoClipStates)
    end
    if key == "KillAuraEnabled" or key == "AimbotEnabled" or key == "TargetStrafeOrbitEnabled"
        or key == "KillAuraTargetLock" or key == "AimbotTargetLock" or key == "TargetStrafeTargetLock"
        or key == "KillAuraRange" or key == "AimbotMaxDistance" or key == "AimbotTeamCheck"
        or key == "AimbotWallCheck" or key:match("^AimbotIgnore_") then self:UpdateTargets() end
    if key == "ViewHandsEnabled" and not Cfg.ViewHandsEnabled then
        self:RestoreArms()
        Session:RestoreArmJoints()
    end
    if key == "CustomFovEnabled" and not Cfg.CustomFovEnabled then self:Release("FOV") end
    if key == "ThirdPersonEnabled" and not Cfg.ThirdPersonEnabled then self:Release("CameraMode") end
    if key == "TargetHudPosition" and not Cfg.TargetHudInPlayer then
        TargetHUD.Position = Cfg.TargetHudPosition
        self:ClampHudPosition(false)
    end
    if key == "TargetHudScale" then self:SyncHudAppearance() end
    if key == "TargetHudInPlayer" or key == "TargetHudSide" or key == "TargetHudHeadDistance"
        or key == "TargetHudEnabled" then
        self:RefreshHudPlacement()
    end
    if key:match("^WorldColor") or key == "LowEndMode" then
        self.SceneDirty = true
        self:UpdateSceneSettings()
    end
end

function Session:ClampHudPosition(save)
    local camera = workspace.CurrentCamera
    if not camera then return end
    local viewport = camera.ViewportSize
    local position = TargetHUD.Position
    local width = TargetHUD.Size.X.Offset * Hud.Scale.Scale
    local height = TargetHUD.Size.Y.Offset * Hud.Scale.Scale
    local x = viewport.X * position.X.Scale + position.X.Offset
    local y = viewport.Y * position.Y.Scale + position.Y.Offset
    local nx = math.clamp(x, 4, math.max(4, viewport.X - width - 4))
    local ny = math.clamp(y, 4, math.max(4, viewport.Y - height - 4))
    if math.abs(nx - x) > 0.1 or math.abs(ny - y) > 0.1 then
        TargetHUD.Position = UDim2.new(position.X.Scale, position.X.Offset + nx - x, position.Y.Scale, position.Y.Offset + ny - y)
        if save and not Cfg.TargetHudInPlayer then Cfg.TargetHudPosition = TargetHUD.Position; SaveLocalMAIN() end
    end
end

function Session:SyncHudDecorations()
    local opacity = math.clamp(tonumber(window.Opacity) or 1, 0.5, 1)
    if Hud.DecorOpacity ~= opacity then
        Hud.DecorOpacity = opacity
        if Hud.ShadowIsImage then Hud.Shadow.ImageTransparency = 1 - 0.55 * opacity
        else Hud.Shadow.BackgroundTransparency = 1 - 0.35 * opacity end
        if Hud.Rim then Hud.Rim.ImageTransparency = 1 - 0.5 * opacity end
        strokeHUD.Transparency = 1 - 0.18 * opacity
        Hud.AvatarStroke.Transparency = 1 - 0.14 * opacity
        Hud.HealthStroke.Transparency = 1 - 0.12 * opacity
        TargetIconContainer.BackgroundTransparency = 1 - 0.82 * opacity
        HealthBack.BackgroundTransparency = 1 - 0.88 * opacity
    end
    local radius = Nova.U.radiusMult or 1
    if Hud.DecorRadius ~= radius then
        Hud.DecorRadius = radius
        if Hud.Rim then Hud.Rim.Visible = radius > 0 end
        if Hud.Gloss then Hud.Gloss.Visible = radius > 0 end
    end
end

function Session:SyncHudAppearance()
    if not self.Alive then return end
    local textScale = Nova.U.textScale or 1
    -- A little extra width and height prevents large interface fonts clipping the HP row.
    local extra = math.max(0, math.ceil((textScale - 1) * 28))
    local width, height = 272 + extra * 2, 86 + extra
    TargetHUD.Size = UDim2.fromOffset(width, height)
    local avatarSize, left = 52, 76
    TargetIconContainer.Size = UDim2.fromOffset(avatarSize, avatarSize)
    TargetIconContainer.Position = UDim2.fromOffset(12, math.floor((height - avatarSize) / 2))
    Hud.Tag.Position = UDim2.fromOffset(left, 9)
    Hud.Tag.Size = UDim2.new(1, -(left + 12), 0, 13)
    TargetName.Position = UDim2.fromOffset(left, 24)
    TargetName.Size = UDim2.new(1, -(left + 12), 0, 21 + extra)
    HealthText.Position = UDim2.fromOffset(left, 47 + extra)
    HealthText.Size = UDim2.new(1, -(left + 12), 0, 16)
    HealthBack.Position = UDim2.fromOffset(left, height - 16)
    HealthBack.Size = UDim2.new(1, -(left + 12), 0, 5)
    local hudScale = tonumber(Cfg.TargetHudScale)
    if not hudScale or hudScale ~= hudScale or math.abs(hudScale) == math.huge then hudScale = 1 end
    local interfaceScale = window.Scale and window.Scale.Scale or window.OverlayScale or window.UserScale or 1
    Hud.Scale.Scale = interfaceScale * math.clamp(hudScale, 0.5, 2)
    self:SyncHudDecorations()
    self:RefreshHudPlacement()
end

function Session:SyncHudTheme()
    if self.ThemeRoot then self:SyncHudAppearance(); return end
    -- These Nova refresh roots affect theme/font/radius only; menu Close does not touch them.
    self.ThemeRoot = {Gui = NotificationGui, Destroyed = false}
    table.insert(Nova.Windows, 1, self.ThemeRoot)
    -- Nova's own brand-card pipeline applies the same opacity, card surface, gradients,
    -- background texture/intensity and accent as its watermark and launcher cards.
    window:_registerBrandCard(Hud.Card)
    Nova.Refresh.sync(TargetHUD)
    self:SyncHudAppearance()
    Session:Connect(Hud.Card:GetPropertyChangedSignal("BackgroundTransparency"), function()
        Session:SyncHudDecorations()
    end)
    Session:Connect(cornerHUD:GetPropertyChangedSignal("CornerRadius"), function()
        Session:SyncHudDecorations()
    end)
    Session:Connect(window.Scale:GetPropertyChangedSignal("Scale"), function()
        Session:SyncHudAppearance()
    end)
    Session:Connect(TargetName:GetPropertyChangedSignal("TextSize"), function()
        Session:SyncHudAppearance()
    end)
    -- Clamp on viewport changes even when the menu's computed scale is unchanged.
    function self:WatchHudCamera()
        if Hud.ViewportConnection then Hud.ViewportConnection:Disconnect() end
        local camera = workspace.CurrentCamera
        Hud.ViewportConnection = camera and Session:Connect(camera:GetPropertyChangedSignal("ViewportSize"), function()
            Session:RefreshHudPlacement()
        end) or nil
        Session:RefreshHudPlacement()
    end
    self:WatchHudCamera()
    Session:Connect(workspace:GetPropertyChangedSignal("CurrentCamera"), function()
        Session:WatchHudCamera()
    end)
end
Session:SyncHudTheme()

function Session:UpdateTargetHUD(target, dt)
    self:SyncHudDecorations()
    if self:IsFriend(target) then target = nil end
    dt = type(dt) == "number" and dt == dt and dt > 0 and dt < math.huge and dt or 0
    local character = target and target.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not Cfg.TargetHudEnabled or not humanoid or humanoid.Health <= 0 then
        Hud.PlacementCharacter = nil
        if TargetHUD.Visible then TargetHUD.Visible = false end
        lastTargetUserId, lastTargetHealth, Hud.LastMaxHealth = nil, nil, nil
        if currentTween then currentTween:Cancel(); currentTween = nil end
        if Hud.DragInput and not Cfg.TargetHudInPlayer then Cfg.TargetHudPosition = TargetHUD.Position; SaveLocalMAIN() end
        Hud.DragInput, Hud.DragStart, Hud.DragOrigin = nil, nil, nil
        return
    end
    Hud.PlacementCharacter = character
    TargetHUD.Visible = self:UpdateHudPlacement(character)
    local health, maximum = math.max(0, humanoid.Health), math.max(1, humanoid.MaxHealth)
    local fraction = math.clamp(health / maximum, 0, 1)
    local changedTarget = lastTargetUserId ~= target.UserId or Hud.Character ~= character
    local motion = Nova.Motion.enabled
    if changedTarget then
        if currentTween then currentTween:Cancel(); currentTween = nil end
        Hud.Character = character
        lastTargetUserId = target.UserId
        TargetName.Text = target.DisplayName
        TargetIcon.Image = "rbxthumb://type=AvatarHeadShot&id=" .. target.UserId .. "&w=150&h=150"
        TargetIcon.ImageColor3 = Color3.new(1, 1, 1)
        HealthBar.Size = UDim2.fromScale(fraction, 1)
        lastDamageTimeHUD = -math.huge
    elseif lastTargetHealth and health < lastTargetHealth then
        lastDamageTimeHUD = tick()
        if currentTween then currentTween:Cancel(); currentTween = nil end
        if motion then
            TargetIcon.ImageColor3 = Cfg.TargetHudDamageColor
            currentTween = Nova.Motion.tween(TargetIcon, TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {ImageColor3 = Color3.new(1, 1, 1)})
        end
    end
    if not motion then
        if currentTween then currentTween:Cancel(); currentTween = nil end
        TargetIcon.ImageColor3 = Color3.new(1, 1, 1)
    end
    if changedTarget or lastTargetHealth ~= health or Hud.LastMaxHealth ~= maximum then
        HealthText.Text = string.format("%.0f / %.0f HP", health, maximum)
        Hud.LastMaxHealth = maximum
    end
    lastTargetHealth = health
    local normalColor = Cfg.TargetHudSyncColor and Nova.Theme.tokens.Accent or Cfg.TargetHudNormalColor
    local elapsed = tick() - lastDamageTimeHUD
    local barColor = normalColor
    if elapsed < 0.3 then
        -- Disabling UI motion uses a static damage indicator with no interpolated animation.
        barColor = motion and Cfg.TargetHudDamageColor:Lerp(normalColor, elapsed / 0.3) or Cfg.TargetHudDamageColor
    end
    if lastTargetHudBarColor ~= barColor then
        lastTargetHudBarColor = barColor
        barGradient.Color = ColorSequence.new(barColor:Lerp(Color3.new(0, 0, 0), 0.16), barColor)
    end
    local current = HealthBar.Size.X.Scale
    local nextFraction = motion and (current + (fraction - current) * (1 - math.exp(-16 * math.max(dt, 0)))) or fraction
    if math.abs(nextFraction - fraction) < 0.001 then nextFraction = fraction end
    if nextFraction ~= current then HealthBar.Size = UDim2.fromScale(nextFraction, 1) end
end

function Session:Destroy()
    if not self.Alive then return end
    self:DestroyStretchScreen()
    self:DestroyAuraAttack()
    self:DestroyCharacterDiagnostics()
    if self.Flush then pcall(function() self:Flush() end) end
    self:ResetNoFall(true)
    self:DestroyNoFallScripts()
    self:ClearCharacterParts()
    self:ResetTargetLocks()
    self:DestroyWorldShader()
    self:DestroyBridgeViewmodel()
    self:DestroySoftCamera()
    self.Alive = false
    self:RefreshAimHooks()
    self:DestroyHitFeedback()
    self:ClearHitSounds()
    self:DestroyFriends()
    for sound in pairs(self.HitFeedbackSounds) do sound:Destroy() end
    table.clear(self.HitFeedbackSounds)
    self:ClearDamageNumbers(true)
    self:ClearHitSplashes()
    self:ClearWorldCubes()
    self:ClearJumpCircles()
    if currentTween then currentTween:Cancel(); currentTween = nil end
    if self.ThemeRoot then self.ThemeRoot.Destroyed = true end
    self.CharacterGeneration = (self.CharacterGeneration or 0) + 1
    local hooks = environment.__NotificationNovaHooks
    if hooks and hooks.Session == self then hooks.Session = nil end
    RunService:UnbindFromRenderStep(self.RenderName)
    for _, bucket in ipairs({self.Connections, self.CharacterConnections}) do
        for _, connection in ipairs(bucket) do pcall(function() connection:Disconnect() end) end
        table.clear(bucket)
    end
    local owners = {}
    for owner in pairs(self.Overrides) do table.insert(owners, owner) end
    for _, owner in ipairs(owners) do self:Release(owner) end
    self:RestoreAntiFling()
    self:RestoreAnimations()
    self:RestoreArms()
    self:RestoreHitboxes()
    for part, state in pairs(OrigNoClipStates) do if part.Parent then pcall(function() part.CanCollide = state end) end end
    self:RestoreArmJoints()
    for _, object in ipairs({NotificationGui, HatPart, ChamsFolder, Chams3DFolder, Session.WorldCubesFolder, self.Effects, SaturationEffect}) do
        pcall(function() object:Destroy() end)
    end
end

-- Platform: Roblox client / Luau; target: shared cosmetic attack and damage feedback.
do
    local records, tools = {}, {}
    local characterConnections, toolCharacter = {}, nil
    local activeTool, activeTarget, sampleTime = nil, nil, 0
    local bound, soundVersion, particleVersion = false, 0, 0
    local WINDOW, MAX_TARGETS, serial = 1.5, 32, 0
    Session.HitFeedbackTargets = records
    local function finite(n) return type(n) == "number" and n == n and math.abs(n) < math.huge end
    local function enabled() return Cfg.HitSoundEnabled or Cfg.DamageParticlesEnabled end
    local function damageMode()
        return (Cfg.HitSoundEnabled and Cfg.HitSoundOnDamage) or (Cfg.DamageParticlesEnabled and Cfg.HitParticlesOnDamage)
    end
    local function currentChannels(attack)
        return (attack.Sound and attack.SoundVersion == soundVersion and Cfg.HitSoundEnabled and Cfg.HitSoundOnDamage)
            or (attack.Particles and attack.ParticleVersion == particleVersion and Cfg.DamageParticlesEnabled and Cfg.HitParticlesOnDamage)
    end
    local function disconnect(bucket)
        for _, connection in ipairs(bucket) do connection:Disconnect() end
        table.clear(bucket)
    end
    local function drop(character)
        local record = records[character]
        if record then disconnect(record.Connections); records[character] = nil end
    end
    local function eligible(character)
        if not character or not character.Parent or character == LocalPlayer.Character or Session:IsFriendCharacter(character) then return false end
        local player = Players:GetPlayerFromCharacter(character)
        if player and player.Character ~= character then return false end
        return true
    end
    local function point(character)
        local part = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Head")
        return part and part:IsA("BasePart") and part.Position or nil
    end
    local function owner(character, humanoid)
        -- These are game conventions, not a universal Roblox damage-source API.
        for _, parent in ipairs({humanoid, character}) do
            for _, name in ipairs({"creator", "Creator", "attacker", "Attacker"}) do
                local tag = parent:FindFirstChild(name)
                if tag and tag:IsA("ObjectValue") then
                    local value = tag.Value
                    if value and (value == LocalPlayer or value == LocalPlayer.Character) then return true end
                    if value and (value:IsA("Player") or value:IsA("Model")) then return false end
                end
            end
        end
        return nil
    end
    local function expire(record)
        task.delay(WINDOW + 0.1, function()
            if not Session.Alive or records[record.Character] ~= record then return end
            if tick() - record.LastTime >= WINDOW or not eligible(record.Character) then drop(record.Character)
            else expire(record) end
        end)
    end
    local function watch(record)
        if record.Watching or not damageMode() then return end
        record.Watching = true
        local humanoid, character = record.Humanoid, record.Character
        record.Health = finite(humanoid.Health) and math.max(0, humanoid.Health) or nil
        Session:Connect(humanoid.HealthChanged, function(nextHealth)
            if records[character] ~= record then return end
            local previous = record.Health
            record.Health = finite(nextHealth) and math.max(0, nextHealth) or nil
            if not previous or not record.Health or record.Health >= previous or not damageMode() or not eligible(character) then return end
            local attack, now = nil, tick()
            while #record.Pending > 0 do
                local candidate = table.remove(record.Pending, 1)
                if now - candidate.Time <= WINDOW and currentChannels(candidate) then attack = candidate; break end
            end
            if not attack and activeTarget == character and activeTool and activeTool.Parent == LocalPlayer.Character then
                attack = {Time=now, Position=point(character), Sound=Cfg.HitSoundEnabled and Cfg.HitSoundOnDamage,
                    Particles=Cfg.DamageParticlesEnabled and Cfg.HitParticlesOnDamage, SoundVersion=soundVersion, ParticleVersion=particleVersion}
            end
            if not attack then return end
            local sourceOwner = owner(character, humanoid)
            -- Allow a creator tag replicated just after Health to arrive; the attack is consumed once.
            task.delay(0.03, function()
                if not Session.Alive or records[character] ~= record or not eligible(character)
                    or (record.Player and record.Player.Character ~= character)
                    or humanoid.Parent ~= character or character:FindFirstChildOfClass("Humanoid") ~= humanoid then return end
                local currentOwner = owner(character, humanoid)
                if currentOwner == false or (currentOwner == nil and sourceOwner == false) then return end
                if attack.Sound and attack.SoundVersion == soundVersion and Cfg.HitSoundEnabled and Cfg.HitSoundOnDamage then Session:PlayHitFeedback(character) end
                if attack.Particles and attack.ParticleVersion == particleVersion and Cfg.DamageParticlesEnabled and Cfg.HitParticlesOnDamage then
                    local position = point(character) or attack.Position
                    if position then Session:EmitHitSplash(position, attack.Normal, character) end
                end
            end)
        end, record.Connections)
    end
    function Session:RecordFeedbackAttack(character, position, normal, source)
        if not self.Alive or not enabled() or not eligible(character) then return false end
        local localCharacter = LocalPlayer.Character
        local localHumanoid = localCharacter and localCharacter:FindFirstChildOfClass("Humanoid")
        if not localCharacter or not localCharacter.Parent or not localHumanoid or localHumanoid.Health <= 0 then return false end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or not finite(humanoid.Health) or humanoid.Health <= 0 then return false end
        position = typeof(position) == "Vector3" and position or point(character)
        if not position then return false end
        source = source or "input"
        local record, now = records[character], tick()
        if record and record.Humanoid ~= humanoid then drop(character); record = nil end
        if not record then
            local count, oldest = 0, nil
            for _, entry in pairs(records) do
                count += 1
                if not oldest or entry.Serial < oldest.Serial then oldest = entry end
            end
            if count >= MAX_TARGETS and oldest then drop(oldest.Character) end
            serial += 1
            record = {Character=character, Player=Players:GetPlayerFromCharacter(character), Humanoid=humanoid,
                Connections={}, Pending={}, LastTime=now, Serial=serial}
            records[character] = record
            expire(record)
        end
        watch(record)
        record.LastTime = now
        if source == "held" then
            -- Holding a Tool only maintains damage observation; it never invents click feedback.
            if #record.Pending > 0 and now - record.Pending[#record.Pending].Time < 0.2 then return true end
        elseif record.LastAttack and now - record.LastAttack.Time < 0.06 and not record.LastAttack.Sources[source] then
            record.LastAttack.Sources[source] = true
            return true
        end
        local attack = {Time=now, Position=position, Normal=normal, Sources={[source]=true},
            SoundVersion=soundVersion, ParticleVersion=particleVersion,
            Sound=Cfg.HitSoundEnabled and Cfg.HitSoundOnDamage,
            Particles=Cfg.DamageParticlesEnabled and Cfg.HitParticlesOnDamage}
        if source ~= "held" then record.LastAttack = attack end
        if attack.Sound or attack.Particles then
            while #record.Pending >= 16 do table.remove(record.Pending, 1) end
            table.insert(record.Pending, attack)
        end
        if source ~= "held" then
            if Cfg.HitSoundEnabled and not Cfg.HitSoundOnDamage then self:PlayHitFeedback(character) end
            if Cfg.DamageParticlesEnabled and not Cfg.HitParticlesOnDamage then self:EmitHitSplash(position, normal, character) end
        end
        return true
    end
    function Session:CaptureFeedbackAttack(source)
        if not self.Alive or not enabled() or window.Listening or UserInputService:GetFocusedTextBox() or window:PointerOverUI() then return nil end
        local camera = workspace.CurrentCamera
        if not camera then return nil end
        local mouse = UserInputService:GetMouseLocation()
        local ray = camera:ScreenPointToRay(mouse.X, mouse.Y)
        local params = RaycastParams.new()
        params.FilterType, params.IgnoreWater = Enum.RaycastFilterType.Exclude, true
        local exclusions = {self.Effects}
        if LocalPlayer.Character then table.insert(exclusions, LocalPlayer.Character) end
        if self.WorldCubesFolder then table.insert(exclusions, self.WorldCubesFolder) end
        if Chams3DFolder then table.insert(exclusions, Chams3DFolder) end
        params.FilterDescendantsInstances = exclusions
        local hit = workspace:Raycast(ray.Origin, ray.Direction * 1000, params)
        local character = hit and hit.Instance
        while character and character ~= workspace do
            if character:IsA("Model") and character:FindFirstChildOfClass("Humanoid") then
                if self:RecordFeedbackAttack(character, hit.Position, hit.Normal, source) then return character end
                return nil
            end
            character = character.Parent
        end
        return nil
    end
    function Session:ResetHitFeedback()
        for character in pairs(records) do drop(character) end
        activeTarget = nil
    end
    function Session:PruneFriendlyFeedback()
        for character in pairs(records) do if not eligible(character) then drop(character) end end
        if activeTarget and not eligible(activeTarget) then activeTarget = nil end
    end
    local function removeTool(tool)
        if tools[tool] then disconnect(tools[tool]); tools[tool] = nil end
        if activeTool == tool then activeTool, activeTarget = nil, nil end
    end
    local function addTool(tool)
        if not tool:IsA("Tool") or tools[tool] then return end
        local bucket = {}; tools[tool] = bucket
        Session:Connect(tool.Activated, function()
            if tool.Parent ~= LocalPlayer.Character then return end
            activeTool = tool
            activeTarget = Session:CaptureFeedbackAttack("tool")
        end, bucket)
        Session:Connect(tool.Deactivated, function()
            if activeTool == tool then activeTool, activeTarget = nil, nil end
        end, bucket)
    end
    function Session:RefreshHitFeedback(key)
        if key == "HitSoundEnabled" or key == "HitSoundOnDamage" then soundVersion += 1 end
        if key == "DamageParticlesEnabled" or key == "HitParticlesOnDamage" then particleVersion += 1 end
        for _, record in pairs(records) do
            for i = #record.Pending, 1, -1 do
                if not currentChannels(record.Pending[i]) then table.remove(record.Pending, i) end
            end
        end
        if bound and toolCharacter == LocalPlayer.Character and enabled() then return end
        self:ResetHitFeedback()
        disconnect(characterConnections)
        for tool in pairs(tools) do removeTool(tool) end
        toolCharacter, activeTool, bound = LocalPlayer.Character, nil, false
        if not self.Alive or not enabled() or not toolCharacter then return end
        bound = true
        for _, tool in ipairs(toolCharacter:GetChildren()) do addTool(tool) end
        self:Connect(toolCharacter.ChildAdded, addTool, characterConnections)
        self:Connect(toolCharacter.ChildRemoved, removeTool, characterConnections)
    end
    function Session:DestroyHitFeedback()
        self:ResetHitFeedback()
        disconnect(characterConnections)
        for tool in pairs(tools) do removeTool(tool) end
        activeTool, toolCharacter, bound = nil, nil, false
    end
    Session:Connect(LocalPlayer.CharacterAdded, function() Session:RefreshHitFeedback() end)
    Session:Connect(LocalPlayer.CharacterRemoving, function() Session:DestroyHitFeedback() end)
    Session:Connect(Players.PlayerRemoving, function(player) if player.Character then drop(player.Character) end end)
    Session:Connect(UserInputService.InputBegan, function(input, processed)
        if not processed and input.UserInputType == Enum.UserInputType.MouseButton1 then Session:CaptureFeedbackAttack("input") end
    end)
    Session:Connect(UserInputService.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then activeTool, activeTarget = nil, nil end
    end)
    Session:Connect(RunService.Heartbeat, function(dt)
        if not activeTool or not damageMode() then return end
        if activeTool.Parent ~= LocalPlayer.Character then activeTool, activeTarget = nil, nil; return end
        sampleTime += dt
        if sampleTime >= 0.12 then
            sampleTime = 0
            activeTarget = Session:CaptureFeedbackAttack("held")
        end
    end)
end
-- End shared cosmetic hit feedback.


-- Platform: Roblox client / Luau; target: horizontal air movement with explicit movement precedence.
do
    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end
    function Session:GetAirStrafeVelocity(character, humanoid, root)
        if not self.Alive or not self.Ready or not Cfg.AirStrafeEnabled or character ~= LocalPlayer.Character
            or not character or not character.Parent or not humanoid or humanoid.Parent ~= character
            or not root or root.Parent ~= character or not root:IsA("BasePart") or root.Anchored
            or humanoid.Health <= 0 or humanoid.Sit or humanoid.SeatPart or humanoid.PlatformStand then return nil end
        local state = humanoid:GetState()
        local transition = state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.RunningNoPhysics
            or state == Enum.HumanoidStateType.Landed
        if state ~= Enum.HumanoidStateType.Jumping and state ~= Enum.HumanoidStateType.Freefall
            and not (transition and humanoid.FloorMaterial == Enum.Material.Air) then return nil end
        local direction, velocity = humanoid.MoveDirection, root.AssemblyLinearVelocity
        if not finite(direction.X) or not finite(direction.Y) or not finite(direction.Z)
            or not finite(velocity.X) or not finite(velocity.Y) or not finite(velocity.Z) then return nil end
        local flat = Vector3.new(direction.X, 0, direction.Z)
        if flat.Magnitude < 0.001 then return nil end
        local speed = tonumber(Cfg.AirStrafeSpeed)
        if not finite(speed) then speed = 30 end
        return flat.Unit * math.clamp(speed, 1, 500)
    end
end


-- Platform: Roblox client / Luau; target: reversible Bridge Duel camera sword presentation.
do
    local names = {woodensword=true, woodsword=true, stonesword=true, ironsword=true,
        goldsword=true, goldensword=true, diamondsword=true}
    local state = {Records={}, Connections={}, CameraConnections={}, ViewConnections={},
        Active=false, Stopped=false, Queued=false, Revision=0, Offset=Vector3.zero, Scale=1}
    Session.BridgeViewmodelState = state
    local beforeName, afterName = Session.RenderName .. "_BridgeViewmodelBefore", Session.RenderName .. "_BridgeViewmodelAfter"
    local function normalized(value) return string.lower(value):gsub("[^%w]", "") end
    local function finite(value, fallback, minimum, maximum)
        value = tonumber(value)
        if not value or value ~= value or math.abs(value) == math.huge then return fallback end
        return math.clamp(value, minimum, maximum)
    end
    local function disconnect(list)
        for _, connection in ipairs(list) do connection:Disconnect() end
        table.clear(list)
    end
    local function nearNumber(a, b) return math.abs(a - b) <= 0.00001 * math.max(1, math.abs(a), math.abs(b)) end
    local function nearVector(a, b) return (a - b).Magnitude < 0.00001 end
    local function nearFrame(a, b)
        return nearVector(a.Position, b.Position) and nearVector(a.LookVector, b.LookVector)
            and nearVector(a.UpVector, b.UpVector)
    end
    local function readPivot(record)
        return record.Model and record.Object:GetPivot() or record.Object.CFrame
    end
    local function writePivot(record, frame)
        if record.Model then record.Object:PivotTo(frame) else record.Object.CFrame = frame end
    end
    local function undoOffset(record)
        if not record.Applied then return end
        pcall(function()
            -- An absolute pose written by the game after our pass belongs to the game.
            if nearFrame(readPivot(record), record.Applied) then writePivot(record, record.Base) end
        end)
        record.Base, record.Applied = nil, nil
    end
    local function undoScale(record)
        if not record.AppliedScale then return end
        pcall(function()
            if record.Model then
                if nearNumber(record.Object:GetScale(), record.AppliedScale) then record.Object:ScaleTo(record.BaseScale) end
            elseif record.Mesh then
                if record.Mesh.Parent == record.Object then
                    if nearVector(record.Mesh.Scale, record.AppliedScale) then record.Mesh.Scale = record.BaseScale end
                    if nearVector(record.Mesh.Offset, record.AppliedMeshOffset) then record.Mesh.Offset = record.BaseMeshOffset end
                end
            elseif nearVector(record.Object.Size, record.AppliedScale) then
                record.Object.Size = record.BaseScale
                if record.OffsetMesh and record.OffsetMesh.Parent == record.Object
                    and nearVector(record.OffsetMesh.Offset, record.AppliedMeshOffset) then
                    record.OffsetMesh.Offset = record.BaseMeshOffset
                end
            end
        end)
        record.AppliedScale, record.AppliedMeshOffset, record.Factor = nil, nil, nil
    end
    local function restore(record) undoOffset(record); undoScale(record) end
    local function clearRecords()
        for object, record in pairs(state.Records) do restore(record); state.Records[object] = nil end
    end
    local function valid(record)
        return state.Camera == workspace.CurrentCamera and state.Viewmodel
            and state.Viewmodel.Parent == state.Camera and record.Object.Parent
            and record.Object:IsDescendantOf(state.Viewmodel)
    end
    local function applyScale(record)
        local factor = state.Scale
        if record.Factor == factor then return end
        undoScale(record)
        -- Capture the game's current baseline after releasing our previous scale.
        if record.Model then
            record.BaseScale = record.Object:GetScale()
            record.AppliedScale = record.BaseScale * factor
            record.Object:ScaleTo(record.AppliedScale)
            record.AppliedScale = record.Object:GetScale()
        elseif record.Mesh and record.Mesh.Parent == record.Object then
            record.BaseScale, record.BaseMeshOffset = record.Mesh.Scale, record.Mesh.Offset
            record.AppliedScale, record.AppliedMeshOffset = record.BaseScale * factor, record.BaseMeshOffset * factor
            record.Mesh.Scale, record.Mesh.Offset = record.AppliedScale, record.AppliedMeshOffset
        else
            record.BaseScale = record.Object.Size
            record.AppliedScale = record.BaseScale * factor
            record.Object.Size = record.AppliedScale
            if record.OffsetMesh and record.OffsetMesh.Parent == record.Object then
                record.BaseMeshOffset = record.OffsetMesh.Offset
                record.AppliedMeshOffset = record.BaseMeshOffset * factor
                record.OffsetMesh.Offset = record.AppliedMeshOffset
            end
        end
        record.Factor = factor
    end
    local function track(object)
        local record = {Object=object, Model=object:IsA("Model")}
        if not record.Model then
            local mesh = object:FindFirstChildOfClass("SpecialMesh")
            -- FileMesh geometry follows its mesh scale, not the surrounding Part.Size.
            if mesh and mesh.MeshType == Enum.MeshType.FileMesh then record.Mesh = mesh
            elseif mesh then record.OffsetMesh = mesh end
        end
        state.Records[object] = record
    end
    local discover
    local function queueDiscovery()
        if state.Queued or not state.Active or state.Stopped then return end
        state.Queued = true
        local revision = state.Revision
        task.defer(function()
            if state.Stopped or revision ~= state.Revision then return end
            state.Queued = false
            if state.Active then discover() end
        end)
    end
    local function setCamera(camera)
        if state.Camera == camera then return end
        clearRecords()
        disconnect(state.CameraConnections); disconnect(state.ViewConnections)
        state.Camera, state.Viewmodel = camera, nil
        if camera then
            table.insert(state.CameraConnections, camera.ChildAdded:Connect(queueDiscovery))
            table.insert(state.CameraConnections, camera.ChildRemoved:Connect(queueDiscovery))
        end
    end
    discover = function()
        if not state.Active then return end
        setCamera(workspace.CurrentCamera)
        local viewmodel
        if state.Camera then
            for _, child in ipairs(state.Camera:GetChildren()) do
                if normalized(child.Name) == "viewmodel" then viewmodel = child; break end
            end
        end
        if viewmodel ~= state.Viewmodel then
            clearRecords(); disconnect(state.ViewConnections)
            state.Viewmodel = viewmodel
            if viewmodel then
                table.insert(state.ViewConnections, viewmodel.DescendantAdded:Connect(queueDiscovery))
                table.insert(state.ViewConnections, viewmodel.DescendantRemoving:Connect(queueDiscovery))
            end
        end
        local found = {}
        if viewmodel then
            -- Walk this small visual subtree only; an equipped sword is treated as one unit.
            local pending, count = {viewmodel}, 0
            while #pending > 0 and count < 512 do
                local parent = table.remove(pending)
                for _, child in ipairs(parent:GetChildren()) do
                    count += 1
                    if names[normalized(child.Name)] and (child:IsA("Model") or child:IsA("BasePart")) then
                        found[child] = true
                    elseif count < 512 then
                        table.insert(pending, child)
                    end
                    if count >= 512 then break end
                end
            end
        end
        for object, record in pairs(state.Records) do
            if not found[object] then restore(record); state.Records[object] = nil end
        end
        for object in pairs(found) do
            local record = state.Records[object]
            if record and not record.Model then
                local mesh = object:FindFirstChildOfClass("SpecialMesh")
                if mesh ~= (record.Mesh or record.OffsetMesh) then
                    restore(record); state.Records[object] = nil
                end
            end
            if not state.Records[object] then track(object) end
        end
    end
    local function beforeRender()
        for _, record in pairs(state.Records) do undoOffset(record) end
    end
    local function afterRender()
        if not state.Active or not Session.Alive or not Session.PlaceSupport.Viewmodel or not Cfg.BridgeViewmodelEnabled then return end
        if workspace.CurrentCamera ~= state.Camera then discover() end
        local camera = state.Camera
        if not camera then return end
        local frame = camera.CFrame
        local offset = frame.RightVector * state.Offset.X + frame.UpVector * state.Offset.Y - frame.LookVector * state.Offset.Z
        for object, record in pairs(state.Records) do
            if not valid(record) then restore(record); state.Records[object] = nil; queueDiscovery()
            else
                local ok = pcall(function()
                    undoOffset(record)
                    applyScale(record)
                    if offset.Magnitude > 0.00001 then
                        record.Base = readPivot(record)
                        writePivot(record, record.Base + offset)
                        record.Applied = readPivot(record)
                    end
                end)
                if not ok then restore(record); state.Records[object] = nil end
            end
        end
    end
    local function deactivate()
        state.Active, state.Queued = false, false
        state.Revision += 1
        RunService:UnbindFromRenderStep(beforeName); RunService:UnbindFromRenderStep(afterName)
        clearRecords()
        disconnect(state.Connections); disconnect(state.CameraConnections); disconnect(state.ViewConnections)
        state.Camera, state.Viewmodel = nil, nil
    end
    function Session:RefreshBridgeViewmodel()
        if state.Stopped then return end
        local enabled = self.Alive and self.Ready ~= false and self.PlaceSupport.Viewmodel == true and Cfg.BridgeViewmodelEnabled == true
        if not enabled then deactivate(); return end
        state.Offset = Vector3.new(finite(Cfg.BridgeViewmodelX, 0, -2, 2), finite(Cfg.BridgeViewmodelY, 0, -2, 2),
            finite(Cfg.BridgeViewmodelZ, 0, -2, 2))
        state.Scale = finite(Cfg.BridgeViewmodelScale, 1, 0.5, 1.5)
        if not state.Active then
            state.Active = true
            table.insert(state.Connections, workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
                -- Release the previous camera's visual immediately, before the next render.
                setCamera(workspace.CurrentCamera); queueDiscovery()
            end))
            RunService:BindToRenderStep(beforeName, -1, beforeRender)
            RunService:BindToRenderStep(afterName, 2001, afterRender)
        end
        beforeRender(); discover()
    end
    function Session:DestroyBridgeViewmodel()
        if state.Stopped then return end
        deactivate(); state.Stopped = true
    end
end


-- Platform: Roblox client / Luau; target: detached, inert character ghost construction.
do
    function Session:BuildCosmeticGhost(character)
        if not self.Alive or not character or not character.Parent then return nil end
        local archivable = character.Archivable
        local ok, clone = pcall(function()
            character.Archivable = true
            return character:Clone()
        end)
        character.Archivable = archivable
        if not ok or not clone then return nil end
        local prepared = pcall(function()
            -- Never publish a live rig or runnable character scripts into Workspace.
            local descendants = clone:GetDescendants()
            for _, item in ipairs(descendants) do
                if item:IsA("LuaSourceContainer") or item:IsA("Script") or item:IsA("LocalScript")
                    or item:IsA("ModuleScript") or item:IsA("JointInstance") or item:IsA("Motor6D")
                    or item:IsA("Weld") or item:IsA("WeldConstraint") or item:IsA("Constraint")
                    or item:IsA("BodyMover") then item:Destroy() end
            end
            for _, item in ipairs(clone:GetDescendants()) do
                if item:IsA("Humanoid") or item:IsA("AnimationController") or item:IsA("Animator")
                    or item:IsA("ControllerManager") or item.Name == "HumanoidRootPart" then
                    item:Destroy()
                elseif item:IsA("BasePart") then
                    item.Anchored, item.Massless = true, true
                    item.CanCollide, item.CanQuery, item.CanTouch = false, false, false
                    item.LocalTransparencyModifier = 0
                end
            end
            clone.Name = "Notification_Ghost"
        end)
        if not prepared then clone:Destroy(); return nil end
        return clone
    end
end


-- Platform: Roblox client / Luau; target: bounded local character diagnostics, never server visibility.
do
    local state = {Started=false, Stopped=false, Generation=0, Connections={}}
    local function finite(n) return type(n) == "number" and n == n and math.abs(n) < math.huge end
    local function vector(v)
        return typeof(v) == "Vector3" and finite(v.X) and finite(v.Y) and finite(v.Z)
    end
    local function frame(v)
        return typeof(v) == "CFrame" and vector(v.Position) and vector(v.RightVector) and vector(v.UpVector) and vector(v.LookVector)
    end
    local function number(n) return finite(n) and string.format("%.3f", n) or "invalid" end
    function Session:CaptureCharacterDiagnostics(label)
        if not self.Alive or state.Stopped then return self.LatestCharacterDiagnostics or "Session ended; no character snapshot." end
        local active = {}
        for key in pairs(self.ToggleKeys) do if Cfg[key] == true then table.insert(active, key) end end
        table.sort(active)
        while #active > 96 do table.remove(active) end
        local character = LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root and not root:IsA("BasePart") then root = nil end
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local parts, hidden, localHidden, combinedHidden, joints, invalidJoints = 0, 0, 0, 0, 0, 0
        local queue, at, capped = character and {character} or {}, 1, false
        while at <= #queue do
            local object = queue[at]; at += 1
            if object:IsA("BasePart") then
                parts += 1
                local t, l = object.Transparency, object.LocalTransparencyModifier
                if finite(t) and t >= 0.99 then hidden += 1 end
                if finite(l) and l >= 0.99 then localHidden += 1 end
                if finite(t) and finite(l) and 1 - (1 - t) * (1 - l) >= 0.99 then combinedHidden += 1 end
            elseif object:IsA("JointInstance") or object:IsA("Motor6D") then
                joints += 1
                if not frame(object.C0) or not frame(object.C1) then invalidJoints += 1 end
            end
            for _, child in ipairs(object:GetChildren()) do
                if #queue >= 512 then capped = true; break end
                table.insert(queue, child)
            end
        end
        local position = root and root:IsA("BasePart") and root.Position
        local pos = vector(position) and (number(position.X) .. "," .. number(position.Y) .. "," .. number(position.Z)) or "missing/invalid"
        local humState = "missing"
        if humanoid then
            local ok, value = pcall(function() return humanoid:GetState().Name end)
            humState = ok and tostring(value) or "unavailable"
        end
        local text = string.format("local-only; server visibility unknown | %s | active=%s | character=%s parented=%s hp=%s state=%s | root=%s anchored=%s pos=%s frameFinite=%s | parts=%d transparencyHidden=%d localModifierHidden=%d effectiveHidden=%d joints=%d invalidJointFrames=%d scanned=%d capped=%s | hooksEnabled=%s hooksRequested=%s",
            tostring(label or "manual"):gsub("[\r\n]", " "):sub(1, 64), #active > 0 and table.concat(active, ",") or "none",
            tostring(character ~= nil), tostring(character ~= nil and character.Parent ~= nil), humanoid and number(humanoid.Health) or "missing", humState,
            tostring(root ~= nil), tostring(root ~= nil and root.Anchored == true), pos, tostring(root ~= nil and frame(root.CFrame)),
            parts, hidden, localHidden, combinedHidden, joints, invalidJoints, #queue, tostring(capped),
            tostring(self.HooksEnabled == true), tostring(self.AimHooksRequested == true))
        local attack = self.AuraAttackState or {}
        local function count(value) return finite(value) and tostring(math.floor(math.clamp(value, 0, 1000000000))) or "0" end
        local backend = tostring(attack.LastBackend or "none"):gsub("[\r\n]", " "):sub(1, 48)
        local errorText = tostring(attack.LastError or "none"):gsub("[\r\n]", " "):sub(1, 160)
        text ..= string.format(" | aura successful=%s failed=%s backend=%s pending=%s unreleased=%s error=%s",
            count(attack.SuccessfulDispatches), count(attack.FailedDispatches), backend,
            tostring(attack.Pending ~= nil), tostring(attack.Unreleased ~= nil), errorText)
        self.LatestCharacterDiagnostics = text
        local previousStage = Startup.Stage
        pcall(function() Startup:Mark("character.diagnostics " .. text) end)
        Startup.Stage = previousStage
        return text
    end
    local function schedule(character, label)
        state.Generation += 1
        state.Character = character
        local generation = state.Generation
        Session:CaptureCharacterDiagnostics(label)
        for _, seconds in ipairs({1, 5}) do
            task.delay(seconds, function()
                if Session.Alive and not state.Stopped and state.Generation == generation and LocalPlayer.Character == character then
                    Session:CaptureCharacterDiagnostics(label .. "+" .. tostring(seconds) .. "s")
                end
            end)
        end
    end
    function Session:StartCharacterDiagnostics()
        if not self.Alive or state.Started or state.Stopped then return end
        state.Started = true
        self:Connect(LocalPlayer.CharacterAdded, function(character) schedule(character, "character-added") end, state.Connections)
        self:Connect(LocalPlayer.CharacterRemoving, function(character)
            if state.Character == character then state.Generation += 1; state.Character = nil end
        end, state.Connections)
        schedule(LocalPlayer.Character, "ready")
    end
    function Session:DestroyCharacterDiagnostics()
        if state.Stopped then return end
        state.Stopped, state.Started = true, false
        state.Generation += 1
        for _, connection in ipairs(state.Connections) do connection:Disconnect() end
        table.clear(state.Connections)
        state.Character = nil
    end
end


-- Platform: Roblox client / Luau; target: horizontal screen stretch with owned camera restoration.
do
    local state = {Active = false, Factor = 1, Stopped = false}
    Session.StretchScreenState = state
    local beforeName, afterName = Session.RenderName .. "_StretchBefore", Session.RenderName .. "_StretchAfter"
    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end
    local function vectorFinite(value)
        return finite(value.X) and finite(value.Y) and finite(value.Z)
    end
    local function sameBasis(a, b)
        return a.RightVector == b.RightVector and a.UpVector == b.UpVector and a.LookVector == b.LookVector
    end
    local function owns(camera)
        return camera == state.Camera and state.Applied ~= nil and sameBasis(camera.CFrame, state.Applied)
    end

    function Session:GetStretchFactor(camera)
        if not self.Alive or not state.Active or Cfg.StretchScreenEnabled ~= true
            or camera ~= workspace.CurrentCamera then return 1 end
        return state.Factor
    end

    function Session:RestoreStretchScreen()
        local camera, base, applied = state.Camera, state.Base, state.Applied
        state.Camera, state.Base, state.Applied = nil, nil, nil
        if not camera or not base or not applied then return end
        pcall(function()
            local current = camera.CFrame
            if current == applied then
                camera.CFrame = base
            elseif sameBasis(current, applied) and vectorFinite(current.Position) then
                -- Preserve a later translation (including Soft Camera being disabled).
                camera.CFrame = base + (current.Position - applied.Position)
            end
        end)
    end

    function Session:UpdateStretchScreen()
        -- Also safe when invoked twice without the next early render pass.
        self:RestoreStretchScreen()
        local camera = workspace.CurrentCamera
        if not self.Alive or not self.Ready or not state.Active or not camera
            or Cfg.StretchScreenEnabled ~= true or state.Factor <= 1 then return end
        local base = camera.CFrame
        if not vectorFinite(base.Position) or not vectorFinite(base.RightVector)
            or not vectorFinite(base.UpVector) or not vectorFinite(base.LookVector) then return end
        if base.RightVector.Magnitude < 0.0001 or base.UpVector.Magnitude < 0.0001
            or base.LookVector.Magnitude < 0.0001 then return end
        -- Camera's transpose view transform: x/z expands by Factor; y/z is unchanged.
        -- All matrix components stay <= 1 for an ordinary orthonormal camera pose.
        local s = 1 / state.Factor
        local right, up, back = base.RightVector, base.UpVector * s, -base.LookVector * s
        local p = base.Position
        local stretched = CFrame.new(p.X, p.Y, p.Z,
            right.X, up.X, back.X, right.Y, up.Y, back.Y, right.Z, up.Z, back.Z)
        camera.CFrame = stretched
        state.Camera, state.Base, state.Applied = camera, base, camera.CFrame
    end

    function Session:ProjectToViewport(camera, position)
        local point, onScreen = camera:WorldToViewportPoint(position)
        local factor = self:GetStretchFactor(camera)
        if factor <= 1 then return point, onScreen end
        local viewport = camera.ViewportSize
        if not vectorFinite(point) or not finite(viewport.X) or not finite(viewport.Y)
            or viewport.X <= 0 or viewport.Y <= 0 then return point, false end
        if owns(camera) then
            -- Late UI refresh: projection already includes the stretch. Return normal
            -- camera depth so distance-based marker sizes do not grow by Factor too.
            point = Vector3.new(point.X, point.Y, point.Z * factor)
        else
            point = Vector3.new(viewport.X * 0.5 + (point.X - viewport.X * 0.5) * factor, point.Y, point.Z)
        end
        return point, point.Z > 0 and point.X >= 0 and point.X <= viewport.X and point.Y >= 0 and point.Y <= viewport.Y
    end

    local function deactivate()
        Session:RestoreStretchScreen()
        RunService:UnbindFromRenderStep(beforeName)
        RunService:UnbindFromRenderStep(afterName)
        if state.CameraConnection then state.CameraConnection:Disconnect(); state.CameraConnection = nil end
        state.Active, state.Factor = false, 1
    end

    function Session:RefreshStretchScreen()
        if state.Stopped then return end
        self:RestoreStretchScreen()
        local amount = tonumber(Cfg.StretchScreenAmount)
        local factor = (finite(amount) and math.clamp(amount, 100, 500) or 100) / 100
        if not self.Alive or not self.Ready or Cfg.StretchScreenEnabled ~= true or factor <= 1 then
            deactivate()
        else
            state.Factor = factor
            if not state.Active then
                state.Active = true
                state.CameraConnection = workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
                    self:RestoreStretchScreen()
                    self.PlayerVisualForce = true
                end)
                -- Restore before input, camera movement and Soft Camera; apply after
                -- the game camera, this script's aiming and the sword viewmodel.
                RunService:BindToRenderStep(beforeName, -2, function() self:RestoreStretchScreen() end)
                RunService:BindToRenderStep(afterName, 2003, function() self:UpdateStretchScreen() end)
            end
        end
        self.PlayerVisualForce = true
    end

    function Session:DestroyStretchScreen()
        if state.Stopped then return end
        deactivate()
        state.Stopped = true
    end
end


return Session
end

local defaults = {
    blur = true, tooltips = true, sidebarWidth = 199, base = "Midnight", size = {676,585}, radius = 0.45,
    font = "Roboto", accent = "595959", menuKey = "LeftControl", sidebarCollapsed = false, autoFit = true,
    opacity = 0.66, textScale = 1.12, bgIntensity = 1.13, volume = 1, bgStyle = "Grid", panel = "0c0c0c",
    motion = true, density = "Comfortable", groupLabels = false, scale = 0.74, sounds = true,
    cardStyle = "Frosted", serviceWatermark = true,
}
Startup:Mark("window.create.begin")
local window = Nova:CreateWindow({
    Accent = Color3.fromHex("595959"), Key = Enum.KeyCode.LeftControl, Size = Vector2.new(676,585),
    Scale = 0.74, SidebarWidth = 199, Density = "Comfortable", Base = "Midnight", CardStyle = "Frosted",
    Background = "Grid", GuiName = "NotificationNovaMenu", Blur = true, SearchText = "Search",
    StateFile = "MenuSettings/ui.json", StateDefaults = defaults,
})
Startup:Mark("window.create.ready")
window.Startup = Startup
environment.__NotificationNova = window
Startup:Mark("runtime.begin")
local session = StartNotification(window)
Startup:Mark("runtime.ready")
window.Runtime = session
window.OnDestroy = function()
    if window.Marquee then window.Marquee:Destroy() end
    session:Destroy()
    if environment.__NotificationNova == window then environment.__NotificationNova = nil end
end

local cfg, controls = session.Cfg, {}
local Http = Nova.Services.HttpService
local localPath = "MenuSettings/notification.json"
-- Read existing profiles once; new saves and exports use the current name.
local previousConfigKey = string.char(103,101,109,105,110,105)
local bindingAliases = {ctrl="LeftControl", control="LeftControl", shift="LeftShift", alt="LeftAlt", mb1="MouseButton1", mb2="MouseButton2", mb3="MouseButton3"}
local keyLookup = {}
for _, key in ipairs(Enum.KeyCode:GetEnumItems()) do keyLookup[key.Name:lower()] = key end
for _, name in ipairs({"MouseButton1","MouseButton2","MouseButton3"}) do keyLookup[name:lower()] = Enum.UserInputType[name] end
local function parseBind(value)
    if value == "None" or value == "" then return nil, true end
    if type(value) ~= "string" or #value > 32 then return nil, false end
    local key = value:lower()
    if bindingAliases[key] then key = bindingAliases[key]:lower() end
    -- Migrate old MB1 bindings to unbound; left click is reserved for UI editing.
    if key == "mousebutton1" then return nil, true end
    local enum = keyLookup[key]
    if not enum or enum == Enum.KeyCode.Unknown or enum == Enum.KeyCode.Escape or enum == Enum.KeyCode.Backspace or enum == Enum.KeyCode.Delete then return nil, false end
    return enum, true
end
local function finite(value) return type(value) == "number" and value == value and math.abs(value) < math.huge end
local function isTeamKey(key)
    return type(key) == "string" and #key <= 200 and (key:match("^AimbotIgnore_.+") or key:match("^Esp2DBoxIgnore_.+") or key:match("^ChamsIgnore_.+")) ~= nil
end

local function encodeFeatures()
    local values = {}
    for key, value in pairs(cfg) do
        if key == "Friends" then values[key] = session:CopyFriends()
        elseif typeof(value) == "Color3" then values[key] = {type="Color3", r=value.R, g=value.G, b=value.B}
        elseif typeof(value) == "UDim2" then values[key] = {type="UDim2", xs=value.X.Scale, xo=value.X.Offset, ys=value.Y.Scale, yo=value.Y.Offset}
        else values[key] = value end
    end
    return {version=1, values=values}
end

-- Validate the entire payload before changing either the menu or the runtime.
local function decodeFeatures(doc)
    if type(doc) ~= "table" or doc.version ~= 1 or type(doc.values) ~= "table" then return nil, "Invalid Notification config." end
    local out = table.clone(session.Defaults)
    out.Friends = {}
    local count = 0
    for key, value in pairs(doc.values) do
        count += 1
        if count > 2000 or type(key) ~= "string" or #key > 240 then return nil, "Config is too large or has invalid keys." end
        local default = session.Defaults[key]
        local teamBind = key:sub(-4) == "Bind" and isTeamKey(key:sub(1,-5))
        if default ~= nil or isTeamKey(key) or teamBind then
            local range = NumberRanges[key]
            if key == "Friends" then
                local friends, message = session:ValidateFriends(value)
                if not friends then return nil, message end
                out.Friends = friends
            elseif key:sub(-4) == "Bind" then
                local enum, valid = parseBind(value)
                if not valid then return nil, "Invalid keybind: " .. key end
                out[key] = enum and enum.Name or "None"
            elseif range then
                if not finite(value) then return nil, "Invalid number: " .. key end
                local factor = 10 ^ range[3]
                out[key] = math.floor(math.clamp(value,range[1],range[2])*factor+0.5)/factor
            elseif typeof(default) == "Color3" then
                if type(value) ~= "table" or value.type ~= "Color3" then return nil, "Invalid color: " .. key end
                for _, component in ipairs({"r","g","b"}) do
                    if not finite(value[component]) or value[component] < 0 or value[component] > 1 then return nil, "Invalid color: " .. key end
                end
                out[key] = Color3.new(value.r,value.g,value.b)
            elseif typeof(default) == "UDim2" then
                if type(value) ~= "table" or value.type ~= "UDim2" then return nil, "Invalid position: " .. key end
                for _, component in ipairs({"xs","xo","ys","yo"}) do if not finite(value[component]) then return nil, "Invalid position: " .. key end end
                out[key] = UDim2.new(math.clamp(value.xs,-1,2),math.clamp(value.xo,-10000,10000),math.clamp(value.ys,-1,2),math.clamp(value.yo,-10000,10000))
            elseif type(default) == "boolean" or isTeamKey(key) then
                if type(value) ~= "boolean" then return nil, "Invalid toggle: " .. key end
                out[key] = value
            else
                return nil, "Unsupported setting: " .. key
            end
        end
    end
    return out
end

function session:Flush()
    if not self.Alive then return false, "Session is closed." end
    self.SaveVersion = (self.SaveVersion or 0) + 1
    if type(writefile) ~= "function" then return false, "File saving is unavailable in this environment." end
    local ok, err = pcall(function()
        if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder("MenuSettings") then makefolder("MenuSettings") end
        writefile(localPath, Http:JSONEncode(encodeFeatures()))
    end)
    self.LastSaveError = if ok then nil else tostring(err)
    return ok, ok and "Saved locally." or tostring(err)
end
function session:Save()
    self.SaveVersion = (self.SaveVersion or 0) + 1
    local generation = self.SaveVersion
    task.delay(0.6,function()
        if self.Alive and self.SaveVersion == generation then self:Flush() end
    end)
end
local syncing = false
local function syncControls()
    syncing = true
    for key, control in pairs(controls) do
        control:SetSilent(cfg[key])
        if control.Bind then
            local bind = parseBind(cfg[key .. "Bind"] or "None")
            control.Bind.Set(bind, true)
        end
    end
    syncing = false
    window:_kbDirty()
end
local function applyFeatures(values)
    session.PlaceSupport.Normalize(values)
    local changed = {}
    for key, value in pairs(values) do
        if cfg[key] ~= value then changed[key] = true end
    end
    -- Clear removed dynamic team fields so loading/resetting a config is deterministic.
    for key in pairs(cfg) do if isTeamKey(key) and values[key] == nil then cfg[key] = key:sub(-4) == "Bind" and "None" or false end end
    for key, value in pairs(values) do cfg[key] = value end
    for key in pairs(changed) do session:Changed(key) end
    syncControls()
end
local function notify(text, kind)
    if not window.Destroyed then window:Notify({Title="notification", Text=text, Kind=kind or "info", Duration=3}) end
end
local refreshAimHooks = session.RefreshAimHooks
function session:RefreshAimHooks()
    local enabled, message, attempted = refreshAimHooks(self)
    if attempted and not enabled then notify(message, "warning") end
    return enabled, message, attempted
end

local localLoadError
if type(isfile) == "function" and type(readfile) == "function" then
    local ok, raw = pcall(function()
        if isfile(localPath) then return readfile(localPath) end
        local previousPath = "MenuSettings/" .. previousConfigKey .. ".json"
        return isfile(previousPath) and readfile(previousPath) or nil
    end)
    if ok and raw then
        if #raw <= 131072 then
            local decoded, data = pcall(Http.JSONDecode,Http,raw)
            if decoded then
                local values, err = decodeFeatures(data)
                if values then applyFeatures(values) else localLoadError = err end
            else localLoadError = "Local config contains invalid JSON." end
        else localLoadError = "Local config is too large." end
    elseif not ok then localLoadError = "Local config could not be read." end
end

local baseExport = window.ExportConfig
local baseApply = window.ApplyConfig
function window:ExportConfig()
    local doc = baseExport(self)
    doc.notification = encodeFeatures()
    return doc
end
function window:ApplyConfig(doc)
    local appearance, err = Nova.Config.validate(doc)
    if not appearance then return false, err end
    local values
    local featureDoc = doc.notification
    if featureDoc == nil then featureDoc = doc[previousConfigKey] end
    if featureDoc ~= nil then
        values, err = decodeFeatures(featureDoc)
        if not values then return false, err end
    end
    local backup = self:ExportConfig()
    local ok, why = baseApply(self, doc)
    if not ok then return false, why end
    if values then
        local applied, failure = pcall(applyFeatures, values)
        if not applied then
            pcall(function() self:_applyConfigValues(backup.settings) end)
            local old = decodeFeatures(backup.notification)
            if old then pcall(applyFeatures,old) end
            return false, "Config could not be applied: " .. tostring(failure)
        end
    end
    -- The menu key is reserved; an imported config cannot toggle a feature with it.
    for key in pairs(session.ToggleKeys) do
        if self.Key and cfg[key .. "Bind"] == self.Key.Name then cfg[key .. "Bind"] = "None" end
    end
    syncControls()
    session:Save()
    return true
end

local tabs = {}
tabs.Combat = window:Tab({Name="Combat", Icon="notification-combat"})
tabs.Visuals = window:Tab({Name="Visuals", Icon="notification-visuals"})
tabs.Movement = window:Tab({Name="Movement", Icon="notification-movement"})
tabs.Visuals:SubTabs({"Players", "World", "Camera", "Effects"})

local function setValue(key,value)
    if syncing or not session.Alive then return end
    if cfg[key] == value then return end
    cfg[key] = value
    session:Changed(key)
    session:Save()
end
local function toggle(section,name,key)
    session.ToggleKeys[key] = session.ToggleKeys[key] or name
    if cfg[key] == nil then cfg[key] = false end
    cfg[key.."Bind"] = cfg[key.."Bind"] or "None"
    local keybind = parseBind(cfg[key.."Bind"])
    if keybind == window.Key then keybind = nil; cfg[key.."Bind"] = "None" end
    local control
    control = section:Toggle({
        Text = name, Default = cfg[key], Bind = true, Keybind = keybind,
        Callback = function(value) setValue(key,value) end,
        OnBind = function(value)
            if syncing then return end
            if value == Enum.UserInputType.MouseButton1 then value = nil; control.Bind.Set(nil, true) end
            if value and value == window.Key then
                control.Bind.Set(nil, true)
                cfg[key.."Bind"] = "None"
                notify("This key opens the menu. Choose a different feature key.", "warning")
            else
                cfg[key.."Bind"] = value and value.Name or "None"
                if value then
                    for other in pairs(session.ToggleKeys) do
                        if other ~= key and cfg[other.."Bind"] == value.Name then
                            notify("Shared key: " .. Nova.keyName(value) .. ". Both toggles will switch together.", "warning")
                            break
                        end
                    end
                end
            end
            session:Save()
        end,
    })
    controls[key] = control
    return control
end

Startup:Mark("controls.begin")
local teamSections = {}
for _, feature in ipairs(FeatureSchema) do
    local section = tabs[feature.Tab]:Section({Title=feature.Name, Sub=feature.Sub ~= "" and feature.Sub or nil})
    toggle(section, feature.Name, feature.Key)
    if feature.Key == "HitSoundEnabled" or feature.Key == "DamageParticlesEnabled" then
        section:Label({Text="On Damage Dealt waits for health loss after your attack. Attacker tags are checked when available; otherwise attribution is estimated.", Size=11, Color="Muted"})
    end
    if feature.Key == "NoFallEnabled" then
        section:Label({Text="Matches dedicated local fall scripts by name. Server damage and combined controllers may remain active.", Size=11, Color="Muted"})
        local status = section:Label({Text=session:GetNoFallScriptStatus(), Size=11, Color="Muted"})
        session.NoFallStatusChanged = function(text)
            if not window.Destroyed then status:SetText(text) end
        end
        section:Button({Text="Rescan local fall scripts", Callback=function() session:RefreshNoFallScripts() end})
    end
    if feature.Key == "KillAuraEnabled" and session.PlaceSupport.NoCamRotate then
        if session.PlaceSupport.NoCamRotate == "InternalCamera" then
            section:Label({Text="No Cam Rotate uses this place's internal camera profile. Camera modules keep their own view; aim hooks connect automatically.", Size=11, Color="Muted"})
        else
            section:Label({Text="No Cam Rotate connects aim hooks automatically. Camera input and wall collision stay unchanged.", Size=11, Color="Muted"})
        end
    end
    if feature.Key == "BridgeViewmodelEnabled" then
        section:Label({Text="Adjusts the sword under Camera / Viewmodel. Offsets are camera-relative; disabling restores the original viewmodel.", Size=11, Color="Muted"})
    end
    if feature.Key == "StretchScreenEnabled" then
        section:Label({Text="100% = normal view. Higher values stretch the world horizontally, up to 500%.", Size=11, Color="Muted"})
    end
    for _, option in ipairs(feature.Options) do
        local key = option.Key
        if option.Kind == "Toggle" then toggle(section,option.Name,key)
        elseif option.Kind == "Slider" then
            local range = assert(NumberRanges[key], "Missing range: " .. key)
            if key == "JitterYawMode" or key == "HitSoundMode" or key == "WorldCubeTexture" or key == "TargetHudSide" then
                local options
                if key == "TargetHudSide" then
                    options = {{value=1,label="Right"},{value=2,label="Left"}}
                elseif key == "WorldCubeTexture" then
                    options = {{value=1,label="Aurora"},{value=2,label="Hologram"},{value=3,label="Cosmic"},{value=4,label="Prism"}}
                elseif key == "JitterYawMode" then options = {{value=1,label="Forward"},{value=2,label="Backward"}}
                else options = GetHitSoundOptions() end
                controls[key] = section:Dropdown({Text=option.Name, Options=options, Default=cfg[key], Callback=function(value) setValue(key,value) end})
            else
                controls[key] = section:Slider({Text=option.Name, Min=range[1], Max=range[2], Decimals=range[3], Default=cfg[key], Callback=function(value) setValue(key,value) end})
            end
        elseif option.Kind == "Color" then
            controls[key] = section:Colorpicker({Text=option.Name, Default=cfg[key], Alpha=false, Callback=function(value) setValue(key,value) end})
        end
    end
    if feature.Teams then table.insert(teamSections,{Section=section, Prefix=feature.Teams, Controls={}}) end
end

local function refreshTeams()
    for _, entry in ipairs(teamSections) do
        local current = {}
        for _, team in ipairs(game:GetService("Teams"):GetChildren()) do
            if team:IsA("Team") then
                local key = entry.Prefix .. team.Name
                current[key] = true
                if not entry.Controls[key] then entry.Controls[key] = toggle(entry.Section,'Ignore "'..team.Name..'" team',key) end
                entry.Controls[key]:SetVisible(true)
            end
        end
        for key, control in pairs(entry.Controls) do control:SetVisible(current[key] == true) end
    end
end
local function watchTeam(team)
    if not team:IsA("Team") then return end
    session:Connect(team:GetPropertyChangedSignal("Name"),refreshTeams)
end
for _, team in ipairs(game:GetService("Teams"):GetChildren()) do watchTeam(team) end
session:Connect(game:GetService("Teams").ChildAdded,function(team) watchTeam(team); refreshTeams() end)
session:Connect(game:GetService("Teams").ChildRemoved,refreshTeams)
refreshTeams()

-- One input dispatcher for all Notification toggles; the menu owns key capture and the bind list.
session:Connect(Nova.Services.UserInputService.InputBegan,function(input,processed)
    if processed or window.Listening or Nova.Services.UserInputService:GetFocusedTextBox() then return end
    if window.Key and input.KeyCode == window.Key then return end
    for key in pairs(session.ToggleKeys) do
        local control = controls[key]
        if control and control.Bind and Nova.bindHit(window,input,control.Bind.Key,processed) then control:Set(not cfg[key]) end
    end
end)
window:OnKeyChanged(function(key)
    if not session.Alive then return end
    local changed = false
    for name in pairs(session.ToggleKeys) do
        if key and cfg[name.."Bind"] == key.Name then cfg[name.."Bind"] = "None"; changed = true end
    end
    if changed then syncControls(); session:Save(); notify("Feature bindings using the new menu key were cleared.", "warning") end
end)

local settings = window:Tab({Name="Settings", Icon="settings"})
window:AddAppearance(settings,{})
local performance = settings:Section({Title="Performance", Icon="settings"})
toggle(performance,"Low-end PC mode","LowEndMode")
performance:Label({Text="Caps cosmetic effects: 40 cubes at 30 Hz, 64 droplets, 24 segments per jump ring. Combat and camera updates keep their normal rate.", Size=11, Color="Muted"})
local configs = window:Tab({Name="Config", Icon="file-cog", Columns=1})
window:AddConfigs(configs)
local localSection = configs:Section({Title="Local Notification config", Icon="save"})
localSection:Label({Text="Feature values and keybinds save automatically on this device. Shared keys include the menu appearance and all Notification settings. Old appearance-only keys still work.",Size=12})
localSection:Button({Text="Save now",Icon="save",Callback=function()
    local ok, message = session:Flush()
    notify(message,ok and "success" or "warning")
end})
localSection:Button({Text="Copy diagnostics",Icon="copy",Callback=function()
    session:CaptureCharacterDiagnostics("manual")
    local text = table.concat(Startup.Lines, "\n")
    if type(setclipboard) == "function" and pcall(setclipboard, text) then
        notify("Diagnostics copied. Character visibility is measured locally only.", "success")
    else
        notify("Diagnostics saved to the startup log. In Studio, open Launcher Logs.", "info")
    end
end})
localSection:Button({Text="Reset feature settings",Icon="rotate-ccw",Callback=function()
    applyFeatures(table.clone(session.Defaults))
    session:Save()
    notify("Notification values and keybinds reset.","success")
end})
localSection:Label({Text="Bind: click the key chip, then press a keyboard key or MB2–MB3. Click a bind to edit; click it again to clear. Left mouse cannot be assigned. Escape cancels; Backspace / Delete clears. Menu key stays out of Keybind List; the launcher keeps an unbound menu accessible.",Size=12})
Nova.AddFriendManager(window, session)
syncControls()
window:SelectTab(tabs.Combat)
Startup:Mark("menu.open.begin")
window:Open()
Startup:Mark("menu.open.ready")
if localLoadError then notify(localLoadError,"warning") end
Startup:Mark("marquee.begin")
Nova.StartMarquee(window, {window.Gui, window.Parking, session.OverlayGui})
Startup:Mark("startup.ready")
session.Ready = true
session:StartCharacterDiagnostics()
session:RefreshAimHooks()
session:RefreshBridgeViewmodel()
session:RefreshStretchScreen()
session:RefreshHitFeedback()
if cfg.HitSoundEnabled then session:PrepareHitSound() end
session:RefreshNoFallScripts()
return window
